}

void log(const char* format, ...) {
    // Check if the buffer is full
    if (log_buffer_used == log_buffer_size) {
        flush();
    }

    // Format the message using snprintf
    va_list args;
    va_start(args, format);
    int n = vsnprintf(log_buffer + log_buffer_used, log_buffer_size - log_buffer_used, format, args);
    if (n > 0) {
        log_buffer_used += n;
    }
    va_end(args);
}

void flush() {
    // Check if the buffer is empty
    if (log_buffer_used == 0) {
        return;
    }

    // Send the log message to the cloud logging service using curl
    CURL* curl = curl_easy_init();
    if (curl != NULL) {
        struct curl_slist* header_chunk = NULL;
        header_chunk = curl_slist_append(header_chunk, "Content-Type: application/json");
        char* post_data = malloc(log_buffer_used + 1);
        strcpy(post_data, log_buffer);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, log_buffer_used);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, header_chunk);
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            printf("Error: failed to send log message (%d)\n", res);
        }
        curl_slist_free_all(header_chunk);
        free(post_data);
    }
    curl_easy_cleanup(curl);

    // Reset the buffer
    log_buffer_used = 0;
}

void cleanup() {
    // Release memory
    if (log_buffer != NULL) {
        free(log_buffer);
    }
    if (curl_handle != NULL) {
        curl_easy_cleanup(curl_handle);
    }
}
