#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

#define NUM_THREADS 100
#define MAX_RETRY_COUNT 3

// Define the shared resource as a global variable
int shared_resource;

// Define the semaphore for controlling access to the shared resource
sem_t *sem;

// Function for acquiring the semaphore and incrementing the shared resource
void *acquire_and_increment(void *arg) {
  int thread_id = (int) arg;
  int retry_count = 0;

  while (retry_count < MAX_RETRY_COUNT) {
    if (sem_wait(sem)) {
      perror("sem_wait");
      exit(1);
    }

    // Increment the shared resource
    shared_resource++;

    printf("Thread %d: Shared resource = %d\n", thread_id, shared_resource);

    if (sem_post(sem)) {
      perror("sem_post");
      exit(1);
    }

    retry_count++;
  }

  pthread_exit(NULL);
}

int main() {
  int i;
  pthread_t threads[NUM_THREADS];

  // Initialize the semaphore to 0
  if (sem_init(&sem, 0, 1)) {
    perror("sem_init");
    exit(1);
  }

  for (i = 0; i < NUM_THREADS; i++) {
    if (pthread_create(&threads[i], NULL, acquire_and_increment, (void *) i)) {
      perror("pthread_create");
      exit(1);
    }
  }

  for (i = 0; i < NUM_THREADS; i++) {
    if (pthread_join(threads[i], NULL)) {
      perror("pthread_join");
      exit(1);
    }
  }

  // Clean up the semaphore
  if (sem_destroy(&sem)) {
    perror("sem_destroy");
    exit(1);
  }

  return 0;
}']

