            return dist(mt) % (max - min + 1) + min;
        }

        // Function to generate a random floating-point number in a specified range
        float getRandomFloat(float min, float max) {
            std::lock_guard<std::mutex> lock(mux);
            return dist(mt) % (max - min + 1) + min;
        }

    private:
        // Mutex to ensure thread-safe access to the generator state
        std::mutex mux;

        // Generator state, which is stored in a separate struct to make it easier to share between threads
        GeneratorState state;

        // Condition variable to signal when a new random number has been generated
        std::condition_variable cv;
    };

