```
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
const writeFileAsync = promisify(fs.writeFile);
const log = require('loglevel');

// Define the directory to process files from
const fileDirectory = '/path/to/files';

// Define the criteria for filtering files
const fileExtensions = ['txt', 'pdf'];
const maxFileSize = 1024 * 1024; // 1 MB
const lastModifiedDate = new Date();

// Define a function to process a single file
async function processFile(filePath) {
  try {
    const fileData = await readFileAsync(filePath);
    if (fileData.length > maxFileSize) {
      log.warn(`${filePath} is too large, skipping`);
      return;
    }
    // TODO: Add additional filtering criteria here

    // Write the filtered file to a new location
    const outputFilePath = path.join(fileDirectory, `${path.basename(filePath)}.filtered`);
    await writeFileAsync(outputFilePath, fileData);
  } catch (error) {
    log.error(`Error processing ${filePath}:`, error);
  }
}

// Define a function to process all files in the directory
async function processFiles() {
  try {
    const files = await fs.readdir(fileDirectory);
    for (const file of files) {
      if (path.extname(file) === '.') {
        continue; // Skip hidden files
      }
      const filePath = path.join(fileDirectory, file);
      await processFile(filePath);
    }
  } catch (error) {
    log.error(`Error processing directory ${fileDirectory}:`, error);
  }
}

// Define a function to handle system dependencies and integrate with a third-party logging service
async function startService() {
  try {
    await processFiles();
  } catch (error) {
    log.error(`Error processing files:`, error);
  }
}

// Start the service
startService();
```
