// Import dependencies
import axios from 'axios';
import { countBy } from 'lodash';

// Define API endpoints and validation rules
const apiEndpoint = 'https://bible-api.com/api/v2/search?q=';
const validationRules = {
  dialogFieldId: 'required',
  resourceId: 'required',
};

// Define the refreshDialogFields function
function refreshDialogFields(dialogFieldId, resourceId) {
  // Validate input parameters
  if (!validationRules.dialogFieldId || !validationRules.resourceId) {
    throw new Error('Invalid input parameters');
  }

  // Fetch dialog field data from API endpoint
  const response = await axios.get(apiEndpoint + resourceId);
  const dialogFieldData = response.data;

  // Extract book names from dialog field content
  const bookNames = [];
  dialogFieldData.forEach((field) => {
    if (field.dialog_field_id === dialogFieldId) {
      const regex = /\b[A-Z][a-z']+/g; // matches whole words
      const matchArray = field.content.match(regex);
      if (matchArray) {
        bookNames.push(...matchArray);
      }
    }
  });

  // Count book names and return results as an object
  const bookCounts = countBy(bookNames);

  // Return final state of dialog fields and extracted book counts
  return {
    dialogFields: dialogFieldData,
    bookCounts,
  };
}
```
