    return response.data;
  } catch (error) {
    console.error('Error fetching data from API:', error);
    return null;
  }
};

const generateVirtualDOM = async (htmlDocument, apiData) => {
  const virtualDom = [];

  // Iterate through the HTML document and extract relevant data
  htmlDocument.querySelectorAll('body').forEach(node => {
    if (!node.hasAttribute('data-api')) return;

    const apiUrl = node.getAttribute('data-api');
    const apiParams = JSON.parse(node.getAttribute('data-params'));

    // Fetch data from API and add it to the virtual DOM
    const data = await getDataFromAPI(apiUrl, apiParams);
    if (data) {
      node.removeAttribute('data-api');
      node.removeAttribute('data-params');
      node.innerHTML = data;
      virtualDom.push(node);
    }
  });

  return virtualDom;
};

const updateVirtualDOM = async (virtualDom, apiData) => {
  // Update the virtual DOM with new data from the API
  for (let i = 0; i < virtualDom.length; i++) {
    const node = virtualDom[i];
    const apiUrl = node.getAttribute('data-api');
    const apiParams = JSON.parse(node.getAttribute('data-params'));

    // Fetch data from API and update the node with new data
    const data = await getDataFromAPI(apiUrl, apiParams);
    if (data) {
      node.innerHTML = data;
    } else {
      // Handle error case when data is null or undefined
      console.error('Error updating virtual DOM:', 'No data found for API');
    }
  }
};

