    let packages: HashMap<String, Package> = json["packages"]
        .as_array()
        .map(|packages| {
            packages
                .iter()
                .map(|package| {
                    let name = package["name"].as_str().unwrap();
                    let version = package["version"].as_str().unwrap();
                    (name, Package { name, version })
                })
                .collect()
        })
