        Ok(parsed_files)
    }

    fn parse_certificates_and_private_keys(paths: &[PathBuf]) -> Result<Vec<Certificate>, Error> {
        let parsed_files = validate_and_parse_files(paths)?;
        let mut certificates = Vec::new();

        for (certificate_data, private_key_data) in parsed_files {
