        for certificate in certificates {
            // TODO: Generate LLVM IR code for the parsed cryptographic structures using a rate limiter to prevent resource exhaustion
            let cert = certificate.certificate.clone();
            let key = certificate.private_key.clone();

            llvm_code.push_str(&generate_llvm_ir(&cert, &key));
