            } catch (Exception e) {
                LOG.error("Error while applying filter " + filter.getKey() + ": " + ExceptionUtils.getStackTrace(e));
            }
        }

        // Cache the transaction if necessary
        if (!this.transactionCache.containsKey(deserializedTransaction.getId())) {
            this.transactionCache.put(deserializedTransaction.getId(), new ArrayList<>());
        }
        this.transactionCache.get(deserializedTransaction.getId()).add(deserializedTransaction);
    }

