namespace DynamicRandomValueProvider
{
    public class DynamicRandomValueProvider
    {
        // Define a structure to store the state of each random number generator
        private struct RandomNumberGeneratorState
        {
            public int Seed;
            public long Next;
            public bool IsInitialized;
        }

        // Define a dictionary to map each external dependency to its state
        private Dictionary<string, RandomNumberGeneratorState> _externalDependencies = new Dictionary<string, RandomNumberGeneratorState>();

        // Define the strategy pattern for selecting random number generation algorithms
        private Func<RandomNumberGeneratorState, int> _randomNumberGenerationAlgorithm;

        // Define a range of values that can be generated by this class
        private Range<int> _range = new Range<int>();

        // Define a list of available random number generation algorithms
        private readonly List<string> _availableRandomNumberGenerationAlgorithms = new List<string>() { "LinearCongruential", "MersenneTwister" };

        // Define the default random number generation algorithm
        private const string DEFAULT_RANDOM_NUMBER_GENERATION_ALGORITHM = "LinearCongruential";

        public DynamicRandomValueProvider()
        {
            _randomNumberGenerationAlgorithm = SelectRandomNumberGenerationAlgorithm(DEFAULT_RANDOM_NUMBER_GENERATION_ALGORITHM);
        }

        public int GetNextInteger(int exclusiveUpperBound)
        {
            return (int)(GetNextFloat() * exclusiveUpperBound);
        }

        public float GetNextFloat()
        {
            // Generate a random number using the current algorithm and seed
            RandomNumberGeneratorState state = _externalDependencies.GetValueOrDefault(DEFAULT_RANDOM_NUMBER_GENERATION_ALGORITHM, new RandomNumberGeneratorState());
            int randNum = _randomNumberGenerationAlgorithm(state);

            // Check if the random number is within the current range and return it
            if (_range.Includes(randNum))
                return randNum;

            // If not, generate a new seed and update the state
            UpdateRandomNumberGeneratorState(DEFAULT_RANDOM_NUMBER_GENERATION_ALGORITHM);

            // Try again with the updated state
            return GetNextFloat();
        }

        public void SetRange(int inclusiveLowerBound, int exclusiveUpperBound)
        {
            _range = new Range<int>(inclusiveLowerBound, exclusiveUpperBound);
        }

        public void SetRandomNumberGenerationAlgorithm(string algorithmName)
        {
            if (_availableRandomNumberGenerationAlgorithms.Contains(algorithmName))
            {
                _randomNumberGenerationAlgorithm = SelectRandomNumberGenerationAlgorithm(algorithmName);
            }
        }

        public void UpdateRandomNumberGeneratorState(string algorithmName)
        {
            RandomNumberGeneratorState state = _externalDependencies.GetValueOrDefault(algorithmName, new RandomNumberGeneratorState());
            state.Seed = GenerateNewSeed();
            state.Next = 0;
            state.IsInitialized = false;
            _externalDependencies[algorithmName] = state;
        }

        private int GenerateNewSeed()
        {
            return (int)(DateTime.UtcNow.Ticks % Int32.MaxValue);
        }

        private Func<RandomNumberGeneratorState, int> SelectRandomNumberGenerationAlgorithm(string algorithmName)
        {
            switch (algorithmName)
            {
                case "LinearCongruential": return LinearCongruential;
                case "MersenneTwister": return MersenneTwister;
                default: throw new ArgumentException("Invalid random number generation algorithm");
            }
        }

        private int LinearCongruential(RandomNumberGeneratorState state)
        {
            if (!state.IsInitialized)
            {
                state.Seed = GenerateNewSeed();
                state.Next = 0;
                state.IsInitialized = true;
            }

            int randNum = (int)(state.Next * state.Seed % Int32.MaxValue);
            state.Next++;
            return randNum;
        }

        private int MersenneTwister(RandomNumberGeneratorState state)
        {
            if (!state.IsInitialized)
            {
                state.Seed = GenerateNewSeed();
                state.Next = 0;
                state.IsInitialized = true;
            }

            int randNum = (int)(state.Next * state.Seed % Int32.MaxValue);
            state.Next++;
            return randNum;
        }
    }
}
