// Encryption and decryption functions
int encrypt(const unsigned char* input, const size_t input_len, const unsigned char* key, const size_t key_len, unsigned char** output) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int out_len;
    unsigned char *out;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Error creating cipher context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Error initializing cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    len = (int)input_len;
    if (1 != EVP_EncryptUpdate(ctx, NULL, &out_len, input, len)) {
        fprintf(stderr, "Error updating cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    out = (unsigned char *)malloc(out_len);
    if (out == NULL) {
        fprintf(stderr, "Error allocating memory: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    if (1 != EVP_EncryptUpdate(ctx, out, &out_len, input, len)) {
        fprintf(stderr, "Error updating cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    *output = out;

    EVP_CIPHER_CTX_free(ctx);

    return 1;
}

int decrypt(const unsigned char* input, const size_t input_len, const unsigned char* key, const size_t key_len, unsigned char** output) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int out_len;
    unsigned char *out;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Error creating cipher context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Error initializing cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    len = (int)input_len;
    if (1 != EVP_DecryptUpdate(ctx, NULL, &out_len, input, len)) {
        fprintf(stderr, "Error updating cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    out = (unsigned char *)malloc(out_len);
    if (out == NULL) {
        fprintf(stderr, "Error allocating memory: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    if (1 != EVP_DecryptUpdate(ctx, out, &out_len, input, len)) {
        fprintf(stderr, "Error updating cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    *output = out;

    EVP_CIPHER_CTX_free(ctx);

    return 1;
}

// Database connection and query functions
PGconn* connectToDatabase() {
    PGconn *conn;
    conn = PQconnectdb("host=localhost port=5432 dbname=mydatabase user=myuser password=mypassword");

    if (PQstatus(conn) == CONNECTION_BAD) {
        fprintf(stderr, "Connection to database failed: %s\n", PQerrorMessage(conn));
        return NULL;
    }

    return conn;
}

int queryDatabase(PGconn* conn, const char* query) {
    PGresult *res;
    res = PQexec(conn, query);

    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "Query failed: %s\n", PQerrorMessage(conn));
        return 0;
    }

    return 1;
}

// Command-line interface functions
