package com.example.distributedcommandexecution;

import java.io.File;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DistributedCommandExecutionService {
    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private final ECEPClient ecepClient;
    private final FileManager fileManager;

    public DistributedCommandExecutionService(ECEPClient ecepClient, FileManager fileManager) {
        this.ecepClient = ecepClient;
        this.fileManager = fileManager;
    }

    public void executeCommand(String command, String fileName) throws CommandExecutionException {
        // 1. Delete local file if exists and respect permissions
        File file = new File(fileName);
        if (file.exists()) {
            if (!file.delete()) {
                throw new CommandExecutionException("Failed to delete local file: " + fileName);
            }
        }

        // 2. Execute command asynchronously using secure and efficient method
        executorService.submit(() -> {
            try {
                ecepClient.executeCommand(command);
            } catch (ECEPException e) {
                throw new CommandExecutionException("Failed to execute command: " + command, e);
            }
        });
    }

    public void getCommandStatus(String commandId) throws CommandExecutionException {
        try {
            return ecepClient.getCommandStatus(commandId);
        } catch (ECEPException e) {
            throw new CommandExecutionException("Failed to retrieve command status: " + commandId, e);
        }
    }

    public void deleteCommand(String commandId) throws CommandExecutionException {
        try {
            ecepClient.deleteCommand(commandId);
        } catch (ECEPException e) {
            throw new CommandExecutionException("Failed to delete command: " + commandId, e);
        }
    }

    public void submitCommand(String command) throws CommandExecutionException {
        try {
            return ecepClient.submitCommand(command);
        } catch (ECEPException e) {
            throw new CommandExecutionException("Failed to submit command: " + command, e);
        }
    }
}
