            {
                while (!reader.EndOfStream)
                {
                    var encryptedMessage = await reader.ReadLineAsync();

                    if (string.IsNullOrEmpty(encryptedMessage))
                        continue;

                    // Decrypt the message using one of the provided key pairs and IV
                    var decryptedMessage = DecryptMessage(encryptedMessage, _keyPairs[0], _iv);

                    // Store the decrypted message in a memory-efficient manner
                    ProcessDecryptedData(decryptedMessage);
                }
            }
            catch (Exception ex)
            {
