using ExternalIdentityManagementService;

namespace UserAuthenticationLibrary
{
    public class Authenticator
    {
        private readonly IExternalIdentityManagementService _ims;

        public Authenticator(IExternalIdentityManagementService ims)
        {
            _ims = ims;
        }

        public async Task<bool> AuthenticateAsync(string username, string password)
        {
            // Get the user's salt from the external identity management service
            var userSalt = await _ims.GetUserSaltAsync(username);

            // Hash the provided password using the Argon2 algorithm and the user's salt
            var hashedPassword = HashPassword(password, userSalt);

            // Authenticate with the external identity management service using the hashed password
            var authenticationResult = await _ims.AuthenticateAsync(username, hashedPassword);

            return authenticationResult.IsSuccess;
        }

        public async Task<bool> UpdatePasswordAsync(string username, string oldPassword, string newPassword)
        {
            // Get the user's salt from the external identity management service
            var userSalt = await _ims.GetUserSaltAsync(username);

            // Hash the provided password using the Argon2 algorithm and the user's salt
            var hashedNewPassword = HashPassword(newPassword, userSalt);

            // Update the user's password in the external identity management service using the new hashed password
            var updateResult = await _ims.UpdateUserPasswordAsync(username, hashedNewPassword, oldPassword);

            return updateResult.IsSuccess;
        }

        private static string HashPassword(string password, string salt)
        {
            // Use the Argon2 algorithm to hash the provided password and the user's salt
            var argon2 = new Argon2();
            var hashedPassword = argon2.ComputeHash(password + salt);

            return hashedPassword;
        }
    }
}
