        private readonly JsonSerializerOptions _jsonSerializerOptions;

        public DataRecoveryService(HttpClient httpClient, EncryptionApi encryptionApi)
        {
            _httpClient = httpClient;
            _encryptionApi = encryptionApi;
            _jsonSerializerOptions = new JsonSerializerOptions()
            {
                WriteIndented = true,
                IgnoreNullValues = true,
                AllowTrailingCommas = true,
                PropertyNameCaseInsensitive = true,
            };
        }

        public async Task<T> DecryptAndDeserializeDataAsync<T>(string url, byte[] key, byte[] iv) where T : class
        {
            try
            {
                // Fetch encrypted data from URL
                var response = await _httpClient.GetAsync(url);
                if (!response.IsSuccessStatusCode)
                    throw new HttpRequestException($"Failed to retrieve encrypted data: {response.StatusCode}");

                var encryptedData = await response.Content.ReadAsStreamAsync();

                // Decrypt and deserialize data
                var decryptedData = _encryptionApi.Decrypt(encryptedData, key, iv);
                using (var streamReader = new StreamReader(decryptedData))
                {
                    return JsonSerializer.Deserialize<T>(streamReader.BaseStream, _jsonSerializerOptions);
                }
            }
            catch (HttpRequestException ex)
            {
                LogError($"Failed to retrieve data from URL: {url}", ex);
                throw;
            }
            catch (CryptographicException ex)
            {
                LogError("Failed to decrypt data", ex);
                throw;
            }
            catch (JsonException ex)
