// C# Library for Deserializing Complex Datasets from Binary Files

namespace Deserializer
{
    using System;
    using System.IO;
    using System.Text;
    using System.Threading;
    using System.Threading.Tasks;

    public class Deserializer
    {
        // Settings
        private const int BufferSize = 4096; // Size of the buffer for reading data from the file
        private const int MaxFileSize = 1024 * 1024 * 1024; // Maximum size of the file to be read (in bytes)
        private static readonly Encoding DefaultEncoding = Encoding.UTF8; // Default encoding for the file

        // Members
        private string _filePath; // Path to the binary file
        private int _fileSize; // Size of the file to be read (in bytes)
        private long _position; // Current position in the file
        private byte[] _buffer; // Buffer for reading data from the file
        private CancellationTokenSource _cancellationTokenSource; // Token source for cancelling tasks
        private Task _readTask; // Task for reading data from the file
        private object _lock = new object(); // Object for synchronizing access to the buffer and position variables

        // Constructor
        public Deserializer(string filePath)
        {
            _filePath = filePath;
            _cancellationTokenSource = new CancellationTokenSource();
        }

        // Methods
        public async Task<T> DeserializeAsync<T>(CancellationToken cancellationToken = default) where T : class
        {
            await InitializeAsync(cancellationToken);

            using var stream = File.OpenRead(_filePath);
            stream.Position = _position;

            // Read the data from the file and deserialize it to an object of type T
            return await DeserializeFromStreamAsync<T>(stream, cancellationToken);
        }

        public async Task<bool> TryDeserializeAsync<T>(out T result, CancellationToken cancellationToken = default) where T : class
        {
            result = null;
            try
            {
                result = await DeserializeAsync<T>(cancellationToken);
                return true;
            }
            catch (Exception ex) when (!(ex is OperationCanceledException))
            {
                // Log the error and return false if an exception occurred
                Console.WriteLine($"Failed to deserialize data from file: {_filePath}");
                return false;
            }
        }

        public async Task InitializeAsync(CancellationToken cancellationToken = default)
        {
            if (_readTask == null || _readTask.IsCompleted)
            {
                // Create a new task for reading the file
                _readTask = ReadFileAsync(cancellationToken);
            }
            else
            {
                // Cancel any existing tasks and create a new one
                _cancellationTokenSource.Cancel();
                _readTask = null;

                _readTask = ReadFileAsync(cancellationToken);
            }
        }

        public async Task DisposeAsync()
        {
            // Cancel any existing tasks and dispose of the buffer
            if (_readTask != null)
            {
                _cancellationTokenSource.Cancel();
                await _readTask;
            }

            _buffer = null;
            _position = 0;
            _fileSize = 0;
        }

        // Private methods
        private async Task ReadFileAsync(CancellationToken cancellationToken)
        {
            try
            {
                using var stream = File.OpenRead(_filePath);
                await DeserializeFromStreamAsync<T>(stream, cancellationToken);
            }
            catch (Exception ex) when (!(ex is OperationCanceledException))
            {
                Console.WriteLine($"Failed to read file: {_filePath}");
            }
        }

        private async Task<T> DeserializeFromStreamAsync<T>(Stream stream, CancellationToken cancellationToken) where T : class
        {
            // Ensure that the buffer is large enough for reading from the stream
            if (_buffer == null || _buffer.Length < BufferSize)
            {
                _buffer = new byte[BufferSize];
            }

            // Read data from the stream until EOF or an error occurs
            while (!stream.CanSeek && !cancellationToken.IsCancellationRequested)
            {
                // Ensure that the buffer is large enough for reading from the stream
                if (_buffer == null || _buffer.Length < BufferSize)
                {
                    _buffer = new byte[BufferSize];
                }

                // Read data from the stream into the buffer
                var bytesRead = await stream.ReadAsync(_buffer, 0, _buffer.Length, cancellationToken);

                if (bytesRead == 0) break;

                // Deserialize the data in the buffer to an object of type T
                using var memoryStream = new MemoryStream(_buffer, 0, bytesRead, false);
                return Serializer.Deserialize<T>(memoryStream);
            }

            return null;
        }
    }
}']

