import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;

public class BinaryDeserializer {
  private static final Logger logger = LoggerFactory.getLogger(BinaryDeserializer.class);
  private Gson gson;

  public BinaryDeserializer() {
    this.gson = new Gson();
  }

  public <T> T deserialize(byte[] data, Class<T> clazz) throws IOException {
    try {
      return gson.fromJson(data, clazz);
    } catch (JsonSyntaxException e) {
      logger.error("Failed to deserialize data", e);
      throw new IOException("Failed to deserialize data", e);
    }
  }

  public <T> T deserializeWithFallback(byte[] data, Class<T> clazz) throws IOException {
    try {
      return gson.fromJson(data, clazz);
    } catch (JsonSyntaxException e) {
      logger.error("Failed to deserialize data with fallback", e);
      return fallbackDeserialization(data, clazz);
    }
  }

  private <T> T fallbackDeserialization(byte[] data, Class<T> clazz) throws IOException {
    // Implement fallback deserialization logic here, e.g., use a different serializer or return a default value
  }
}
