async function uploadChunked(buffer, userId) {
  const CHUNK_SIZE = 1024 * 1024; // 1 MB
  const NUM_THREADS = 4;

  const totalSize = buffer.length;
  const numChunks = Math.ceil(totalSize / CHUNK_SIZE);
  const threadPool = [];

  for (let i = 0; i < numChunks; i++) {
