      const response = await axios.get(`${this.secretsManagerUrl}/encrypted-password`);
      return response.data;
    } catch (error) {
      console.log(error);
      // Log error and reject promise with descriptive message
      const logPayload = {
        status: 'failure',
        message: `Failed to retrieve encrypted password from secrets manager`,
        timestamp: new Date(),
      };
      await axios.post(this.loggingServiceUrl, logPayload);
      return Promise.reject(`Failed to retrieve encrypted password from secrets manager`);
    }
  }

  _replacePlaceholdersWithValues(encryptedPassword) {
