            self.vertices[vertex.id] = vertex
            self.cached_vertices.add(vertex)

    def remove_vertex(self, vertex: Vertex):
        if not isinstance(vertex, Vertex):
            raise ValueError("Invalid vertex")
        with self._lock(vertex.id):
            del self.vertices[vertex.id]
            self.cached_vertices.discard(vertex)

    def add_edge(self, edge: Edge):
        if not isinstance(edge, Edge):
            raise ValueError("Invalid edge")
        with self._lock(edge.source_id, edge.target_id):
            self.edges[edge.source_id].add(edge)
            self.cached_edges[edge.source_id].append(edge)

    def remove_edge(self, edge: Edge):
        if not isinstance(edge, Edge):
            raise ValueError("Invalid edge")
        with self._lock(edge.source_id, edge.target_id):
            self.edges[edge.source_id].discard(edge)
            self.cached_edges[edge.source_id].remove(edge)

    def _lock(self, *ids: str) -> bool:
        for id in ids:
            if self.locked_vertices.get(id):
                return False
        for id in ids:
            self.locked_vertices[id] = True
        return True

    def _unlock(self, *ids: str) -> None:
        for id in ids:
            del self.locked_vertices[id]

    def get_vertex(self, vertex_id: str) -> Vertex:
        if not isinstance(vertex_id, str):
            raise ValueError("Invalid vertex ID")
        with self._lock(vertex_id):
            return self.vertices[vertex_id]

    def get_edges(self, source_id: str, target_id: str) -> List[Edge]:
        if not isinstance(source_id, str) or not isinstance(target_id, str):
            raise ValueError("Invalid edge IDs")
        with self._lock(source_id, target_id):
            return self.edges[source_id].intersection(self.edges[target_id])

    def get_vertices(self) -> List[Vertex]:
        with self._lock():
            return list(self.cached_vertices)

    def get_edges(self, source_id: str) -> List[Edge]:
        if not isinstance(source_id, str):
            raise ValueError("Invalid edge IDs")
        with self._lock(source_id):
            return self.cached_edges[source_id]

    def update_vertex_attribute(self, vertex_id: str, attribute: str, value: any) -> bool:
        if not isinstance(vertex_id, str) or not isinstance(attribute, str):
            raise ValueError("Invalid vertex ID or attribute")
        with self._lock(vertex_id):
            try:
                self.vertices[vertex_id].attributes[attribute] = value
                return True
            except KeyError:
                return False

    def update_edge_attribute(self, source_id: str, target_id: str, attribute: str, value: any) -> bool:
        if not isinstance(source_id, str) or not isinstance(target_id, str) or not isinstance(attribute, str):
            raise ValueError("Invalid edge IDs or attribute")
        with self._lock(source_id, target_id):
            try:
                edge = self.edges[source_id].intersection(self.edges[target_id])
                if not edge:
                    return False
                edge.attributes[attribute] = value
                return True
            except KeyError:
                return False

class Vertex:
    def __init__(self, id: str, attributes: Dict[str, any]):
        self.id = id
        self.attributes = attributes

class Edge:
    def __init__(self, source_id: str, target_id: str, attributes: Dict[str, any]):
        self.source_id = source_id
        self.target_id = target_id
        self.attributes = attributes

# Hashing functions for secure storage of vertex and edge metadata
def hash_vertex(vertex: Vertex) -> str:
    return hashlib.sha256(json.dumps(vertex).encode()).hexdigest()

def hash_edge(edge: Edge) -> str:
    return hashlib.sha256(json.dumps(edge).encode()).hexdigest()

# Cryptographic functions for secure storage of vertex and edge metadata
def encrypt_vertex(vertex: Vertex, key: bytes) -> str:
    return hashlib.aes_encrypt(json.dumps(vertex).encode(), key).hexdigest()

def decrypt_vertex(hashed_vertex: str, key: bytes) -> Vertex:
    try:
        encrypted_vertex = hashlib.aes_decrypt(hashed_vertex.encode(), key)
        return json.loads(encrypted_vertex.decode())
    except (ValueError, TypeError):
        return None

def encrypt_edge(edge: Edge, key: bytes) -> str:
    return hashlib.aes_encrypt(json.dumps(edge).encode(), key).hexdigest()

def decrypt_edge(hashed_edge: str, key: bytes) -> Edge:
    try:
        encrypted_edge = hashlib.aes_decrypt(hashed_edge.encode(), key)
        return json.loads(encrypted_edge.decode())
    except (ValueError, TypeError):
        return None
