        plugin(input)
    }
}

struct ErrorHandler {
    errors: HashMap<String, (Box<dyn FnOnce() + Send + Sync>, Option<String>)>,
}

impl ErrorHandler {
    fn new() -> Self {
        ErrorHandler {
            errors: HashMap::new(),
        }
    }

    fn register_error(&mut self, name: &str, error: Box<dyn FnOnce() + Send + Sync>) {
        self.errors.insert(name.to_string(), (error, None));
    }

    fn handle_error(&self, error: &Error) -> Option<String> {
        for (name, (handler, _)) in self.errors.iter() {
            if handler().is::<Error>() {
                return Some(name.to_string());
            }
        }
        None
    }
}

struct ConcurrencyManager {
    runtime: Runtime,
    task_queue: Mutex<VecDeque<JoinHandle<String>>>,
    max_concurrency: usize,
}

impl ConcurrencyManager {
    fn new(max_concurrency: usize) -> Self {
        let runtime = Runtime::new().unwrap();
        let task_queue = Mutex::new(VecDeque::new());
        ConcurrencyManager {
            runtime,
            task_queue,
            max_concurrency,
        }
    }

    fn add_task(&self, task: JoinHandle<String>) -> bool {
        self.task_queue.lock().unwrap().push_back(task);
        if self.task_queue.len() > self.max_concurrency {
            return false;
        }
        true
    }

    fn execute_tasks(&self) -> Vec<String> {
        let mut results = Vec::new();
        while let Some(task) = self.task_queue.lock().unwrap().pop_front() {
            results.push(task.join());
        }
        results
    }
}

