// Module for handling directory creation, environment variable updates, and error logging
use std::env;
use std::path::PathBuf;
use std::fs::{File, create_dir};
use std::io::ErrorKind;
use std::sync::Mutex;
use std::time::Instant;

// Struct for storing directory information
struct Directory {
    name: String,
    path: PathBuf,
}

// Function to create a new directory with the given name
fn create_directory(name: &str) -> Result<Directory, String> {
    // Validate the directory name for safety
    if !validate_directory_name(name) {
        return Err("Invalid directory name".to_string());
    }

    // Create a new mutex to protect shared resources
    let mutex = Mutex::new(false);

    // Acquire the lock on the mutex
    let _lock = mutex.lock().unwrap();

    // Check if the directory already exists
    if File::open(name).is_ok() {
        return Err("Directory already exists".to_string());
    }

    // Create the directory
    match create_dir(name) {
        Ok(_) => (),
        Err(e) => return Err(format!("Failed to create directory: {}", e)),
    }

    // Update the environment variable with the new directory path
    let env_var = format!("DIR_{}", name);
    match env::set_var(&env_var, &name) {
        Ok(_) => (),
        Err(e) => return Err(format!("Failed to set environment variable: {}", e)),
    }

    // Release the lock on the mutex
    drop(_lock);

    // Return the new directory information
    Ok(Directory { name, path: PathBuf::from(name) })
}

// Function to update the environment variable associated with a directory path
fn update_environment_variable(directory: &str) -> Result<(), String> {
    // Validate the directory name for safety
    if !validate_directory_name(directory) {
        return Err("Invalid directory name".to_string());
    }

    // Update the environment variable with the new directory path
    let env_var = format!("DIR_{}", directory);
    match env::set_var(&env_var, &directory) {
        Ok(_) => (),
        Err(e) => return Err(format!("Failed to set environment variable: {}", e)),
    }

    // Return successfully
    Ok(())
}

// Function to retrieve the directory path associated with an environment variable
fn get_directory_path(env_var: &str) -> Result<PathBuf, String> {
    // Validate the environment variable for safety
    if !validate_environment_variable(env_var) {
        return Err("Invalid environment variable".to_string());
    }

    // Retrieve the directory path from the environment variable
    match env::var(env_var) {
        Ok(path) => PathBuf::from(path),
        Err(_) => return Err("Failed to retrieve directory path".to_string()),
    }
}

// Function to log an error message and update the environment variable with the new directory path
fn log_error(directory: &str, message: &str) {
    // Log the error message
    println!("{}", format!("Error occurred while creating directory {}: {}", directory, message));

    // Update the environment variable with the new directory path
    update_environment_variable(directory).unwrap();
}

// Function to validate a directory name for safety
fn validate_directory_name(name: &str) -> bool {
    // Check if the directory name is empty
    if name.is_empty() {
        return false;
    }

    // Check if the directory name contains invalid characters
    if !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
        return false;
    }

    // Return successfully
    true
}

// Function to validate an environment variable for safety
fn validate_environment_variable(env_var: &str) -> bool {
    // Check if the environment variable is empty
    if env_var.is_empty() {
        return false;
    }

    // Return successfully
    true
}
