import os
import shutil
from multiprocessing import Pool
from concurrent.futures import ThreadPoolExecutor
from typing import List
from time import sleep

class FileSynchronizer:
    def __init__(self, source_path: str, target_path: str):
        self.source_path = source_path
        self.target_path = target_path
        self.file_list = []
        self.cache = {}

    def add_file(self, file_name: str):
        """Add a file to the file list"""
        self.file_list.append(file_name)

    def sync_files(self, force=False):
        """Sync files between source and target paths"""
        if not os.path.exists(self.source_path):
            raise ValueError("Source path does not exist")
        if not os.path.exists(self.target_path):
            raise ValueError("Target path does not exist")

        for file in self.file_list:
            source_file = os.path.join(self.source_path, file)
            target_file = os.path.join(self.target_path, file)
            if force or not os.path.exists(target_file):
                shutil.copy2(source_file, target_file)
            elif os.path.getmtime(source_file) > os.path.getmtime(target_file):
                shutil.copy2(source_file, target_file)

    def sync_files_with_cache(self):
        """Sync files using a cache to reduce load on primary storage nodes"""
        for file in self.file_list:
            source_file = os.path.join(self.source_path, file)
            target_file = os.path.join(self.target_path, file)
            if not os.path.exists(target_file):
                shutil.copy2(source_file, target_file)
            elif self.cache.get(source_file):
                if self.cache.get(source_file) > os.path.getmtime(target_file):
                    shutil.copy2(source_file, target_file)

    def add_node(self, node: str):
        """Add a node to the list of nodes"""
        self.nodes.append(node)

    def remove_node(self, node: str):
        """Remove a node from the list of nodes"""
        self.nodes.remove(node)

    def get_node_list(self):
        """Get the list of nodes"""
        return self.nodes

    def sync_files_across_nodes(self, force=False):
        """Sync files across nodes using a thread pool executor"""
        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = []
            for node in self.nodes:
                futures.append(executor.submit(self.sync_files, force))
            for future in futures:
                future.result()

    def sync_files_with_cache_across_nodes(self):
        """Sync files across nodes using a thread pool executor with cache"""
        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = []
            for node in self.nodes:
                futures.append(executor.submit(self.sync_files_with_cache))
            for future in futures:
                future.result()

class FileSynchronizationManager:
