#include <limits.h>
#include <math.h>
#include <time.h>
#define AES_KEY "thisisthetestkey"
#define AES_IV "thisisthetestiv"
int main(int argc, char **argv) {
    int fd;
    char filename[PATH_MAX] = "";
    char *filedata = NULL;
    size_t filesize;
    const unsigned char aes_key[] = AES_KEY;
    const unsigned char aes_iv[] = AES_IV;
    int blocksize = 0;
    struct stat st;
    int cnt = 0;
    FILE *fp = NULL;
    fd = open(filename, O_RDONLY);
    if (fd == -1) {
        printf("Error reading file: %s\n", filename);
        return 0;
    }
    if (fstat(fd, &st) == -1) {
        close(fd);
        printf("Error reading file: %s\n", filename);
        return 0;
    }
    filesize = st.st_size;
    fp = fdopen(fd, "rb");
    if (fp == NULL) {
        close(fd);
        printf("Error opening file: %s\n", filename);
        return 0;
    }
    blocksize = AES_BLOCK_SIZE;
    int keylength = strlen(AES_KEY);
    int ivlength = strlen(AES_IV);
    if (keylength != ivlength) {
        printf("Error: Invalid key and IV lengths\n");
        return 0;
    }
    unsigned char *encryptdata = NULL;
    size_t encryptedsize;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Could not create EVP cipher context\n");
        return 0;
    }
    int ret = EVP_EncryptInit(ctx, EVP_aes_256_cbc(), aes_key, aes_iv);
    if (ret != 1) {
        printf("Error: Could not initialize encryption context\n");
        return 0;
    }
    encryptedsize = filesize + blocksize - 1;
    encryptdata = (unsigned char *)malloc(encryptedsize * sizeof(unsigned char));
    if (encryptdata == NULL) {
        printf("Error: Could not allocate memory for encryption\n");
        return 0;
    }
    int readcount = fread(filedata, sizeof(unsigned char), filesize, fp);
    if (readcount != filesize) {
        printf("Error: Could not read file data\n");
        return 0;
    }
    ret = EVP_EncryptUpdate(ctx, encryptdata, &encryptedsize, filedata, filesize);
    if (ret != 1) {
        printf("Error: Could not encrypt file data\n");
        return 0;
    }
    int padding = blocksize - encryptedsize % blocksize;
    ret = EVP_EncryptUpdate(ctx, encryptdata + encryptedsize, &padding, NULL, padding);
    if (ret != 1) {
        printf("Error: Could not pad encryption\n");
        return 0;
    }
    EVP_CIPHER_CTX_free(ctx);
    close(fd);
    fclose(fp);
    free(filedata);
    filedata = encryptdata;
    filesize = encryptedsize + padding;
}
