import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.Objects;

public static Object loadStateFromFile(String filePath) {
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
        // Read the object from the stream and check if it is an instance of MoSTState
        Object obj = ois.readObject();
        if (obj instanceof MoSTState) {
            return obj;
        }
    } catch (IOException | ClassNotFoundException e) {
        // Handle exceptions and close the ObjectInputStream appropriately
        System.out.println("Failed to load state from file: " + e.getMessage());
        if (ois != null) {
            try {
                ois.close();
            } catch (IOException ex) {
                // Log the exception and continue with a null return value
                System.out.println("Error closing ObjectInputStream: " + ex.getMessage());
            }
        }
    }
    return null;
}
```
