#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <stdint.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_EVENTS 100000
#define EVENT_SIZE sizeof(struct event)
#define MAX_THREADS 8
#define THREAD_IDLE 2000
#define MAX_QUERY_DEPTH 5
#define MIN_QUERY_TIME 100
#define QUERY_TIMEOUT 30000
#define ALERT_INTERVAL 60000
#define DATA_RETENTION_DAYS 90

typedef struct event {
    uint8_t type; // protocol type (e.g., TCP, UDP)
    uint32_t src_ip; // IP address of source host
    uint16_t src_port; // port number of source host
    uint32_t dst_ip; // IP address of destination host
    uint16_t dst_port; // port number of destination host
    uint32_t time; // timestamp of event (milliseconds since epoch)
} event;

typedef struct thread_data {
    int queue_id;
    pthread_mutex_t *queue_lock;
    pthread_cond_t *queue_not_empty;
} thread_data;

typedef struct query_info {
    uint8_t type; // protocol type (e.g., TCP, UDP)
    uint32_t src_ip; // IP address of source host
    uint16_t src_port; // port number of source host
    uint32_t dst_ip; // IP address of destination host
    uint16_t dst_port; // port number of destination host
    uint32_t time_start; // start time of query (milliseconds since epoch)
    uint32_t time_end; // end time of query (milliseconds since epoch)
    int32_t result_count; // number of results returned
} query_info;

typedef struct event_queue {
    pthread_mutex_t *lock;
    pthread_cond_t *not_empty;
    pthread_cond_t *not_full;
    int32_t head;
    int32_t tail;
    int32_t size;
    event events[MAX_EVENTS];
} event_queue;

typedef struct query_queue {
    pthread_mutex_t *lock;
    pthread_cond_t *not_empty;
    pthread_cond_t *not_full;
    int32_t head;
    int32_t tail;
    int32_t size;
    query_info queries[MAX_QUERY_DEPTH];
} query_queue;

typedef struct data_node {
    int32_t count;
    uint32_t last_time;
    event events[MAX_EVENTS];
} data_node;

typedef struct data_table {
    pthread_mutex_t *lock;
    data_node nodes[MAX_THREADS];
} data_table;

typedef struct cache_data {
    uint32_t last_time;
    event events[MAX_EVENTS];
} cache_data;

void init_event_queue(event_queue *q) {
    q->lock = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(q->lock, NULL);
    q->not_empty = malloc(sizeof(pthread_cond_t));
    pthread_cond_init(q->not_empty, NULL);
    q->not_full = malloc(sizeof(pthread_cond_t));
    pthread_cond_init(q->not_full, NULL);
    q->head = 0;
    q->tail = 0;
    q->size = 0;
}

void init_query_queue(query_queue *q) {
    q->lock = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(q->lock, NULL);
    q->not_empty = malloc(sizeof(pthread_cond_t));
    pthread_cond_init(q->not_empty, NULL);
    q->not_full = malloc(sizeof(pthread_cond_t));
    pthread_cond_init(q->not_full, NULL);
    q->head = 0;
    q->tail = 0;
    q->size = 0;
}

void init_data_table(data_table *t) {
    t->lock = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(t->lock, NULL);
    for (int i = 0; i < MAX_THREADS; ++i) {
        t->nodes[i].count = 0;
        t->nodes[i].last_time = 0;
    }
}

void init_cache_data(cache_data *d) {
    d->last_time = 0;
    for (int i = 0; i < MAX_EVENTS; ++i) {
        d->events[i] = {0};
    }
}

void destroy_event_queue(event_queue *q) {
    pthread_mutex_destroy(q->lock);
    free(q->lock);
    pthread_cond_destroy(q->not_empty);
    free(q->not_empty);
    pthread_cond_destroy(q->not_full);
    free(q->not_full);
}

void destroy_query_queue(query_queue *q) {
    pthread_mutex_destroy(q->lock);
    free(q->lock);
    pthread_cond_destroy(q->not_empty);
    free(q->not_empty);
    pthread_cond_destroy(q->not_full);
    free(q->not_full);
}

void destroy_data_table(data_table *t) {
    pthread_mutex_destroy(t->lock);
    free(t->lock);
}

void destroy_cache_data(cache_data *d) {
    // nothing to do
}

void enqueue_event(event_queue *q, event e) {
    pthread_mutex_lock(q->lock);
    while (q->size >= MAX_EVENTS) {
        pthread_cond_wait(q->not_full, q->lock);
    }
    q->events[q->tail] = e;
    q->tail = (q->tail + 1) % MAX_EVENTS;
    q->size++;
    pthread_cond_broadcast(q->not_empty);
    pthread_mutex_unlock(q->lock);
}

void enqueue_query(query_queue *q, query_info qi) {
    pthread_mutex_lock(q->lock);
    while (q->size >= MAX_QUERY_DEPTH) {
        pthread_cond_wait(q->not_full, q->lock);
    }
    q->queries[q->tail] = qi;
    q->tail = (q->tail + 1) % MAX_QUERY_DEPTH;
    q->size++;
    pthread_cond_broadcast(q->not_empty);
    pthread_mutex_unlock(q->lock);
}

void dequeue_event(event_queue *q, event *e) {
    pthread_mutex_lock(q->lock);
    while (q->size <= 0) {
        pthread_cond_wait(q->not_empty, q->lock);
    }
    *e = q->events[q->head];
    q->head = (q->head + 1) % MAX_EVENTS;
    q->size--;
    pthread_cond_broadcast(q->not_full);
    pthread_mutex_unlock(q->lock);
}

void dequeue_query(query_queue *q, query_info *qi) {
    pthread_mutex_lock(q->lock);
    while (q->size <= 0) {
        pthread_cond_wait(q->not_empty, q->lock);
    }
    *qi = q->queries[q->head];
    q->head = (q->head + 1) % MAX_QUERY_DEPTH;
    q->size--;
    pthread_cond_broadcast(q->not_full);
    pthread_mutex_unlock(q->lock);
}

void add_event_to_table(data_table *t, event e) {
    pthread_mutex_lock(t->lock);
    data_node *n = &(t->nodes[e.type % MAX_THREADS]);
    if (n->count < MAX_EVENTS) {
        n->events[n->count] = e;
        n->count++;
    } else {
        // overflow, replace oldest event
        int i = 0;
        while (i < MAX_EVENTS && n->events[i].time != 0) {
            ++i;
        }
        if (i < MAX_EVENTS) {
            n->events[i] = e;
        } else {
            // unable to add event, discard oldest event
            int j = i - 1;
            while (j >= 0 && n->events[j].time != 0) {
                --j;
            }
            if (j < MAX_EVENTS) {
                n->events[j + 1] = e;
            } else {
                // unable to add event, discard all events
                n->count = 0;
            }
        }
    }
    pthread_mutex_unlock(t->lock);
}

void remove_event_from_table(data_table *t, event e) {
    pthread_mutex_lock(t->lock);
    data_node *n = &(t->nodes[e.type % MAX_THREADS]);
    int i = 0;
    while (i < n->count && !(n->events[i].time == e.time && n->events[i].id == e.id)) {
        ++i;
    }
    if (i < n->count) {
        // found event, remove it
        for (int j = i; j < n->count - 1; ++j) {
            n->events[j] = n->events[j + 1];
        }
        --n->count;
    }
    pthread_mutex_unlock(t->lock);
}

void find_all_events_in_range(data_table *t, query_info qi, event_list *el) {
    pthread_mutex_lock(t->lock);
    data_node *n = &(t->nodes[qi.type % MAX_THREADS]);
    for (int i = 0; i < n->count; ++i) {
        if (n->events[i].time >= qi.start && n->events[i].time <= qi.end) {
            add_event_to_list(el, n->events[i]);
        }
    }
    pthread_mutex_unlock(t->lock);
}

void find_top_k_events_in_range(data_table *t, query_info qi, int k, event_list *el) {
    pthread_mutex_lock(t->lock);
    data_node *n = &(t->nodes[qi.type % MAX_THREADS]);
    // initialize priority queue with top k elements
    for (int i = 0; i < n->count && i < k; ++i) {
        if (n->events[i].time >= qi.start && n->events[i].time <= qi.end) {
            add_event_to_list(el, n->events[i]);
        }
    }
    // heapify the priority queue
    for (int i = k - 1; i >= 0; --i) {
        int j = i;
        while (j > 0 && el.events[j].time < el.events[(j - 1) / 2].time) {
            swap_event(&el.events[j], &el.events[(j - 1) / 2]);
            j = (j - 1) / 2;
        }
    }
    // iterate over the remaining elements and replace them if necessary
    for (int i = k; i < n->count; ++i) {
        if (n->events[i].time >= qi.start && n->events[i].time <= qi.end) {
            int j = 0;
            while (j < k && el.events[j].time < n->events[i].time) {
                ++j;
            }
            if (j < k) {
                // replace oldest element in the priority queue with new event
                swap_event(&el.events[j], &n->events[i]);
                j = 0;
                while (j > 0 && el.events[j].time < el.events[(j - 1) / 2].time) {
                    swap_event(&el.events[j], &el.events[(j - 1) / 2]);
                    j = (j - 1) / 2;
                }
            } else {
                // discard oldest element in the priority queue and add new event
                --el.count;
                el.events[k - 1] = n->events[i];
                for (int j = k - 2; j >= 0; --j) {
                    if (el.events[j].time < el.events[(j + 1) / 2].time) {
                        swap_event(&el.events[j], &el.events[(j + 1) / 2]);
                    } else {
                        break;
                    }
                }
            }
        }
    }
    pthread_mutex_unlock(t->lock);
}

void swap_event(event *e1, event *e2) {
    int temp = e1->time;
    e1->time = e2->time;
    e2->time = temp;
    temp = e1->id;
    e1->id = e2->id;
    e2->id = temp;
}

void add_event_to_list(event_list *el, event e) {
    el.events[el.count] = e;
    ++el.count;
}']

