import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.log4j.LogManager;
import org.apache.log4j.Logger;

public class ModularLoggingService {
  private static final Logger logger = LogManager.getLogger(ModularLoggingService.class);
  private static final int MAX_LOG_SIZE = 1024 * 1024; // 1 MB
  private static final long RETENTION_PERIOD = 365L * 24L * 60L * 60L * 1000L; // 1 year in milliseconds

  public void log(String message) {
    try {
      logMessageToBuffer(message);
      deliverLogs();
    } catch (Exception e) {
      logger.error("Failed to deliver logs: " + e.getMessage());
    }
  }

  private void logMessageToBuffer(String message) throws IOException {
    if (buffer == null) {
      buffer = new BlockingQueue<>(MAX_LOG_SIZE);
    }
    buffer.put(message);
  }

  private void deliverLogs() throws Exception {
    // Deliver logs to external logging destinations like ELK Stack and CloudWatch
    List<String> logsToDeliver = buffer.drain();
    for (String log : logsToDeliver) {
      try {
        deliverLog(log);
      } catch (Exception e) {
        logger.error("Failed to deliver log: " + e.getMessage());
      }
    }
  }

  private void deliverLog(String log) throws Exception {
    // Implement logic for delivering logs to external logging destinations here
    // Example: Use HTTP POST requests to send logs to ELK Stack or CloudWatch
  }

  public void flush() {
    buffer.flush();
  }

  public void close() throws Exception {
    buffer.close();
  }
}
```
This implementation uses a blocking queue to store log messages in memory before delivering them to external logging destinations. The `log` method is responsible for storing the message in the buffer and delivering it to the external logging destination, while the `flush` method is used to flush the buffer and deliver any remaining logs that were not yet delivered. The `close` method is used to close the buffer and release any resources.

To handle structured and unstructured logs, this implementation uses a custom log formatter that serializes the log message as JSON. This allows the service to support different logging levels and formats while still maintaining compatibility with external logging destinations.

