#include <netdb.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

using namespace std;

// Global variables
const int DEFAULT_TIMEOUT = 5000; // 5 seconds
const int MIN_CONNECTIONS = 1;
const int MAX_CONNECTIONS = 10;
const int CONNECTION_BACKOFF = 500; // 0.5 seconds
const int CONNECTION_RETRY_LIMIT = 3;

// Global mutex and condition variable for synchronizing access to the connection pool
mutex g_mutex;
condition_variable g_cv;

// Struct for managing connections in the pool
struct Connection {
    int fd; // File descriptor for socket
    time_t lastUsed; // Timestamp of last use
    bool isInUse; // Flag indicating if connection is in use
};

// Vector to store all connections in the pool
vector<Connection> g_connections;

// Function to create a new connection and add it to the pool
void createConnection() {
    // Lock mutex before making any changes to the connection pool
    lock_guard<mutex> lock(g_mutex);

    // Check if there is space in the pool for a new connection
    if (g_connections.size() >= MAX_CONNECTIONS) {
        throw runtime_error("No more connections available");
    }

    // Create a new socket and connect to the server
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd == -1) {
        perror("socket() failed");
        throw runtime_error("Failed to create socket");
    }

    // Set socket options and connect to the server
    int option = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &option, sizeof(option)) == -1) {
        perror("setsockopt() failed");
        throw runtime_error("Failed to set socket options");
    }

    sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(80); // Port number
    if (inet_pton(AF_INET, "127.0.0.1", &serverAddr.sin_addr) == -1) {
        perror("inet_pton() failed");
        throw runtime_error("Failed to convert IP address");
    }

    if (connect(fd, reinterpret_cast<sockaddr*>(&serverAddr), sizeof(serverAddr)) == -1) {
        perror("connect() failed");
        throw runtime_error("Failed to connect to server");
    }

    // Add the new connection to the pool
    g_connections.push_back({fd, time(NULL), false});
}

// Function to retrieve a connection from the pool
Connection* getConnection() {
    // Lock mutex before making any changes to the connection pool
    lock_guard<mutex> lock(g_mutex);

    // Check if there are any available connections in the pool
    for (auto& conn : g_connections) {
        if (!conn.isInUse && difftime(time(NULL), conn.lastUsed) < CONNECTION_BACKOFF) {
            return &conn;
        }
    }

    // If no available connections, create a new one
    try {
        createConnection();
    } catch (const runtime_error& e) {
        throw runtime_error("Failed to get connection: " + string(e.what()));
    }

    // Return the newly created connection
    return &g_connections.back();
}

// Function to release a connection back to the pool
void releaseConnection(Connection* conn) {
    // Lock mutex before making any changes to the connection pool
    lock_guard<mutex> lock(g_mutex);

    // Update timestamp of last use for released connection
    conn->lastUsed = time(NULL);

    // Set flag indicating that connection is no longer in use
    conn->isInUse = false;

    // Notify any threads waiting on the condition variable
    g_cv.notify_all();
}

// Function to perform an HTTP GET request using a connection from the pool
string httpGet(const string& url) {
    // Lock mutex before making any changes to the connection pool
    lock_guard<mutex> lock(g_mutex);

    // Check if there are any available connections in the pool
    for (auto& conn : g_connections) {
        if (!conn.isInUse && difftime(time(NULL), conn.lastUsed) < CONNECTION_BACKOFF) {
            // Set flag indicating that connection is in use
            conn.isInUse = true;

            // Create HTTP GET request and send it to the server
            string httpReq = "GET " + url + " HTTP/1.1\r\n";
            if (send(conn.fd, httpReq.c_str(), httpReq.length(), 0) == -1) {
