            }

            // Receive response from the server
            char buffer[4096];
            memset(buffer, 0, sizeof(buffer));
            if (recv(conn.fd, buffer, sizeof(buffer), 0) == -1) {
                perror("recv() failed");
                throw runtime_error("Failed to receive HTTP response");
            }

            // Extract the contents of the response body from the buffer
            string respBody;
            char* p = strstr(buffer, "\r\n\r\n");
            if (p) {
                int bodyStart = p - buffer + 4;
