#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

#define BUFFER_SIZE 1024
#define MAX_INTEGER_VALUE 1000000

typedef struct {
    int value;
} integer_t;

void *process_data(void *args) {
    // Get the data buffer and its size from the args structure
    char *buffer = (char *)args;
    int buffer_size = strlen(buffer);

    // Parse the data buffer as a series of integers
    for (int i = 0; i < buffer_size; i += sizeof(integer_t)) {
        integer_t *data = (integer_t *)&buffer[i];

        // Check if the value is valid and within range
        if (data->value <= MAX_INTEGER_VALUE) {
            // Update the largest value encountered so far
            pthread_mutex_lock(&largest_value_mutex);
            if (data->value > largest_value) {
                largest_value = data->value;
            }
            pthread_mutex_unlock(&largest_value_mutex);
        } else {
            // Handle out-of-range values gracefully
            printf("Value %d is out of range, ignoring...\n", data->value);
        }
    }

    return NULL;
}

void *initialize_connection(void *args) {
    // Get the connection details from the args structure
    struct sockaddr_in *address = (struct sockaddr_in *)args;

    // Create a new socket and connect to the server
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket() failed");
        return NULL;
    }

    if (connect(sock, (struct sockaddr *)address, sizeof(*address)) < 0) {
        perror("connect() failed");
        close(sock);
        return NULL;
    }

    // Set the socket options to handle network interruptions and data corruption
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &(int){1}, sizeof(int)) < 0) {
        perror("setsockopt() failed");
        close(sock);
        return NULL;
    }

    // Initialize the SSL/TLS context and start the SSL/TLS handshake
    SSL_CTX *ctx = SSL_CTX_new(TLSv1_2_client_method());
    if (!ctx) {
        printf("SSL_CTX_new() failed\n");
        close(sock);
        return NULL;
    }

    SSL *ssl = SSL_new(ctx);
    if (!ssl) {
        printf("SSL_new() failed\n");
        SSL_CTX_free(ctx);
        close(sock);
        return NULL;
    }

    if (SSL_set_fd(ssl, sock) < 0) {
        printf("SSL_set_fd() failed\n");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(sock);
        return NULL;
    }

    if (SSL_connect(ssl) <= 0) {
        printf("SSL_connect() failed\n");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(sock);
        return NULL;
    }

    // Start the data processing thread
    pthread_t process_data_thread;
    if (pthread_create(&process_data_thread, NULL, process_data, (void *)&address) < 0) {
        perror("pthread_create() failed");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(sock);
        return NULL;
    }

    // Start the data receiving thread
    pthread_t receive_data_thread;
    if (pthread_create(&receive_data_thread, NULL, receive_data, (void *)&address) < 0) {
        perror("pthread_create() failed");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(sock);
        return NULL;
    }

    // Start the SSL/TLS shutdown and cleanup
    if (SSL_shutdown(ssl) <= 0) {
        printf("SSL_shutdown() failed\n");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(sock);
        return NULL;
    }

    if (SSL_free(ssl) < 0) {
        printf("SSL_free() failed\n");
        SSL_CTX_free(ctx);
        close(sock);
        return NULL;
    }

    if (SSL_CTX_free(ctx) < 0) {
        printf("SSL_CTX_free() failed\n");
        close(sock);
        return NULL;
    }

    close(sock);

    return NULL;
}

int main(int argc, char **argv) {
