        perror("pthread_create() failed");
        return 1;
    }

    // Start the data processing thread
    pthread_t process_data_thread;
    if (pthread_create(&process_data_thread, NULL, process_data, (void *)&address) < 0) {
        perror("pthread_create() failed");
        return 1;
    }

    // Wait for the SSL/TLS handshake and data processing threads to complete before exiting
    if (pthread_join(initialize_ssl_thread, NULL) < 0 || pthread_join(receive_data_thread, NULL) < 0 || pthread_join(process_data_thread, NULL) < 0) {
        perror("pthread_join() failed");
        return 1;
    }

    printf("The largest integer value encountered so far is %d\n", largest_value);

    return 0;
}
