import os
import hashlib
from concurrent.futures import ProcessPoolExecutor
from data_service import get_metadata

def compute_hash(filepath):
    """Computes the MD5 hash of a file using a 4096-byte chunk size"""
    BUF_SIZE = 4096
    with open(filepath, 'rb') as f:
        hasher = hashlib.md5()
        while True:
            data = f.read(BUF_SIZE)
            if not data:
                break
            hasher.update(data)
        return hasher.hexdigest()

def process_file(filepath):
    """Processes a file and computes its MD5 hash"""
    try:
        with open(filepath, 'rb') as f:
            md5 = compute_hash(f)
            return (filepath, md5)
    except FileNotFoundError:
        # Handle missing files gracefully
        return (filepath, None)

def process_directory(directory):
    """Recursively scans a directory and processes all files"""
    for root, dirs, files in os.walk(directory):
        for file in files:
            yield os.path.join(root, file)

def process_file_with_metadata(filepath, metadata):
    """Processes a file and computes its MD5 hash while handling metadata lookups"""
    try:
        md5 = compute_hash(filepath)
        return (filepath, md5, metadata)
    except FileNotFoundError:
        # Handle missing files gracefully
        return (filepath, None, metadata)

def process_directory_with_metadata(directory):
    """Recursively scans a directory and processes all files, handling metadata lookups"""
    for root, dirs, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            try:
                metadata = get_metadata(filepath)
                yield process_file_with_metadata(filepath, metadata)
            except FileNotFoundError:
                # Handle missing files gracefully
                yield (filepath, None, metadata)

def run_processing(directory):
    """Runs the processing of a directory and returns a report"""
    with ProcessPoolExecutor() as executor:
        tasks = [executor.submit(process_directory_with_metadata, directory)]
        results = [task.result() for task in tasks]
    return generate_report(results)

def generate_report(results):
    """Generates a report summarizing the processing status"""
    total_files = 0
    processed_files = 0
    failed_files = []
    warnings = []
    for result in results:
        if isinstance(result, tuple):
            total_files += 1
            if result[2] is not None:
                processed_files += 1
            else:
                failed_files.append((result[0], result[2]))
        else:
            warnings.append(result)
    return {
        'total_files': total_files,
        'processed_files': processed_files,
        'failed_files': failed_files,
        'warnings': warnings,
    }

if __name__ == "__main__":
    directory = "/path/to/directory"
    report = run_processing(directory)
    print(report)']

