            }
            List<JSONObject> synergies = new ArrayList<>();
            for (String synergyMoveName : primaryWeaknesses) {
                if (!dbQueryCache.containsKey(synergyMoveName)) {
                    JSONArray jsonSynergies = getSynergies(moveName, synergyMoveName);
                    dbQueryCache.put(synergyMoveName, jsonSynergies);
                }
            }
        }

        // Print the final report and close connections
        System.out.println(report.toString());
        dataSource.close();
    }

    private static JSONObject getPokemonData(String name) {
