            return null;
        }
    }

    private static String getTerrain(String location) {
        try {
            return new JSONObject(new URL("https://api.openweathermap.org/data/2.5/terrain?q=" + location).openStream())
                    .getString("terrain");
        } catch (IOException | JSONException e) {
            return null;
        }
    }

    private static JSONObject getMoveData(String name) {
        try {
            return new JSONObject(new URL("https://pokeapi.co/api/v2/move/" + name).openStream());
        } catch (IOException e) {
            return null;
        }
    }

    private static JSONArray getSynergies(String moveName1, String moveName2) {
        try {
            JSONObject moveData1 = new JSONObject(new URL("https://pokeapi.co/api/v2/move/" + moveName1).openStream());
            JSONObject moveData2 = new JSONObject(new URL("https://pokeapi.co/api/v2/move/" + moveName2).openStream());
            if (moveData1.getString("type").equalsIgnoreCase(moveData2.getString("type"))) {
                return null;
            }
            JSONArray synergies = new JSONArray();
            for (String typeName : moveData1.getJSONArray("type")) {
                if (isWeakAgainst(moveData2.getString("type"), typeName)) {
                    synergies.put(moveData1.getString("name"));
                    break;
                }
            }
            return synergies;
        } catch (IOException | JSONException e) {
            return null;
        }
    }

    private static boolean isWeakAgainst(String moveType, String pokemonType) {
        // This function returns whether a Pokémon of the given type is weak against a move of the given type.
        // For simplicity, we'll assume that all moves are super effective against the same types as their counterparts in the opposite type effectiveness ladder (e.g., fire is super effective against water, grass, electric, and ice).
        switch (moveType) {
            case "normal":
                return pokemonType.equalsIgnoreCase("rock") || pokemonType.equalsIgnoreCase("bug");
            case "fire":
                return pokemonType.equalsIgnoreCase("water") || pokemonType.equalsIgnoreCase("grass") || pokemonType.equalsIgnoreCase("electric") || pokemonType.equalsIgnoreCase("ice");
            case "water":
                return pokemonType.equalsIgnoreCase("fire") || pokemonType.equalsIgnoreCase("electric");
            case "grass":
                return pokemonType.equalsIgnoreCase("water") || pokemonType.equalsIgnoreCase("electric") || pokemonType.equalsIgnoreCase("ice");
            case "electric":
                return pokemonType.equalsIgnoreCase("water") || pokemonType.equalsIgnoreCase("ground");
            case "ice":
                return pokemonType.equalsIgnoreCase("fire") || pokemonType.equalsIgnoreCase("flying") || pokemonType.equalsIgnoreCase("dragon");
            case "fighting":
                return pokemonType.equalsIgnoreCase("normal") || pokemonType.equalsIgnoreCase("rock") || pokemonType.equalsIgnoreCase("bug") || pokemonType.equalsIgnoreCase("steel");
            case "poison":
                return pokemonType.equalsIgnoreCase("grass") || pokemonType.equalsIgnoreCase("fairy") || pokemonType.equalsIgnoreCase("dragon");
            case "ground":
                return pokemonType.equalsIgnoreCase("electric") || pokemonType.equalsIgnoreCase("rock") || pokemonType.equalsIgnoreCase("steel");
            case "flying":
                return pokemonType.equalsIgnoreCase("electric") || pokemonType.equalsIgnoreCase("grass") || pokemonType.equalsIgnoreCase("fairy");
            case "psychic":
                return pokemonType.equalsIgnoreCase("bug") || pokemonType.equalsIgnoreCase("ghost") || pokemonType.equalsIgnoreCase("dragon");
            case "bug":
                return pokemonType.equalsIgnoreCase("grass") || pokemonType.equalsIgnoreCase("fairy");
            case "rock":
                return pokemonType.equalsIgnoreCase("normal") || pokemonType.equalsIgnoreCase("fire") || pokemonType.equalsIgnoreCase("ice") || pokemonType.equalsIgnoreCase("fighting") || pokemonType.equalsIgnoreCase("ground") || pokemonType.equalsIgnoreCase("steel");
            case "ghost":
                return pokemonType.equalsIgnoreCase("normal") || pokemonType.equalsIgnoreCase("psychic") || pokemonType.equalsIgnoreCase("bug");
            case "dragon":
                return pokemonType.equalsIgnoreCase("fairy") || pokemonType.equalsIgnoreCase("fire") || pokemonType.equalsIgnoreCase("ice") || pokemonType.equalsIgnoreCase("dragon");
            case "dark":
                return pokemonType.equalsIgnoreCase("ghost") || pokemonType.equalsIgnoreCase("fighting");
            case "steel":
                return pokemonType.equalsIgnoreCase("normal") || pokemonType.equalsIgnoreCase("rock") || pokemonType.equalsIgnoreCase("ice") || pokemonType.equalsIgnoreCase("flying") || pokemonType.equalsIgnoreCase("dragon");
            case "fairy":
                return pokemonType.equalsIgnoreCase("normal") || pokemonType.equalsIgnoreCase("bug") || pokemonType.equalsIgnoreCase("steel");
        }
        return false;
    }
}
