class CustomLock {
    private:
        std::mutex mutex_;
        std::condition_variable cv_;
        bool locked_;

    public:
        CustomLock() : locked_(false) {}

        void lock() {
            while (true) {
                if (!locked_) {
                    std::unique_lock<std::mutex> lk(mutex_);
                    if (locked_) {
                        cv_.wait(lk);
                    } else {
                        locked_ = true;
                        break;
                    }
                }
            }
        }

        void unlock() {
            std::unique_lock<std::mutex> lk(mutex_);
            locked_ = false;
            cv_.notify_all();
        }
};
```
