// Encryption Service
struct EncryptionService {
    // AES and RSA algorithms supported
    algorithms: Vec<Algorithm>,

    // Environment variables for configuration
    env_vars: HashMap<String, String>,

    // Legacy C++ runtime library for memory management and multi-threading
    cpp_runtime: CPPRuntime,
}

// Algorithm enum for AES and RSA
enum Algorithm {
    Aes(AesAlgorithm),
    Rsa(RsaAlgorithm),
}

// AES algorithm enum
enum AesAlgorithm {
    Aes128,
    Aes192,
    Aes256,
}

// RSA algorithm enum
enum RsaAlgorithm {
    Rsa1024,
    Rsa2048,
    Rsa4096,
}

// CPPRuntime struct for managing memory and multi-threading
struct CPPRuntime {
    // Memory management functions
    malloc: fn(size_t) -> *mut c_void,
    free: fn(*mut c_void),

    // Multi-threading functions
    create_thread: fn(&str) -> Thread,
    join_thread: fn(Thread) -> i32,
}

// EncryptionService implementation
impl EncryptionService {
    // Initialize the encryption service with AES and RSA algorithms and CPP runtime library
    fn new() -> Self {
        let env_vars = HashMap::new();
        let cpp_runtime = CPPRuntime::new();

        EncryptionService {
            algorithms: vec![Algorithm::Aes(AesAlgorithm::Aes128), Algorithm::Rsa(RsaAlgorithm::Rsa2048)],
            env_vars,
            cpp_runtime,
        }
    }

    // Encrypt data with the selected algorithm and key
    fn encrypt(&self, data: &[u8]) -> Vec<u8> {
        let mut encrypted_data = vec![];

        for algorithm in self.algorithms.iter() {
            match algorithm {
                Algorithm::Aes(aes_algorithm) => {
                    // Use AES encryption with the selected key and IV
                    let aes_key = self.get_aes_key();
                    let iv = self.get_iv();
                    encrypted_data = encrypt_aes(aes_algorithm, &aes_key, &iv, data);
                }
                Algorithm::Rsa(rsa_algorithm) => {
                    // Use RSA encryption with the selected key and IV
                    let rsa_key = self.get_rsa_key();
                    let iv = self.get_iv();
                    encrypted_data = encrypt_rsa(rsa_algorithm, &rsa_key, &iv, data);
                }
            }
        }

        // Return the encrypted data
        encrypted_data
    }

    // Decrypt data with the selected algorithm and key
    fn decrypt(&self, data: &[u8]) -> Vec<u8> {
        let mut decrypted_data = vec![];

        for algorithm in self.algorithms.iter() {
            match algorithm {
                Algorithm::Aes(aes_algorithm) => {
                    // Use AES decryption with the selected key and IV
                    let aes_key = self.get_aes_key();
                    let iv = self.get_iv();
                    decrypted_data = decrypt_aes(aes_algorithm, &aes_key, &iv, data);
                }
                Algorithm::Rsa(rsa_algorithm) => {
                    // Use RSA decryption with the selected key and IV
                    let rsa_key = self.get_rsa_key();
                    let iv = self.get_iv();
                    decrypted_data = decrypt_rsa(rsa_algorithm, &rsa_key, &iv, data);
                }
            }
        }

        // Return the decrypted data
        decrypted_data
    }

    // Get the AES key from the environment variables
    fn get_aes_key(&self) -> [u8; 32] {
        let aes_key = self.env_vars.get("AES_KEY").unwrap();
        hex::decode(aes_key).unwrap()
    }

    // Get the IV from the environment variables
    fn get_iv(&self) -> [u8; 16] {
        let iv = self.env_vars.get("IV").unwrap();
        hex::decode(iv).unwrap()
    }

    // Get the RSA key from the environment variables
    fn get_rsa_key(&self) -> String {
        self.env_vars.get("RSA_KEY").unwrap().to_string()
    }
}
```
