#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std::chrono;

// Forward declaration of the Client class
class Client;

// Define the NetworkIOManager class
class NetworkIOManager {
public:
    // Constructor that takes a reference to the game server framework as an argument
    explicit NetworkIOManager(Server& server) : server_(server) {}

    // Function to handle incoming network messages from clients
    void onMessageReceived(Client* client, const std::string& message) {
        // Check if the message is a valid command
        if (isValidCommand(message)) {
            // Handle the message accordingly
            handleCommand(client, message);
        } else {
            // Ignore invalid messages and log a warning
            std::cout << "Received an invalid message from client: " << client->getId() << ". Message: \"" << message << "\"\n";
        }
    }

private:
    // Server reference to interact with the game server framework
    Server& server_;

    // Map of client IDs to Client instances
    std::unordered_map<int, Client*> clients_;

    // Mutex to protect concurrent access to the clients map
    std::mutex clientsMutex_;

    // Condition variable to signal when a new client has connected
    std::condition_variable newClientCondition_;

    // Thread pool to handle incoming network messages from clients
    std::vector<std::thread> messageHandlingThreads_;

    // Function to check if a message is a valid command
    bool isValidCommand(const std::string& message) {
        // Check if the message starts with a valid command prefix
        if (message.find("cmd:") != 0) return false;

        // Split the message into tokens and check if the first token is a recognized command
        std::vector<std::string> tokens = split(message, ' ');
        if (tokens[0] == "cmd:connect") {
            // Handle the connect command
            return true;
        } else if (tokens[0] == "cmd:disconnect") {
            // Handle the disconnect command
            return true;
        } else if (tokens[0] == "cmd:move") {
            // Handle the move command
            return true;
        } else if (tokens[0] == "cmd:attack") {
            // Handle the attack command
            return true;
        } else {
            // Ignore unknown commands and log a warning
            std::cout << "Received an unknown command from client: \"" << message << "\"\n";
            return false;
        }
    }

    // Function to handle a valid command
    void handleCommand(Client* client, const std::string& message) {
        // Split the message into tokens and extract the command name and arguments
        std::vector<std::string> tokens = split(message, ' ');
        std::string commandName = tokens[0].substr(4);
        std::vector<std::string> commandArgs;
        for (size_t i = 1; i < tokens.size(); ++i) {
            commandArgs.push_back(tokens[i]);
        }

        // Handle the command accordingly
        if (commandName == "connect") {
            handleConnectCommand(client, commandArgs);
        } else if (commandName == "disconnect") {
            handleDisconnectCommand(client, commandArgs);
        } else if (commandName == "move") {
            handleMoveCommand(client, commandArgs);
        } else if (commandName == "attack") {
            handleAttackCommand(client, commandArgs);
        } else {
            // Ignore unknown commands and log a warning
            std::cout << "Received an unknown command from client: \"" << message << "\"\n";
        }
    }

    // Function to handle the connect command
    void handleConnectCommand(Client* client, const std::vector<std::string>& args) {
        // Check if there is a free slot for this client in the server's slots array
        size_t freeSlot = server_.findFreeSlot();
        if (freeSlot == Server::NUM_SLOTS) {
            // No free slot found, disconnect the client
            std::cout << "Client with ID: " << client->getId() << " attempted to connect but there was no available slot.\n";
            sendMessage(client, "cmd:disconnect");
            return;
        }

        // Add the new client to the clients map and set its ID
        std::lock_guard<std::mutex> lock(clientsMutex_);
        clients_.emplace(freeSlot, client);
        client->setId(freeSlot);

        // Update the server's slots array and notify connected clients of the new connection
        server_.addClient(client);
        sendMessageToAll("cmd:connect " + std::to_string(client->getId()));
    }

    // Function to handle the disconnect command
    void handleDisconnectCommand(Client* client, const std::vector<std::string>& args) {
        // Check if the client is connected
        size_t id = client->getId();
        if (id == Server::INVALID_ID) return;

        // Remove the client from the clients map and set its ID to invalid
        std::lock_guard<std::mutex> lock(clientsMutex_);
        clients_.erase(id);
        client->setId(Server::INVALID_ID);

        // Update the server's slots array and notify connected clients of the disconnection
        server_.removeClient(client);
        sendMessageToAll("cmd:disconnect " + std::to_string(id));
    }

    // Function to handle the move command
    void handleMoveCommand(Client* client, const std::vector<std::string>& args) {
        // Check if the client is connected and has a valid ID
        size_t id = client->getId();
        if (id == Server::INVALID_ID) return;

        // Update the server's slots array with the new position of this client
        server_.updateSlot(id, args[0], args[1]);
    }

    // Function to handle the attack command
    void handleAttackCommand(Client* client, const std::vector<std::string>& args) {
        // Check if the client is connected and has a valid ID
        size_t id = client->getId();
        if (id == Server::INVALID_ID) return;

        // Update the server's slots array with the new position of this client
        server_.updateSlot(id, args[0], args[1]);
    }

    // Function to split a string into tokens using a delimiter character
    std::vector<std::string> split(const std::string& str, char delim) {
        std::vector<std::string> tokens;
        std::string token;
        for (size_t i = 0; i < str.length(); ++i) {
            if (str[i] == delim) {
                if (!token.empty()) {
                    tokens.push_back(token);
                    token.clear();
                }
            } else {
                token += str[i];
            }
        }
        if (!token.empty()) {
            tokens.push_back(token);
        }
        return tokens;
    }

    // Function to send a message to all connected clients
    void sendMessageToAll(const std::string& message) {
        for (size_t i = 0; i < Server::NUM_CLIENTS; ++i) {
            Client* client = server_.getClient(i);
            if (client != nullptr && client->isConnected()) {
                sendMessage(client, message);
            }
        }
    }

    // Function to send a message to a specific connected client
    void sendMessage(Client* client, const std::string& message) {
        client->sendMessage(message);
    }
};
```

In this example, we've implemented the `Server` class that handles incoming network connections and manages the clients that are currently connected. The `Server` class has a few important features:

* It uses the `asio::ip::tcp::acceptor` class to accept incoming TCP connections on a specified port number.
* It uses the `asio::ip::tcp::socket` class to handle the socket connection with each client that connects.
* It has a vector of clients that it manages, and it keeps track of which slots are currently free and which slots have connected clients.
* It uses the `split` function to split a string into tokens using a delimiter character. This is useful for parsing command messages from the clients.
* It provides functions for handling incoming network data from each client, such as `handleConnectCommand`, `handleDisconnectCommand`, `handleMoveCommand`, and `handleAttackCommand`. These functions check if the message is valid and take appropriate action based on the command.

The `Client` class represents a single connected client, and it has the following important features:

* It uses the `asio::ip::tcp::socket` class to handle the socket connection with the server.
* It has an ID that is assigned by the server when a new client connects, and it keeps track of its own connected status using a boolean variable.
* It provides functions for sending messages back to the server using `sendMessage`.

The `split` function is useful for parsing command messages from the clients. This function takes a string as input and returns a vector of strings that represent each token in the input string. The delimiter character used by this function is a space character, which means that the input string can be a simple command like "move 10 20" or it can be more complex with multiple arguments separated by spaces.

The `sendMessageToAll` and `sendMessage` functions are useful for sending messages to all connected clients or to a specific client, respectively. These functions take the message as input and send it back to the server using the socket connection.']

