namespace WeatherSystem
{
    public class WeatherProvider
    {
        private readonly Dictionary<string, string> _apiKeys;
        private readonly MemoryCache _cache;

        public WeatherProvider(IEnumerable<string> apiKeys)
        {
            _apiKeys = apiKeys.ToDictionary(k => k, v => v);
            _cache = new MemoryCache(new MemoryCacheOptions());
        }

        public async Task<WeatherData> GetWeatherAsync(string location)
        {
            var key = $"weather-{location}";

            if (!_cache.TryGetValue(key, out WeatherData weather))
            {
                var request = new RestRequest($"https://api.openweathermap.org/data/2.5/weather?q={location}&appid={_apiKeys[location]}");
                var client = new RestClient("https://api.openweathermap.org");

                try
                {
                    var response = await client.ExecuteAsync(request);
                    weather = JsonConvert.DeserializeObject<WeatherData>(response.Content);
                }
                catch (Exception e)
                {
                    Console.WriteLine($"Failed to retrieve weather data for location '{location}': {e.Message}");
                }

                if (weather != null)
                {
                    _cache.Set(key, weather, TimeSpan.FromHours(1));
                }
            }

            return weather;
        }
    }

    public class WeatherData
    {
        [JsonProperty("main")]
        public Main Main { get; set; }

        [JsonProperty("weather")]
