        }

        private XmlValidationResult ValidateXml(XDocument document, string schemaId)
        {
            if (!_schemas.Contains(schemaId))
            {
                throw new InvalidOperationException($"Unknown schema ID '{schemaId}'.");
            }

            var validationResult = new XmlValidationResult();
            // Implement XML validation logic here...

            return validationResult;
        }

        private string GetXPathQueryForFirstElement(XDocument document)
