// Rust function to measure compilation time and resident set size of a subprocess
use std::time::Instant;
use std::process::Command;

fn measure_compile(command: &str) -> i32 {
    let start = Instant::now();
    let mut child = Command::new("rustc")
        .arg(command)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    let end = Instant::now();
    let elapsed = end.duration_since(start);

    // Measure resident set size of subprocess using psutil
    let mut child = Command::new("ps")
        .arg("-o")
        .arg("rss=")
        .arg(child.id().to_string())
        .output()
        .unwrap();

    // Return exit code and resident set size of subprocess
    (child.status, elapsed.as_secs_f64(), child.stdout[0..])
}
