import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { CacheService } from './cache.service';
import { environment } from 'src/environments/environment';

@Injectable({
  providedIn: 'root'
})
export class DialogFieldService {

  constructor(private http: HttpClient, private cacheService: CacheService) {}

  getDialogFields(resourceId: string): Observable<any> {
    return this.http.get(`${environment.apiUrl}/dialog-fields/${resourceId}`).pipe(
      map((response: any) => {
        if (response.success) {
          // Cache the dialog fields for future use
          this.cacheService.set('dialogFields', response.data);
        }
        return response;
      })
    );
  }
}

export class CacheService {
  constructor(private cache: any = new Map()) {}

  get(key: string): any {
    return this.cache.get(key) || null;
  }

  set(key: string, value: any): void {
    this.cache.set(key, value);
  }
}"]

