        $this->passwordValidationService = $passwordValidationService;
        $this->loggingService = $loggingService;
        $this->cacheService = $cacheService;
        $this->rateLimiter = $rateLimiter;
        $this->retryMechanism = $retryMechanism;
    }

    public function updatePassword(User $user, string $newPassword): void {
        if (!$this->passwordValidationService->validate($newPassword)) {
            throw new PasswordValidationException("Invalid password");
        }

        $this->rateLimiter->throttle();

        try {
            $oldPassword = $user->getPassword();

            // Run system-level checks in the background
            runCommandBackground(function() use ($oldPassword, $newPassword) {
                // Audit or enforce policy changes
            });

            $this->cacheService->clearUserCache($user);

            $user->setPassword($newPassword);

            $this->loggingService->log("Updated password for user " . $user->getId());
        } catch (Exception $e) {
            // Retry mechanism to handle transient failures
            $this->retryMechanism->retry($e, function() use ($oldPassword, $newPassword) {
                $this->updatePassword($user, $newPassword);
            });
        }
    }
}
