import json
from threading import Lock
from typing import Dict, List

class JsonObjectManager:
    def __init__(self):
        self.objects = {}
        self.locks = {}

    def get_object(self, id: str) -> Dict:
        with self.locks[id]:
            return self.objects[id]

    def add_object(self, id: str, object: Dict):
        with self.locks[id]:
            self.objects[id] = object

class JsonFileManager:
    def __init__(self):
        self.files = {}
        self.locks = {}

    def get_file(self, path: str) -> List:
        with self.locks[path]:
            return self.files[path]

    def add_file(self, path: str, file: List):
        with self.locks[path]:
            self.files[path] = file

class JsonConfigManager:
    def __init__(self):
        self.config = {}
        self.locks = {}

    def get_config(self, key: str) -> Dict:
        with self.locks[key]:
            return self.config[key]

    def add_config(self, key: str, config: Dict):
        with self.locks[key]:
            self.config[key] = config

class JsonObjectFactory:
    def __init__(self):
        self.object_types = {}
        self.locks = {}

    def add_object_type(self, type_name: str, creator: Callable[[], Dict]):
        with self.locks[type_name]:
            self.object_types[type_name] = creator

    def create_object(self, type_name: str) -> Dict:
        with self.locks[type_name]:
            return self.object_types[type_name]()

class JsonFileReader:
    def __init__(self):
        self.file_manager = JsonFileManager()
        self.config_manager = JsonConfigManager()
        self.object_factory = JsonObjectFactory()

    def read_file(self, path: str) -> List:
        with open(path, "r") as file:
            data = json.load(file)
            return data["objects"]

    def load_file(self, path: str):
        self.file_manager.add_file(path, self.read_file(path))

    def get_file(self, path: str) -> List:
        return self.file_manager.get_file(path)

    def create_object(self, type_name: str) -> Dict:
        return self.object_factory.create_object(type_name)

class JsonConfigReader:
    def __init__(self):
        self.config_manager = JsonConfigManager()
        self.file_manager = JsonFileManager()
        self.object_factory = JsonObjectFactory()

    def read_config(self, key: str) -> Dict:
        with open(self.file_manager.get_file("config"), "r") as file:
            data = json.load(file)
            return data["config"][key]

    def load_config(self, key: str):
        self.config_manager.add_config(key, self.read_config(key))

    def get_config(self, key: str) -> Dict:
        return self.config_manager.get_config(key)

class JsonObjectWriter:
    def __init__(self):
        self.file_manager = JsonFileManager()
        self.object_factory = JsonObjectFactory()

    def write_object(self, object: Dict, path: str):
        with open(path, "r+") as file:
            data = json.load(file)
            data["objects"].append(object)
            file.seek(0)
            json.dump(data, file, indent=4)

    def create_object(self, type_name: str, object: Dict):
        return self.object_factory.create_object(type_name, object)

class JsonFileWriter:
    def __init__(self):
        self.file_manager = JsonFileManager()

    def write_file(self, path: str):
        with open(path, "w") as file:
            json.dump({"objects": []}, file, indent=4)

class JsonConfigWriter:
    def __init__(self):
        self.config_manager = JsonConfigManager()

    def write_config(self, key: str, config: Dict):
        with open(self.file_manager.get_file("config"), "r+") as file:
            data = json.load(file)
            data["config"][key] = config
            file.seek(0)
            json.dump(data, file, indent=4)

class JsonObjectRegistry:
    def __init__(self):
        self.object_types = {}
        self.locks = {}

    def add_object_type(self, type_name: str, creator: Callable[[], Dict]):
        with self.locks[type_name]:
            self.object_types[type_name] = creator

    def create_object(self, type_name: str) -> Dict:
        with self.locks[type_name]:
            return self.object_types[type_name]()

class JsonFileRegistry:
    def __init__(self):
        self.file_manager = JsonFileManager()
        self.locks = {}

    def add_file(self, path: str):
        with self.locks[path]:
            self.file_manager.add_file(path)

class JsonConfigRegistry:
    def __init__(self):
        self.config_manager = JsonConfigManager()
        self.locks = {}

    def add_config(self, key: str):
        with self.locks[key]:
            self.config_manager.add_config(key)

class JsonFactory:
    def __init__(self):
        self.object_registry = JsonObjectRegistry()
        self.file_registry = JsonFileRegistry()
        self.config_registry = JsonConfigRegistry()
        self.object_writer = JsonObjectWriter()
        self.file_writer = JsonFileWriter()
        self.config_writer = JsonConfigWriter()
        self.reader = JsonReader()

    def create_object(self, type_name: str) -> Dict:
        return self.object_registry.create_object(type_name)

    def load_file(self, path: str):
        self.file_registry.add_file(path)
        self.reader.load_file(path)

    def get_file(self, path: str) -> List:
        return self.reader.get_file(path)

    def write_object(self, object: Dict, path: str):
        self.object_writer.write_object(object, path)

    def create_config(self, key: str, config: Dict):
        self.config_registry.add_config(key)
        self.config_writer.write_config(key, config)
