    StateNode* node = newStateNode(state);
    if (node == NULL) {
        printf("ERROR: Unable to create a new node for the state %d\n", state);
        return;
    }
    if (stateList == NULL) {
        stateList = node;
    } else {
        StateNode* current = stateList;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

