    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5Init(&ctx);

    // Update the MD5 hash with the input string
    MD5Update(&ctx, input, length);

    // Finalize the MD5 hash and return it as a byte array
    unsigned char* output = (unsigned char*) malloc(16 * sizeof(char));
    MD5Final(output, &ctx);
    return output;
}
