    // URL of the REST API for storing and retrieving keys
    char *key_storage_url;
    // Authentication token for accessing the key storage service
    char *auth_token;
};

// Define the data encryption settings
struct DataEncryptionSettings {
    // Key type (AES, RSA, or Camellia)
    KeyType key_type;
    // Key length (in bits)
    int key_length;
    // Encryption mode (AES GCM or Camellia CBC)
    enum EncryptionMode encryption_mode;
};

// Define the data integrity settings
struct DataIntegritySettings {
    // Hashing algorithm (SHA-256)
    enum HashingAlgorithm hashing_algorithm;
    // HMAC key type (AES or Camellia)
    KeyType hmac_key_type;
    // HMAC key length (in bits)
    int hmac_key_length;
};

// Define the key management settings
struct KeyManagementSettings {
    // Key storage service settings
    struct KeyStorageServiceSettings *key_storage_service;
    // Data encryption settings
    struct DataEncryptionSettings *data_encryption_settings;
    // Data integrity settings
    struct DataIntegritySettings *data_integrity_settings;
};

// Define the library instance structure
struct LibraryInstance {
