    public class CloudStorageService : ICloudStorageService
    {
        private readonly ILogger<CloudStorageService> _logger;
        private readonly IConfiguration _configuration;
        private readonly Dictionary<string, CloudProviderConfig> _cloudProviders;

        public CloudStorageService(ILogger<CloudStorageService> logger, IConfiguration configuration)
        {
            _logger = logger;
            _configuration = configuration;
            _cloudProviders = new Dictionary<string, CloudProviderConfig>();
        }

        public async Task TransferData(CloudProviderType providerType, string bucketName, string filePath, Stream dataStream)
        {
            if (!_cloudProviders.ContainsKey(providerType))
            {
                throw new InvalidOperationException($"Invalid cloud provider type: {providerType}");
            }

            var config = _cloudProviders[providerType];
            var client = GetClient(config);
            var bucket = await GetBucketAsync(client, bucketName);

            // Upload data to the specified file path
            await bucket.UploadFromStreamAsync(filePath, dataStream);
        }

        public async Task<Stream> TransferData(CloudProviderType providerType, string bucketName, string filePath)
        {
            if (!_cloudProviders.ContainsKey(providerType))
            {
                throw new InvalidOperationException($"Invalid cloud provider type: {providerType}");
            }

            var config = _cloudProviders[providerType];
            var client = GetClient(config);
            var bucket = await GetBucketAsync(client, bucketName);

            // Download data from the specified file path
            return await bucket.DownloadToStreamAsync(filePath);
        }

        private async Task<AmazonS3Client> GetS3Client(CloudProviderConfig config)
        {
            var client = new AmazonS3Client(config.AccessKeyId, config.SecretAccessKey, config.Region);
            return client;
        }

        private async Task<AzureBlobClient> GetAzureBlobClient(CloudProviderConfig config)
        {
            var client = new AzureBlobClient(config.AccountName, config.AccountKey, config.Container);
            return client;
        }

        private CloudStorageClient GetClient(CloudProviderConfig config)
        {
            switch (config.Type)
            {
                case CloudProviderType.AWS:
                    return new CloudStorageClient(GetS3Client(config));
                case CloudProviderType.Azure:
                    return new CloudStorageClient(GetAzureBlobClient(config));
                default:
                    throw new ArgumentException($"Invalid cloud provider type: {config.Type}");
            }
        }

        private async Task<AmazonS3Bucket> GetS3BucketAsync(AmazonS3Client client, string bucketName)
        {
            var bucket = new AmazonS3Bucket(client, bucketName);
            return await bucket.CreateIfNotExistsAsync();
        }

        private async Task<AzureBlobContainer> GetAzureBlobContainerAsync(AzureBlobClient client, string containerName)
        {
            var container = new AzureBlobContainer(client, containerName);
            return await container.CreateIfNotExistsAsync();
        }

        private async Task<CloudStorageBucket> GetBucketAsync(CloudStorageClient client, string bucketName)
        {
            switch (client.GetType())
            {
                case typeof(AmazonS3Client):
                    return new CloudStorageBucket(client as AmazonS3Client, bucketName);
                case typeof(AzureBlobClient):
                    return new CloudStorageBucket(client as AzureBlobClient, bucketName);
            }
        }

        public async Task AddCloudProviderAsync(string name, CloudProviderType type, string accessKeyId, string secretAccessKey, string region = null)
        {
            _cloudProviders.Add(name, new CloudProviderConfig
            {
                Type = type,
                AccessKeyId = accessKeyId,
                SecretAccessKey = secretAccessKey,
                Region = region
            });
        }
    }

    public class CloudProviderConfig
    {
        public string Name { get; set; }
        public CloudProviderType Type { get; set; }
        public string AccessKeyId { get; set; }
        public string SecretAccessKey { get; set; }
        public string Region { get; set; }
        public string Container { get; set; }
    }

    public enum CloudProviderType
    {
        AWS,
        Azure
    }
}
