using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Text.Json;

namespace MyLibrary
{
    public class DataLoader
    {
        private readonly HttpClient _httpClient;
        private readonly IFileSystem _fileSystem;
        private readonly IDictionary<string, Func<object>> _factoryRegistry = new Dictionary<string, Func<object>>();

        public DataLoader(HttpClient httpClient, IFileSystem fileSystem)
        {
            _httpClient = httpClient;
            _fileSystem = fileSystem;
        }

        public async Task<T> LoadAsync<T>(string id, Func<Stream, T> parser) where T : class
        {
            try
            {
                // Try to load data from the cache first
                var path = GetCachePath(id);
                if (_fileSystem.FileExists(path))
                {
                    using var stream = _fileSystem.OpenRead(path);
                    return parser(stream);
                }

                // If not found in the cache, load it from the REST API
                var response = await _httpClient.GetAsync($"https://api.example.com/data/{id}");
                if (response.IsSuccessStatusCode)
                {
                    using var stream = await response.Content.ReadAsStreamAsync();
                    return parser(stream);
                }
            }
            catch (Exception ex)
            {
                // Log the error and retry after a delay
                Console.WriteLine($"Error loading data: {ex}");
            }

            return null;
        }

        public void RegisterFactory<T>(string id, Func<object> factory) where T : class
        {
            _factoryRegistry[id] = factory;
        }

        private string GetCachePath(string id)
        {
            return $"{_fileSystem.GetTempDirectory()}/{id}.json";
        }
    }
}
