const { exec } = require('child_process');
const { promisify } = require('util');
const execAsync = promisify(exec);

class CommandExecutor {
  constructor() {
    this.commandTimeout = process.env.COMMAND_TIMEOUT || 5000;
    this.loggingVerbosity = process.env.LOGGING_VERBOSITY || 'info';
  }

  async executeCommand(command, args) {
    const fullCommand = `${command} ${args.join(' ')}`;
    try {
      const result = await execAsync(fullCommand);
      return this.handleResult(result);
    } catch (error) {
      console.error(`Failed to execute command: ${fullCommand}`);
      return error;
    }
  }

  handleResult(result) {
    if (result.stderr || result.status !== 0) {
      throw new Error('Invalid command output');
    }
    return result.stdout;
  }
}

class DiagnosticModule {
  constructor() {
    this.executor = new CommandExecutor();
  }

  async executeDiagnostic(diagnosticType, args) {
    let diagnosticCommand;
    switch (diagnosticType) {
      case 'cpu':
        diagnosticCommand = 'cat /proc/cpuinfo';
        break;
      case 'memory':
        diagnosticCommand = 'cat /proc/meminfo';
        break;
      default:
        throw new Error(`Unsupported diagnostic type: ${diagnosticType}`);
    }
    try {
      const result = await this.executor.executeCommand(diagnosticCommand, args);
      return this.parseDiagnosticResult(result);
    } catch (error) {
      console.error(`Failed to execute diagnostic: ${diagnosticType}`);
      return error;
    }
