    src_ip: str
    dst_ip: str
    src_port: int
    dst_port: int

class EventManager:
    def __init__(self):
        self.events = []
        self.event_cache = {}
        self.lock = threading.Lock()

    def add_event(self, event: ConnectionEvent):
        with self.lock:
            self.events.append(event)
            self.event_cache[f"{event.src_ip}:{event.dst_port}"] = event

    def get_events(self, src_ip: str):
        with self.lock:
            return [e for e in self.events if e.src_ip == src_ip]

