            header = ["Timestamp", "Src IP", "Dst IP", "Src Port", "Dst Port"]
            writer.writerow(header)
            for event in self.events:
                row = [event.timestamp, event.src_ip, event.dst_ip, event.src_port, event.dst_port]
                writer.writerow(row)

class EventSource:
    def __init__(self):
        self.url = "https://example.com/events"
        self.last_update = 0

    def fetch_events(self):
        try:
            response = requests.get(self.url, params={"last_update": self.last_update})
            if response.status_code == 200:
                events = [ConnectionEvent(**event) for event in response.json()]
                self.last_update = max([event.timestamp for event in events])
                return events
        except Exception as e:
            logging.error(f"Error fetching events from {self.url}: {e}")
        return []

class EventHandler:
    def __init__(self, event_manager: EventManager):
        self.event_manager = event_manager
        self.lock = threading.Lock()

    def handle_events(self, events: List[ConnectionEvent]):
        with self.lock:
            for event in events:
                self.event_manager.add_event(event)

class EventMonitor:
    def __init__(self, event_handler: EventHandler):
        self.event_handler = event_handler
        self.event_source = EventSource()
        self.lock = threading.Lock()

    def monitor(self):
        while True:
            events = self.event_source.fetch_events()
            if events:
                self.event_handler.handle_events(events)
