    res = curl_easy_read(curl, bundle, (size_t)size, &read);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to read response data: %s\n", curl_easy_strerror(res));
        free(bundle);
        return NULL;
    }

    // Process the bundle and store it in the cache layer if enabled
    BundleInfo *info = (BundleInfo*)malloc(sizeof(BundleInfo));
    info->bundle = bundle;
    info->size = read;
    if (caching_enabled) {
        pthread_mutex_lock(&cache_layer.mutex);
        cache_layer.size += read;
        cache_layer.count++;
        pthread_mutex_unlock(&cache_layer.mutex);
    }

    // Clean up memory
    curl_easy_cleanup(curl);

    return info;
}

void *process_bundle(void *info) {
    BundleInfo *info = (BundleInfo*)info;
    void *bundle = info->bundle;
    size_t size = info->size;
    free(info);

    // Process the bundle here...

    return NULL;
}
