### 2.4.3.2. Caching with a fixed-size cache

In this approach, we keep a fixed number of items in the cache at all times. When a new item is added to the cache and it is full, the least recently used item (LRU) is removed from the cache. The LRU item is determined by the access time of each item in the cache.

The following is an example of how to implement a fixed-size caching mechanism using a linked list:
```c
// Define a node structure for the linked list
struct Node {
    void *data; // pointer to the data stored in the node
    size_t size; // size of the data in bytes
    struct Node *next; // pointer to the next node in the list
};

// Define a cache structure that holds the head and tail pointers of the linked list
struct Cache {
    int capacity; // maximum number of items that can be stored in the cache at any given time
    struct Node *head; // pointer to the head node of the linked list
    struct Node *tail; // pointer to the tail node of the linked list
};

// Define a function to add an item to the cache
void add_to_cache(struct Cache *cache, void *data, size_t size) {
    if (cache->size >= cache->capacity) {
        // If the cache is full, remove the least recently used item
        struct Node *node = cache->head;
        while (node->next != NULL && node->next != cache->tail) {
            node = node->next;
        }
        if (node == cache->tail) {
            // If the tail is not in the cache, move it to the head and remove it from the cache
            cache->head = cache->tail = NULL;
            free(node->data);
            free(node);
            node = NULL;
        } else {
            // Remove the item from the cache
            struct Node *temp = cache->head;
            while (temp->next != node) {
                temp = temp->next;
            }
            cache->head = temp->next;
            free(node->data);
            free(node);
        }
    }
    // Add the item to the head of the list
    struct Node *new_node = (struct Node*)malloc(sizeof(struct Node));
    new_node->data = data;
    new_node->size = size;
    if (cache->head == NULL) {
        cache->tail = cache->head = new_node;
    } else {
        new_node->next = cache->head;
        cache->head = new_node;
    }
    cache->size++;
}

// Define a function to retrieve an item from the cache
void *retrieve_from_cache(struct Cache *cache, size_t size) {
    void *data = NULL;
    struct Node *node = cache->head;
    while (node != NULL && node->size < size) {
        node = node->next;
    }
    if (node == NULL) {
        return data;
    }
    // Remove the item from the cache
    struct Node *temp = cache->head;
    while (temp->next != node) {
        temp = temp->next;
    }
    cache->head = temp->next;
    if (cache->tail == node) {
        cache->tail = NULL;
    }
    data = node->data;
    free(node);
    return data;
}
```

### 2.4.3.3. Caching with a dynamic cache size

In this approach, the number of items in the cache can change over time based on the current system state. The cache size can be adjusted dynamically based on factors such as the amount of available memory, the expected usage patterns, and other performance metrics.

The following is an example of how to implement a dynamic caching mechanism using a linked list:
```c
