        // Handle error
    }
    return read_offset;
}

// Define a function to start the async file reader thread loop
void* async_file_reader_thread_loop(void *arg) {
    struct async_file_reader_thread *thread = (struct async_file_reader_thread*) arg;
    int64_t read_offset = 0;
    while (1) {
        // Perform the actual read operation
        read_offset = async_file_reader_perform_read(thread->reader, read_offset);
        if (read_offset < 0) {
