#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <dirent.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Structure to represent a device log entry
typedef struct DeviceLogEntry {
    time_t timestamp;
    char* message;
} DeviceLogEntry;

// Linked list node for the doubly linked list of DeviceLogEntry structures
struct Node {
    DeviceLogEntry* data;
    struct Node* next;
};

// Doubly linked list to store device log entries
struct List {
    struct Node* head;
    struct Node* tail;
};

// Function to create a new node in the linked list
struct Node* create_node(DeviceLogEntry* data) {
    struct Node* node = malloc(sizeof(struct Node));
    if (!node) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to add a new device log entry to the linked list
void add_log_entry(struct List* list, DeviceLogEntry* entry) {
    struct Node* node = create_node(entry);
    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
}

// Function to remove a device log entry from the linked list
void remove_log_entry(struct List* list, DeviceLogEntry* entry) {
    struct Node* node = list->head;
    while (node && node->data != entry) {
        node = node->next;
    }
    if (node) {
        // Remove the node from the linked list
        if (node == list->head) {
            list->head = node->next;
        }
        if (node == list->tail) {
            list->tail = node->previous;
        }
        free(node);
    }
}

// Function to retrieve a device log entry from the linked list
DeviceLogEntry* get_log_entry(struct List* list, int index) {
    struct Node* node = list->head;
    while (index-- && node != NULL) {
        node = node->next;
    }
    return node ? node->data : NULL;
}

// Function to print a device log entry
void print_log_entry(DeviceLogEntry* entry) {
    printf("[%ld] %s\n", entry->timestamp, entry->message);
}

// Function to process a device log file
void process_log_file(struct List* list, const char* filename) {
    // Open the log file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Read the log file line by line
    char buffer[BUFSIZ];
    while (fgets(buffer, sizeof(buffer), fd) != NULL) {
        // Parse the log message and store it in a device log entry structure
        DeviceLogEntry* entry = malloc(sizeof(DeviceLogEntry));
        if (!entry) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        entry->timestamp = time(NULL);
        entry->message = strdup(buffer);

        // Add the device log entry to the linked list
        add_log_entry(list, entry);
    }

    // Close the log file
    close(fd);
}

// Function to process a directory of device log files recursively
void process_directory(struct List* list, const char* dirname) {
    // Open the directory for reading
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        perror("opendir");
        exit(EXIT_FAILURE);
    }

    // Read each entry in the directory and process it recursively
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char filename[PATH_MAX];
        snprintf(filename, sizeof(filename), "%s/%s", dirname, entry->d_name);
        if (entry->d_type == DT_DIR) {
            process_directory(list, filename);
        } else {
            process_log_file(list, filename);
        }
    }

    // Close the directory
    closedir(dir);
}

// Main function to process device logs in a high-performance, scalable environment
int main(int argc, char* argv[]) {
    // Initialize the linked list for storing device log entries
    struct List list;
    list.head = NULL;
    list.tail = NULL;

    // Process the specified directory of device logs recursively
    if (argc > 1) {
        process_directory(&list, argv[1]);
    }

    // Print all device log entries in chronological order
    struct Node* node = list.head;
    while (node != NULL) {
        print_log_entry(node->data);
        node = node->next;
    }

    return 0;
}
