#!/usr/bin/env python3

import os
import stat
import hashlib
import threading
from concurrent.futures import ThreadPoolExecutor

class FileHasher(object):
    def __init__(self, dirname):
        self.dirname = dirname
        self.files = []
        self.hashes = {}

    def compute_hashes(self, files):
        for file in files:
            with open(file, 'rb') as f:
                hash = hashlib.md5()
                while True:
                    chunk = f.read(1024)
                    if not chunk:
                        break
                    hash.update(chunk)
                self.hashes[os.path.basename(file)] = hash.hexdigest()

    def compute_directory(self, dirname):
        for root, dirs, files in os.walk(dirname):
            for file in files:
                full_path = os.path.join(root, file)
                if stat.S_ISREG(os.stat(full_path).st_mode):
                    self.files.append(full_path)

    def get_hashes(self):
        return self.hashes

def main():
    hasher = FileHasher('.')
    hasher.compute_directory('./')
    print("Computing hashes for files in the current directory...")
    hasher.compute_hashes(hasher.files)
    print("\nFiles with md5 hashes:")
    for file, hash in hasher.get_hashes().items():
        print(file + " - " + hash)

if __name__ == '__main__':
    main()
