    // Check if the key length is valid
    assert(key_length == KEY_SIZE_56 || key_length == KEY_SIZE_112 || key_length == KEY_SIZE_168);

    // Check if the plaintext length is valid
    assert(plaintext_len % BLOCK_SIZE_64 == 0);

    // Initialize the DES engine
    DES_engine *des = init_des();

    // Set the key
    des->set_key(des, key, key_length);

    // Encrypt the plaintext
    uint32_t ciphertext_len = 0;
    des->encrypt(des, plaintext, plaintext_len, &ciphertext[ciphertext_len], &ciphertext_len);

    // Free the DES engine
    free(des);
}

void decrypt(uint8_t *key, uint32_t key_length, uint8_t *ciphertext, uint32_t ciphertext_len, uint8_t *plaintext) {
    // Check if the key length is valid
    assert(key_length == KEY_SIZE_56 || key_length == KEY_SIZE_112 || key_length == KEY_SIZE_168);

    // Check if the ciphertext length is valid
    assert(ciphertext_len % BLOCK_SIZE_64 == 0);

    // Initialize the DES engine
    DES_engine *des = init_des();

    // Set the key
    des->set_key(des, key, key_length);

    // Decrypt the ciphertext
    uint32_t plaintext_len = 0;
    des->decrypt(des, ciphertext, ciphertext_len, &plaintext[plaintext_len], &plaintext_len);

    // Free the DES engine
    free(des);
}

int main() {
    // Define the key and plaintext/ciphertext data
    uint8_t *key = "0123456789abcdef";
    uint8_t *plaintext = "Hello World!";
    uint8_t *ciphertext = (uint8_t *)malloc(sizeof(uint8_t) * 16);

    // Encrypt the plaintext with a 56-bit key
    encrypt(key, KEY_SIZE_56, plaintext, strlen(plaintext), ciphertext);

    // Decrypt the ciphertext with a 56-bit key
    decrypt(key, KEY_SIZE_56, ciphertext, 16, plaintext);

    // Free the memory allocated for the ciphertext
    free(ciphertext);

    return 0;
}
