import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;

import org.json.JSONObject;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Service
public class PokemonAnalysisService {

    @Autowired
    private PokemonApi pokemonApi;

    @Autowired
    private MoveApi moveApi;

    @Autowired
    private TypeApi typeApi;

    @Autowired
    private WeaknessApi weaknessApi;

    @Autowired
    private GeneticApi geneticApi;

    @Autowired
    private RelationalDatabaseService relationalDbService;

    public CompletableFuture<List<Pokemon>> getPokemons(String[] names) {
        return CompletableFuture.supplyAsync(() -> {
            List<Pokemon> pokemons = new ArrayList<>();
            for (String name : names) {
                Pokemon pokemon = pokemonApi.getPokemonByName(name);
                if (pokemon != null) {
                    pokemons.add(pokemon);
                }
            }
            return pokemons;
        });
    }

    public CompletableFuture<Map<String, Move>> getMoves(List<Pokemon> pokemons) {
        return CompletableFuture.supplyAsync(() -> {
            Map<String, Move> moves = new HashMap<>();
            for (Pokemon pokemon : pokemons) {
                List<Move> moveList = moveApi.getMovesByPokemon(pokemon.getName());
                if (moveList != null) {
                    for (Move move : moveList) {
                        moves.put(move.getName(), move);
                    }
                }
            }
            return moves;
        });
    }

    public CompletableFuture<Map<String, Type>> getTypes(List<Pokemon> pokemons) {
        return CompletableFuture.supplyAsync(() -> {
            Map<String, Type> types = new HashMap<>();
            for (Pokemon pokemon : pokemons) {
                Type type = typeApi.getTypeByName(pokemon.getType());
                if (type != null) {
                    types.put(type.getName(), type);
                }
            }
            return types;
        });
    }

    public CompletableFuture<Map<String, Weakness>> getWeaknesses(List<Pokemon> pokemons) {
        return CompletableFuture.supplyAsync(() -> {
            Map<String, Weakness> weaknesses = new HashMap<>();
            for (Pokemon pokemon : pokemons) {
                List<Weakness> weaknessList = weaknessApi.getWeaknessesByPokemon(pokemon.getName());
                if (weaknessList != null) {
                    for (Weakness weakness : weaknessList) {
                        weaknesses.put(weakness.getName(), weakness);
                    }
                }
            }
            return weaknesses;
        });
    }

    public CompletableFuture<Map<String, Genetic>> getGenetics(List<Pokemon> pokemons) {
        return CompletableFuture.supplyAsync(() -> {
            Map<String, Genetic> genetics = new HashMap<>();
            for (Pokemon pokemon : pokemons) {
                Genetic genetic = geneticApi.getGeneticByName(pokemon.getName());
                if (genetic != null) {
                    genetics.put(genetic.getName(), genetic);
                }
            }
            return genetics;
        });
    }

    public CompletableFuture<List<Pokemon>> analyzePokemons(List<Pokemon> pokemons) {
        return getMoves(pokemons).thenCompose((moves) -> getTypes(pokemons))
                .thenCompose((types) -> getWeaknesses(pokemons))
                .thenCompose((weaknesses) -> getGenetics(pokemons))
                .thenApply((genetics) -> {
                    List<Pokemon> analyzedPokemons = new ArrayList<>();
                    for (Pokemon pokemon : pokemons) {
                        analyzedPokemons.add(analyzePokemon(pokemon, moves, types, weaknesses, genetics));
                    }
                    return analyzedPokemons;
                });
    }

    public CompletableFuture<Map<String, Move>> getMoveSynergies(List<Pokemon> pokemons) {
        return getMoves(pokemons).thenCompose((moves) -> {
            Map<String, Move> moveSynergies = new HashMap<>();
            for (Pokemon pokemon : pokemons) {
                List<Move> moves = this.getMovesByPokemon(pokemon);
                if (moves != null) {
                    for (Move move1 : moves) {
                        for (Move move2 : moves) {
                            MoveSynergy synergy = new MoveSynergy(move1, move2);
                            String key = synergy.getKey();
                            if (!moveSynergies.containsKey(key)) {
                                moveSynergies.put(key, synergy);
