                    }
                }
            }
            return moveSynergies;
        });
    }

    public CompletableFuture<Map<String, Type>> getTypeEffectiveness(List<Pokemon> pokemons) {
        return getTypes(pokemons).thenCompose((types) -> {
            Map<String, Type> typeEffectiveness = new HashMap<>();
            for (Pokemon pokemon : pokemons) {
                Type type = types.get(pokemon.getName());
                if (type != null) {
                    List<Type> effects = type.getEffectiveness();
                    if (effects != null) {
                        for (Type effect : effects) {
                            String key = effect.getName();
                            if (!typeEffectiveness.containsKey(key)) {
                                typeEffectiveness.put(key, effect);
                            } else {
                                Type existingEffect = typeEffectiveness.get(key);
                                if (existingEffect.isMorePowerfulThan(effect)) {
                                    continue;
                                }
                            }
                        }
                    }
                }
            }
            return typeEffectiveness;
        });
    }

    public CompletableFuture<Map<String, Weakness>> getWeaknessesByType(List<Pokemon> pokemons) {
        return getTypes(pokemons).thenCompose((types) -> {
            Map<String, Weakness> typeEffectiveness = new HashMap<>();
            for (Pokemon pokemon : pokemons) {
