    public CompletableFuture<Map<String, Move>> getMorePowerfulMoves(List<Pokemon> pokemons) {
        return getMoves(pokemons).thenCompose((moves) -> {
            Map<String, Move> morePowerfulMoves = new HashMap<>();
            for (Move move1 : moves.values()) {
                String key1 = move1.getName();
                if (!morePowerfulMoves.containsKey(key1)) {
                    morePowerfulMoves.put(key1, move1);
                } else {
                    Move existingMove = morePowerfulMoves.get(key1);
                    for (Move move2 : moves.values()) {
                        String key2 = move2.getName();
                        if (!morePowerfulMoves.containsKey(key2)) {
                            continue;
                        }
                        Move existingMove2 = morePowerfulMoves.get(key2);
                        if (move1.isMorePowerfulThan(move2)) {
                            morePowerfulMoves.put(key2, move1);
                        } else if (!existingMove.getName().equals(move2.getName()) && existingMove2.isMorePowerfulThan(move2)) {
                            morePowerfulMoves.put(key2, existingMove2);
                        }
                    }
                }
            }
            return morePowerfulMoves;
        });
    }

    public CompletableFuture<Map<String, Type>> getMorePowerfulTypes(List<Pokemon> pokemons) {
        return getTypes(pokemons).thenCompose((types) -> {
            Map<String, Type> morePowerfulTypes = new HashMap<>();
            for (Type type1 : types.values()) {
                String key1 = type1.getName();
                if (!morePowerfulTypes.containsKey(key1)) {
                    morePowerfulTypes.put(key1, type1);
                } else {
                    Type existingType = morePowerfulTypes.get(key1);
                    for (Type type2 : types.values()) {
                        String key2 = type2.getName();
