['```Rust
pub fn add_vertices_and_edges(graph: &mut Graph) {
    let num_vertices = 10; // Number of vertices to add
    let mut rng = rand::thread_rng();

    for _ in 0..num_vertices {
        let vertex_id = rng.gen_range(0, graph.get_num_vertices());
        let vertex = graph.add_vertex(vertex_id);
        let num_edges = rng.gen_range(0, graph.get_num_vertices() - 1);
        for _ in 0..num_edges {
            let neighbor = rng.gen_range(0, graph.get_num_vertices());
            vertex.add_edge(neighbor);
        }
    }
}
