using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace SQLExecutionUtility
{
    public class CommandExecutor : IDisposable
    {
        private readonly string _connectionString;
        private readonly ILogger<CommandExecutor> _logger;
        private readonly ConcurrentQueue<string> _commandQueue = new();
        private readonly SemaphoreSlim _semaphore = new(1, 1);
        private readonly Dictionary<string, object> _parameters = new();
        private SqlConnection _connection;

        public CommandExecutor(string connectionString, ILogger<CommandExecutor> logger)
        {
            _connectionString = connectionString;
            _logger = logger;
        }

        public async Task ExecuteAsync(string commandText, Dictionary<string, object> parameters = null)
        {
            if (parameters != null)
                _parameters.UnionWith(parameters);

            await _semaphore.WaitAsync();
            try
            {
                if (_connection == null || _connection.State != ConnectionState.Open)
                    _connection = new SqlConnection(_connectionString);
                _commandQueue.Enqueue(commandText);
                while (_commandQueue.TryDequeue(out string command))
                {
                    using var cmd = new SqlCommand(command, _connection);
                    foreach (var parameter in _parameters)
                        cmd.Parameters.AddWithValue(parameter.Key, parameter.Value);
                    try
                    {
                        await cmd.ExecuteNonQueryAsync();
                    }
                    catch (SqlException ex)
                    {
                        _logger.LogError(ex, "Failed to execute SQL command");
                    }
                }
            }
            finally
            {
                if (_connection != null && _connection.State == ConnectionState.Open)
                    await _connection.CloseAsync();
                _semaphore.Release();
            }
        }

        public void Dispose()
        {
            _semaphore?.Dispose();
            _commandQueue?.Clear();
            if (_connection != null && _connection.State == ConnectionState.Open)
                _connection.Close();
        }
    }
}

// Example usage:
var executor = new CommandExecutor(
    connectionString: "Server=(local);Database=MyDb;Trusted_Connection=True",
    logger: logger
);

await executor.ExecuteAsync("SELECT * FROM MyTable WHERE Id = @id", new Dictionary<string, object> { { "@id", 123 } });
await executor.ExecuteAsync("INSERT INTO MyTable (Name) VALUES (@name)", new Dictionary<string, object> { { "@name", "John" } });']

