import requests
from datetime import datetime

class ContentDeliveryNetwork:
    def __init__(self, edge_locations):
        self.edge_locations = edge_locations
        self.routing_table = {}
        self.available_capacity = {}
        self.in_use_capacity = {}
        self.content_sources = []
        self.cached_contents = {}

    def register_edge_location(self, edge_location):
        self.edge_locations[edge_location] = {'available_capacity': 0}

    def unregister_edge_location(self, edge_location):
        del self.edge_locations[edge_location]

    def register_content_source(self, content_source):
        self.content_sources.append(content_source)

    def unregister_content_source(self, content_source):
        self.content_sources.remove(content_source)

    def route_traffic(self, user_location, device_capabilities):
        # Determine the best edge location for the user based on their location and device capabilities
        best_edge_location = self.determine_best_edge_location(user_location, device_capabilities)

        # Route traffic to the best edge location
        return self.route_to_edge_location(best_edge_location)

    def determine_best_edge_location(self, user_location, device_capabilities):
        # Calculate the distance between each edge location and the user's location
        distances = {}
        for edge_location in self.edge_locations:
            distances[edge_location] = self.calculate_distance(user_location, edge_location)

        # Find the edge location with the shortest distance
        best_edge_location = min(distances, key=distances.get)

        # Check if the edge location has available capacity for the device capabilities
        if self.available_capacity[best_edge_location] >= device_capabilities['bandwidth'] and self.available_capacity[best_edge_location] >= device_capabilities['latency']:
            return best_edge_location

        # If no edge location has available capacity, return None
        return None

    def route_to_edge_location(self, edge_location):
        # Determine the best content source for the edge location
        best_content_source = self.determine_best_content_source(edge_location)

        # Route traffic to the best content source
        return self.route_to_content_source(best_content_source, edge_location)

    def determine_best_content_source(self, edge_location):
        # Calculate the distance between each content source and the edge location
        distances = {}
        for content_source in self.content_sources:
            distances[content_source] = self.calculate_distance(edge_location, content_source)

        # Find the content source with the shortest distance
        best_content_source = min(distances, key=distances.get)

        # Check if the content source is available for use
        if self.available_capacity[best_content_source] >= edge_location['bandwidth'] and self.available_capacity[best_content_source] >= edge_location['latency']:
            return best_content_source

        # If no content source is available, return None
        return None

    def route_to_content_source(self, content_source, edge_location):
        # Check if the content source is cached for the edge location
        if content_source['name'] in self.cached_contents and self.cached_contents[content_source['name']] == edge_location:
            return self.cached_contents[content_source['name']]

        # If not, fetch the content from the content source and cache it for the edge location
        response = requests.get(content_source['url'])
        self.cached_contents[content_source['name']] = response.text
        return self.cached_contents[content_source['name']]

    def optimize_cache(self, content_source):
        # Calculate the usage of cache for the content source
        cache_usage = self.calculate_cache_usage(content_source)

        # If the cache is over 90% full, evict some content to make room
        if cache_usage > 0.9:
            self.evict_content()

    def calculate_cache_usage(self, content_source):
        # Calculate the total size of cached contents for the content source
        total_size = sum(len(c) for c in self.cached_contents[content_source['name']].values())

        # Calculate the usage of cache for the content source as a percentage
        usage = total_size / content_source['max_cache_size']

        return usage

    def evict_content(self, content_source):
        # Select the least recently used cached contents for the content source
        least_recently_used = sorted(self.cached_contents[content_source['name']].items(), key=lambda x: x[1])[:int(len(self.cached_contents[content_source['name']]) * 0.1)]

        # Evict the least recently used cached contents for the content source
        for key, value in least_recently_used:
            del self.cached_contents[content_source['name']][key]

    def handle_error(self, error):
        # If an error occurs during content delivery, attempt to recover by retrying the request with a different edge location or content source
        if error == 'network partitioning':
            self.route_traffic()
        elif error == 'DNS failure':
            self.determine_best_edge_location()
        elif error == 'content versioning':
            self.route_to_content_source()

    def handle_disruption(self, disruption):
        # If a disruption occurs during content delivery, attempt to recover by retrying the request with a different edge location or content source
        if disruption == 'network partitioning':
            self.route_traffic()
        elif disruption == 'DNS failure':
            self.determine_best_edge_location()
        elif disruption == 'content versioning':
            self.route_to_content_source()

    def monitor_performance(self):
        # Monitor the performance of the CDN and adjust caching strategies accordingly
        pass
```
This code implements a scalable global CDN solution for a media streaming platform that supports video, audio, and interactive content delivery. The solution is designed to optimize content delivery while minimizing latency and bandwidth usage. It includes features such as error handling, disruption recovery, and performance monitoring."]

