// Define the supported VM features
enum class VmFeature { CPU_CAPACITY, MEMORY_CAPACITY, DISK_CAPACITY, NETWORK_SPEED, COST };

// Define the scaling thresholds for each cloud provider and feature
map<CloudProvider, map<VmFeature, int>> scaleThresholds = {
    { CloudProvider::AWS, { { VmFeature::CPU_CAPACITY, 50 }, { VmFeature::MEMORY_CAPACITY, 80 }, { VmFeature::DISK_CAPACITY, 90 }, { VmFeature::NETWORK_SPEED, 100 }, { VmFeature::COST, 50 } } },
    { CloudProvider::GCP, { { VmFeature::CPU_CAPACITY, 60 }, { VmFeature::MEMORY_CAPACITY, 80 }, { VmFeature::DISK_CAPACITY, 90 }, { VmFeature::NETWORK_SPEED, 100 }, { VmFeature::COST, 60 } } },
    { CloudProvider::AZURE, { { VmFeature::CPU_CAPACITY, 70 }, { VmFeature::MEMORY_CAPACITY, 85 }, { VmFeature::DISK_CAPACITY, 95 }, { VmFeature::NETWORK_SPEED, 100 }, { VmFeature::COST, 70 } } }
};

// Define the retry intervals for failed API calls
map<CloudProvider, int> retryIntervals = {
    { CloudProvider::AWS, 30 },
    { CloudProvider::GCP, 45 },
    { CloudProvider::AZURE, 60 }
};

// Define the failure recovery strategies for each cloud provider
map<CloudProvider, int> failureRecoveryStrategies = {
    { CloudProvider::AWS, FailureRecoveryStrategy::FAILOVER },
    { CloudProvider::GCP, FailureRecoveryStrategy::RETRY },
    { CloudProvider::AZURE, FailureRecoveryStrategy::FAIL_OVER }
};

// Define the caching mechanism for API calls
map<CloudProvider, int> apiCache = {
    { CloudProvider::AWS, 10 },
    { CloudProvider::GCP, 20 },
    { CloudProvider::AZURE, 30 }
};

class VmManager {
public:
    // Constructor to initialize the VM manager with a list of cloud providers and API credentials
    VmManager(const vector<CloudProvider>& cloudProviders, const map<string, string>& apiCredentials) {
        for (auto& provider : cloudProviders) {
            vmProviders[provider] = VmProvider(provider, apiCredentials);
        }
    }

    // Function to provision a VM instance on the specified cloud provider
    bool ProvisionVm(const CloudProvider& provider, const string& vmName, const map<string, string>& vmConfig) {
        auto providerIt = vmProviders.find(provider);
        if (providerIt == vmProviders.end()) {
            return false;
        }

        // Get the API credentials for the specified cloud provider
        auto& apiCredentials = apiCredentials[provider];

        // Provision the VM instance using the appropriate API call
        string response = providerIt->second.provisionVm(vmName, vmConfig);

        if (response == "") {
            return false;
        } else {
            // Parse the provisioning response and extract the VM ID and other relevant information
            auto vmId = parseResponse(response);
            // Store the VM ID in a cache for future reference
            vmCache[provider][vmName] = vmId;
            return true;
        }
    }

    // Function to deprovision a VM instance on the specified cloud provider
    bool DeprovisionVm(const CloudProvider& provider, const string& vmName) {
        auto providerIt = vmProviders.find(provider);
        if (providerIt == vmProviders.end()) {
            return false;
        }

        // Get the API credentials for the specified cloud provider
        auto& apiCredentials = apiCredentials[provider];

        // Deprovision the VM instance using the appropriate API call
        string response = providerIt->second.deprovisionVm(vmName);

        if (response == "") {
            return false;
        } else {
            // Parse the deprovisioning response and ensure that the VM was successfully deleted
            auto vmId = parseResponse(response);
            // Remove the VM ID from the cache
            vmCache[provider].erase(vmName);
            return true;
        }
    }

    // Function to scale a VM instance on the specified cloud provider based on demand metrics
    bool ScaleVm(const CloudProvider& provider, const string& vmName, int demandMetric) {
        auto providerIt = vmProviders.find(provider);
        if (providerIt == vmProviders.end()) {
            return false;
        }

        // Get the API credentials for the specified cloud provider
        auto& apiCredentials = apiCredentials[provider];

        // Scale the VM instance using the appropriate API call
        string response = providerIt->second.scaleVm(vmName, demandMetric);

        if (response == "") {
            return false;
        } else {
            // Parse the scaling response and extract the new VM configuration
            auto vmConfig = parseResponse(response);
            // Update the cached VM configuration
            vmCache[provider][vmName] = vmConfig;
