Here is an example implementation of the modular C library:
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <fcntl.h>

#define JOB_QUEUE_SIZE 10000
#define JOB_PRIORITY_HIGH 1
#define JOB_PRIORITY_MEDIUM 2
#define JOB_PRIORITY_LOW 3

typedef struct job {
    int id;
    char* name;
    char* type;
    char* status;
} job;

typedef struct job_queue {
    pthread_mutex_t mutex;
    int size;
    int front, rear;
    job** jobs;
} job_queue;

void job_init(job_queue* queue) {
    pthread_mutex_init(&queue->mutex, NULL);
    queue->size = JOB_QUEUE_SIZE;
    queue->front = 0;
    queue->rear = 0;
    queue->jobs = (job**) malloc(sizeof(job*) * queue->size);
}

void job_enqueue(job_queue* queue, job* job) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->rear == queue->size - 1) {
        // resize the queue if it is full
        int new_size = queue->size * 2;
        queue->jobs = (job**) realloc(queue->jobs, sizeof(job*) * new_size);
        queue->size = new_size;
    }
    // add the job to the end of the queue
    queue->jobs[queue->rear++] = job;
    pthread_mutex_unlock(&queue->mutex);
}

void job_dequeue(job_queue* queue) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->front == queue->rear) {
        // the queue is empty, do nothing
        return;
    }
    // remove and return the first job in the queue
    int id = queue->jobs[queue->front++];
    pthread_mutex_unlock(&queue->mutex);
}

void job_free(job* job) {
    free(job->name);
    free(job->type);
    free(job->status);
    free(job);
}

void job_print(job* job) {
    printf("Job ID: %d\n", job->id);
    printf("Job Name: %s\n", job->name);
    printf("Job Type: %s\n", job->type);
    printf("Job Status: %s\n", job->status);
}

void* job_handler(void* args) {
    // the thread will run indefinitely until it is stopped or terminated
    while (1) {
        // wait for a new job to arrive in the queue
        pthread_mutex_lock(&queue->mutex);
        if (queue->front == queue->rear) {
            // the queue is empty, sleep for a short period of time before trying again
            pthread_mutex_unlock(&queue->mutex);
            usleep(100000); // 100 ms
            continue;
        }
        // get the next job from the front of the queue
        job* job = queue->jobs[queue->front++];
        pthread_mutex_unlock(&queue->mutex);

        // handle the job and update its status
        if (strcmp(job->type, "high") == 0) {
            // high priority job
            sleep(5); // simulate a long-running task
            strcpy(job->status, "completed");
        } else if (strcmp(job->type, "medium") == 0) {
            // medium priority job
            sleep(2); // simulate a short-running task
            strcpy(job->status, "completed");
        } else if (strcmp(job->type, "low") == 0) {
            // low priority job
            sleep(1); // simulate a very short-running task
            strcpy(job->status, "completed");
        }

        // update the job's status in the queue
        pthread_mutex_lock(&queue->mutex);
        queue->jobs[queue->rear++] = job;
        pthread_mutex_unlock(&queue->mutex);
    }
}

int main() {
    // create a new job queue and start the job handler thread
    job_queue* queue = (job_queue*) malloc(sizeof(job_queue));
    job_init(queue);
    pthread_create(&job_handler, NULL, job_handler, NULL);

    // add some jobs to the queue
    job* high1 = (job*) malloc(sizeof(job));
    high1->id = 1;
    strcpy(high1->name, "High Priority Job 1");
    strcpy(high1->type, "high");
    strcpy(high1->status, "pending");
    job_enqueue(queue, high1);

    job* medium1 = (job*) malloc(sizeof(job));
    medium1->id = 2;
    strcpy(medium1->name, "Medium Priority Job 1");
    strcpy(medium1->type, "medium");
    strcpy(medium1->status, "pending");
    job_enqueue(queue, medium1);

    job* low1 = (job*) malloc(sizeof(job));
    low1->id = 3;
    strcpy(low1->name, "Low Priority Job 1");
    strcpy(low1->type, "low");
    strcpy(low1->status, "pending");
    job_enqueue(queue, low1);

    // print the jobs in the queue and their status
    pthread_mutex_lock(&queue->mutex);
    for (int i = 0; i < queue->rear; i++) {
        job* job = queue->jobs[i];
        printf("Job ID: %d\n", job->id);
        printf("Job Name: %s\n", job->name);
        printf("Job Type: %s\n", job->type);
        printf("Job Status: %s\n", job->status);
    }
    pthread_mutex_unlock(&queue->mutex);

    // wait for the job handler thread to finish
    pthread_join(job_handler, NULL);

    return 0;
}
```

This program creates a new job queue and starts a new thread that will handle jobs indefinitely. The main function adds three jobs to the queue with different priorities and waits for the handler thread to finish before exiting. The handler thread loops indefinitely, waiting for new jobs to arrive in the queue and handling them according to their priority.

The program uses a `pthread_mutex` to synchronize access to the job queue between the main function and the handler thread. This ensures that multiple threads do not try to read or modify the queue at the same time, which would cause race conditions and other issues.

Note that this is just an example program to illustrate the basic concepts of using a job queue with multiple threads in C. You will likely need to modify it to fit your specific needs and add additional features such as error handling, logging, and more advanced thread synchronization mechanisms.']

