using System;
using System.Threading.Tasks;
using System.IO;
using System.Security.Cryptography;
using System.Collections.Generic;

namespace SecureDataProcessor
{
    public class EncryptionHandler
    {
        private readonly IDictionary<string, AesCryptoServiceProvider> _aesProviders = new Dictionary<string, AesCryptoServiceProvider>();

        private readonly IDictionary<string, RsaCryptoServiceProvider> _rsaProviders = new Dictionary<string, RsaCryptoServiceProvider>();

        public Task DecryptMessage(string base64EncodedData, string key, string iv, string algorithm)
        {
            var result = default(string);

            switch (algorithm.ToLower())
            {
                case "aes":
                    var aesProvider = _aesProviders[key];
                    if (aesProvider == null)
                    {
                        throw new Exception("Invalid key");
                    }

                    result = aesProvider.Decrypt(base64EncodedData, iv);
                    break;
                case "tripledes":
                    var tripleDesProvider = _aesProviders[key];
                    if (tripleDesProvider == null)
                    {
                        throw new Exception("Invalid key");
                    }

                    result = tripleDesProvider.Decrypt(base64EncodedData, iv);
                    break;
                case "rsa":
                    var rsaProvider = _rsaProviders[key];
                    if (rsaProvider == null)
                    {
                        throw new Exception("Invalid key");
                    }

                    result = rsaProvider.Decrypt(base64EncodedData);
                    break;
                default:
                    throw new ArgumentException($"Unsupported algorithm '{algorithm}'", nameof(algorithm));
            }

            return Task.FromResult(result);
        }
    }
}
```
