            var user = await GetUserByUsernameAsync(username);
            if (user == null) {
                return null;
            }

            var hash = await _passwordManager.HashPasswordAsync(password);
            var isValid = await _imsClient.VerifyPasswordAsync(user.Id, hash);
            if (!isValid) {
