using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json.Linq;

namespace CloudStorageGateway
{
    public class TransferData
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<TransferData> _logger;

        public TransferData(IConfiguration configuration, ILogger<TransferData> logger)
        {
            _configuration = configuration;
            _logger = logger;
        }

        public async Task ReadAsync(string filePath, string bucketName, string providerType)
        {
            try
            {
                var cloudProviderClient = GetCloudProviderClient(providerType);
                var data = await cloudProviderClient.ReadFileAsync(filePath, bucketName);
                _logger.LogInformation($"Successfully read data from {bucketName} in {providerType}");
                return data;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to read data from {bucketName} in {providerType}");
                throw;
            }
        }

        public async Task WriteAsync(string filePath, string bucketName, string providerType, byte[] data)
        {
            try
            {
                var cloudProviderClient = GetCloudProviderClient(providerType);
                await cloudProviderClient.WriteFileAsync(filePath, bucketName, data);
                _logger.LogInformation($"Successfully wrote data to {bucketName} in {providerType}");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to write data to {bucketName} in {providerType}");
                throw;
            }
        }

        private ICloudProviderClient GetCloudProviderClient(string providerType)
        {
            switch (providerType.ToLower())
            {
                case "aws s3":
                    return new AwsS3Client(_configuration);
                case "azure blob storage":
                    return new AzureBlobStorageClient(_configuration);
                case "google cloud storage":
                    return new GoogleCloudStorageClient(_configuration);
            }
        }
    }
}
```
