```
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.IO;
using System.Security.Cryptography;
using System.Net;
using System.Net.Sockets;
using System.Web;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace MyGraphDatabaseService
{
    public class GraphDatabase
    {
        private readonly ILogger<GraphDatabase> _logger;
        private readonly string _databasePath;
        private readonly Dictionary<string, List<string>> _edges = new Dictionary<string, List<string>>();
        private readonly Dictionary<string, object> _vertices = new Dictionary<string, object>();

        public GraphDatabase(ILogger<GraphDatabase> logger, string databasePath)
        {
            _logger = logger;
            _databasePath = databasePath;
        }

        public async Task AddVertexAsync(string vertexId, object metadata)
        {
            // Use AES-256 encryption to protect the metadata
            byte[] encryptedMetadata = AesEncrypt(metadata);
            await File.WriteAllBytesAsync(_databasePath + "/" + vertexId + ".meta", encryptedMetadata);

            _vertices[vertexId] = metadata;
        }

        public async Task AddEdgeAsync(string sourceVertexId, string targetVertexId)
        {
            // Use AES-256 encryption to protect the edge metadata
            byte[] encryptedMetadata = AesEncrypt(sourceVertexId + " -> " + targetVertexId);
            await File.WriteAllBytesAsync(_databasePath + "/" + sourceVertexId + "-" + targetVertexId + ".meta", encryptedMetadata);

            if (_edges.ContainsKey(sourceVertexId))
            {
                _edges[sourceVertexId].Add(targetVertexId);
            }
            else
            {
                _edges.Add(sourceVertexId, new List<string> { targetVertexId });
            }
        }

        public async Task RemoveVertexAsync(string vertexId)
        {
            // Use AES-256 encryption to protect the metadata
            byte[] encryptedMetadata = AesEncrypt(_vertices[vertexId]);
            await File.WriteAllBytesAsync(_databasePath + "/" + vertexId + ".meta", encryptedMetadata);

            _vertices.Remove(vertexId);
        }

        public async Task RemoveEdgeAsync(string sourceVertexId, string targetVertexId)
        {
            // Use AES-256 encryption to protect the edge metadata
            byte[] encryptedMetadata = AesEncrypt(sourceVertexId + " -> " + targetVertexId);
            await File.WriteAllBytesAsync(_databasePath + "/" + sourceVertexId + "-" + targetVertexId + ".meta", encryptedMetadata);

            if (_edges.ContainsKey(sourceVertexId))
            {
                _edges[sourceVertexId].Remove(targetVertexId);
            }
        }

        public async Task<object> GetVertexMetadataAsync(string vertexId)
        {
            // Use AES-256 encryption to protect the metadata
            byte[] encryptedMetadata = await File.ReadAllBytesAsync(_databasePath + "/" + vertexId + ".meta");
            return AesDecrypt(encryptedMetadata);
        }

        public async Task<object> GetEdgeMetadataAsync(string sourceVertexId, string targetVertexId)
        {
            // Use AES-256 encryption to protect the edge metadata
            byte[] encryptedMetadata = await File.ReadAllBytesAsync(_databasePath + "/" + sourceVertexId + "-" + targetVertexId + ".meta");
            return AesDecrypt(encryptedMetadata);
        }

        private byte[] AesEncrypt(object data)
        {
            // Use a secure hash algorithm (e.g., SHA-256) to protect the metadata
            byte[] dataBytes = Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(data));
            using (AesManaged aes = new AesManaged())
            {
                aes.KeySize = 256;
                aes.BlockSize = 128;
                return aes.CreateEncryptor().TransformFinalBlock(dataBytes, 0, dataBytes.Length);
            }
        }

        private object AesDecrypt(byte[] encryptedData)
        {
            // Use a secure hash algorithm (e.g., SHA-256) to protect the metadata
            using (AesManaged aes = new AesManaged())
            {
                aes.KeySize = 256;
                aes.BlockSize = 128;
                return JsonConvert.DeserializeObject(Encoding.UTF8.GetString(aes.CreateDecryptor().TransformFinalBlock(encryptedData, 0, encryptedData.Length)));
            }
        }
    }
}
