```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>
#include "LTE_RRC_CU ksi_message_t.h"

// Define the structure for storing the messages
typedef struct LTE_RRC_CU ksi_message {
  int message_id;
  char *message;
} LTE_RRC_CU ksi_message_t;

// Define a linked list to store the messages
struct LTE_RRC_CU ksi_message_list {
  struct LTE_RRC_CU ksi_message_t *head;
  struct LTE_RRC_CU ksi_message_t *tail;
};

// Define a mutex for protecting the linked list
pthread_mutex_t message_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a semaphore for waiting on messages to be added
sem_t message_added_sem = SEM_INITIALIZER(0);

// Define a function for adding a message to the linked list
void add_message(LTE_RRC_CU ksi_message_t *message) {
  // Lock the mutex
  pthread_mutex_lock(&message_list_mutex);

  // Create a new node for the message
  struct LTE_RRC_CU ksi_message_t *new_node = malloc(sizeof(struct LTE_RRC_CU ksi_message_t));
  new_node->message_id = message->message_id;
  new_node->message = message->message;

  // Add the node to the end of the linked list
  if (message_list.tail == NULL) {
    message_list.head = new_node;
    message_list.tail = new_node;
  } else {
    message_list.tail->next = new_node;
    message_list.tail = new_node;
  }

  // Unlock the mutex and signal the semaphore
  pthread_mutex_unlock(&message_list_mutex);
  sem_post(&message_added_sem);
}

// Define a function for retrieving a message from the linked list
LTE_RRC_CU ksi_message_t *get_message(int message_id) {
  // Lock the mutex
  pthread_mutex_lock(&message_list_mutex);

  // Search for the node with the given ID
  struct LTE_RRC_CU ksi_message_t *node = message_list.head;
  while (node != NULL) {
    if (node->message_id == message_id) {
      break;
    }
    node = node->next;
  }

  // Unlock the mutex and return the node
  pthread_mutex_unlock(&message_list_mutex);
  return node;
}

// Define a function for updating a message in the linked list
void update_message(LTE_RRC_CU ksi_message_t *message) {
  // Lock the mutex
  pthread_mutex_lock(&message_list_mutex);

  // Search for the node with the given ID
  struct LTE_RRC_CU ksi_message_t *node = message_list.head;
  while (node != NULL) {
    if (node->message_id == message->message_id) {
      break;
    }
    node = node->next;
  }

  // Update the message in the node
  node->message = message->message;

  // Unlock the mutex
  pthread_mutex_unlock(&message_list_mutex);
}

// Define a function for iterating over the messages in the linked list
void iterate_messages(void (*callback)(LTE_RRC_CU ksi_message_t *)) {
  // Lock the mutex
  pthread_mutex_lock(&message_list_mutex);

  // Iterate over the nodes in the linked list
  struct LTE_RRC_CU ksi_message_t *node = message_list.head;
  while (node != NULL) {
    callback(node);
    node = node->next;
  }

  // Unlock the mutex
  pthread_mutex_unlock(&message_list_mutex);
}
```
