        auto buffer = serializer.serialize(metrics);

        // Send the buffer to the logging service asynchronously
        loggingService.sendBufferAsync(buffer, bufferSize);
    }
}

async PersistMetricsToDatabase(vector<Metrics> metrics) {
    // Asynchronously process and store the logged metrics into a relational database
    while (!metrics.empty()) {
        // Handle database connection pooling to optimize performance
        DatabaseConnection conn = dbPool.getConnection();

        // Bulk insert the metrics into the database
        vector<Metrics> processedMetrics;
        for (const auto& metric : metrics) {
            // Skip invalid metrics or those that exceed threshold limits
            if (!metric.isValid() || metric.getValue() > threshold) {
                continue;
            }

            // Add the valid metric to the processed metrics vector
            processedMetrics.push_back(metric);
        }

        // Store the processed metrics in the database
        conn.bulkInsert(processedMetrics);

        // Handle network failures and transient database errors gracefully
        try {
            conn.commit();
        } catch (const DatabaseException& e) {
            conn.rollback();
            throw;
        }
    }
}

