['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <limits.h>
#include <errno.h>
#include <openssl/des.h>

// Define the command-line options
enum {
    OPT_HELP = 'h',
    OPT_MODE = 'm',
    OPT_KEY = 'k',
    OPT_INPUT = 'i',
    OPT_OUTPUT = 'o',
    OPT_VERBOSE = 'v'
};

// Define the encryption modes
enum {
    MODE_ECB,
    MODE_EDE,
    MODE_EDE3,
    MODE_CFB,
    MODE_NULL
};

// Define the error codes
enum {
    ERR_INVALID_MODE = 1,
    ERR_INVALID_KEY = 2,
    ERR_IO_ERROR = 3
};

// Define the command-line options structure
struct option long_options[] = {
    {"help", no_argument, NULL, OPT_HELP},
    {"mode", required_argument, NULL, OPT_MODE},
    {"key", required_argument, NULL, OPT_KEY},
    {"input", required_argument, NULL, OPT_INPUT},
    {"output", required_argument, NULL, OPT_OUTPUT},
    {"verbose", no_argument, NULL, OPT_VERBOSE},
    {NULL, 0, NULL, 0}
};

// Define the usage message
static const char *usage = "Usage: crypt [options]\n\n"
                           "-h --help         Display this help message\n"
                           "-m --mode <mode>  Set the encryption mode (ECB, EDE, EDE3, CFB, NULL)\n"
                           "-k --key <key>    Set the encryption key\n"
                           "-i --input <file> Read input from a file\n"
                           "-o --output <file>Write output to a file\n"
                           "-v --verbose      Enable verbose logging for debugging purposes";

// Define the encryption functions
void encrypt(const unsigned char *key, const unsigned char *input, unsigned char *output) {
    DES_cblock key_block;
    DES_cblock input_block;
    DES_cblock output_block;

    memcpy(key_block, key, 8);
    memcpy(input_block, input, 8);
    DES_encrypt3(&input_block, &output_block, &key_block, DES_ENCRYPT);
    memcpy(output, output_block, 8);
}

void decrypt(const unsigned char *key, const unsigned char *input, unsigned char *output) {
    DES_cblock key_block;
    DES_cblock input_block;
    DES_cblock output_block;

    memcpy(key_block, key, 8);
    memcpy(input_block, input, 8);
    DES_encrypt3(&input_block, &output_block, &key_block, DES_DECRYPT);
    memcpy(output, output_block, 8);
}

// Define the error handling functions
void handle_error(int err) {
    switch (err) {
        case ERR_INVALID_MODE:
            fprintf(stderr, "Error: Invalid encryption mode specified\n");
            break;
        case ERR_INVALID_KEY:
            fprintf(stderr, "Error: Invalid encryption key specified\n");
            break;
        case ERR_IO_ERROR:
            perror("I/O error");
            break;
    }
}

int main(int argc, char **argv) {
    // Parse the command-line options
    int c;
    while ((c = getopt_long(argc, argv, "hm:k:i:o:v", long_options, NULL)) != -1) {
        switch (c) {
            case OPT_HELP:
                fprintf(stdout, "%s", usage);
                return 0;
            case OPT_MODE:
                if (!strcmp(optarg, "ECB")) {
                    mode = MODE_ECB;
                } else if (!strcmp(optarg, "EDE")) {
                    mode = MODE_EDE;
                } else if (!strcmp(optarg, "EDE3")) {
                    mode = MODE_EDE3;
                } else if (!strcmp(optarg, "CFB")) {
                    mode = MODE_CFB;
                } else if (!strcmp(optarg, "NULL")) {
                    mode = MODE_NULL;
                } else {
                    handle_error(ERR_INVALID_MODE);
                    return 1;
                }
                break;
            case OPT_KEY:
                key = optarg;
                if (strlen(key) != 8) {
                    handle_error(ERR_INVALID_KEY);
                    return 1;
                }
                break;
            case OPT_INPUT:
                input_file = fopen(optarg, "rb");
                if (!input_file) {
                    handle_error(ERR_IO_ERROR);
                    return 1;
                }
                break;
            case OPT_OUTPUT:
                output_file = fopen(optarg, "wb");
                if (!output_file) {
                    handle_error(ERR_IO_ERROR);
                    return 1;
                }
                break;
            case OPT_VERBOSE:
                verbose = 1;
        }
    }

    // Check for missing or invalid options
    if (!mode || !key || !input_file || !output_file) {
        handle_error(ERR_INVALID_OPTIONS);
        return 1;
    }

    // Handle the encryption operation
    unsigned char input[8];
    unsigned char output[8];
    while (fread(input, sizeof(char), 8, input_file) == 8) {
        if (verbose) {
            printf("Encrypting...");
        }
        encrypt(key, input, output);
        fwrite(output, sizeof(char), 8, output_file);
    }

    // Handle the decryption operation
    while (fread(input, sizeof(char), 8, input_file) == 8) {
        if (verbose) {
            printf("Decrypting...");
        }
        decrypt(key, input, output);
        fwrite(output, sizeof(char), 8, output_file);
    }

    // Close the files and return successfully
    fclose(input_file);
    fclose(output_file);
    return 0;
}
```

In this example, we're using the `DES_cblock` structure from the OpenSSL library to represent the 64-bit encryption keys. We're also using the `DES_encrypt3()` function from the same library to perform the actual encryption and decryption operations. The `handle_error()` function is used to print error messages for the user.

The main program first parses the command-line options using `getopt()`. We're only supporting a few options: `-h` or `--help`, which prints the usage information; `-m` or `--mode`, which specifies the encryption mode (ECB, EDE, EDE3, CFB, NULL); `-k` or `--key`, which specifies the 64-bit encryption key; `-i` or `--input`, which specifies the input file; and `-o` or `--output`, which specifies the output file.

The `handle_error()` function is used to print error messages for the user. In this example, we're only handling a few different types of errors: invalid encryption mode specified (`ERR_INVALID_MODE`), invalid encryption key specified (`ERR_INVALID_KEY`), and I/O error (`ERR_IO_ERROR`).

Inside the `main()` function, we first check if all the required options are present and valid. If not, we print an error message using `handle_error()`. We then handle the encryption operation by reading 8 bytes at a time from the input file and writing the encrypted data to the output file using the `encrypt()` function. Similarly, we handle the decryption operation by reading 8 bytes at a time from the input file and writing the decrypted data to the output file using the `decrypt()` function.

Note that this is just an example program, and you will need to modify it to suit your specific needs. For example, you may want to add additional options or change the encryption mode or key length.']

