void insertAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
    auto it = list.begin();
    bool found = false;
    while (it != list.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        list.push_back(value);
    } else {
        list.insert_after(it, value);
    }
}
