import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import com.google.gson.*;

public class EventProcessor {
    private static final Logger logger = Logger.getLogger(EventProcessor.class.getName());

    public static void processAndAggregateEvents(List<String> events) {
        // Initialize a list of event types and a map to store the event counts
        List<String> eventTypes = new ArrayList<>();
        Map<String, Integer> eventCounts = new HashMap<>();

        // Iterate through the events and update the event types and counts
        for (String event : events) {
            String eventType = getEventType(event);

            if (!eventTypes.contains(eventType)) {
                eventTypes.add(eventType);
            }

            int count = eventCounts.getOrDefault(eventType, 0) + 1;
            eventCounts.put(eventType, count);
        }

        // Log the event types and counts
        logger.info("Event types: " + Arrays.toString(eventTypes.toArray()));
        logger.info("Event counts: " + eventCounts);
    }

    private static String getEventType(String event) {
        JsonObject json = new Gson().fromJson(event, JsonObject.class);
        return json.getAsJsonPrimitive("type").getAsString();
    }
}
