['```scss
import asyncio
from typing import List, Dict, Optional

class StreamAndAggregateData:
    def __init__(self, api_endpoints: List[str], data_stores: Dict[str, str], configs: Dict[str, Any]):
        self.api_endpoints = api_endpoints
        self.data_stores = data_stores
        self.configs = configs

    async def stream_and_aggregate(self):
        tasks = []
        for endpoint in self.api_endpoints:
            task = asyncio.create_task(self._stream_data(endpoint))
            tasks.append(task)

        await asyncio.gather(*tasks)

    async def _stream_data(self, endpoint):
        while True:
            try:
                data = await self._fetch_data(endpoint)
                if not data:
                    break
                self._process_data(data)
            except Exception as e:
                print(f"Error streaming data from {endpoint}: {e}")
                await asyncio.sleep(self.configs["retry_delay"])

    async def _fetch_data(self, endpoint):
        headers = {"Authorization": f"Bearer {self.configs['api_key']}"}
        response = requests.get(endpoint, headers=headers)
        if response.status_code == 200:
            return response.json()
        else:
            return None

    def _process_data(self, data):
        for record in data:
            self._aggregate_record(record)

    async def _aggregate_record(self, record):
        await asyncio.to_thread(self._store_record, record)

    async def _store_record(self, record):
        for store in self.data_stores:
            await asyncio.to_thread(store.insert, record)

if __name__ == "__main__":
    api_endpoints = ["https://api1.com", "https://api2.com"]
    data_stores = {
        "store1": Store1(),
        "store2": Store2()
    }
    configs = {
        "retry_delay": 30,
        "api_key": "my-api-key"
    }
    stream_and_aggregate = StreamAndAggregateData(api_endpoints, data_stores, configs)
    asyncio.run(stream_and_aggregate.stream_and_aggregate())
