class MovingAverageDistance {
public:
    // Constructor
    MovingAverageDistance(const std::vector<DataPoint>& initialPoints) : windowSize(10), numReaders(5) {}

    // Function for computing and updating the moving average distance between consecutive points
    void updateAverageDistance(const DataPoint& point) {
        if (window.size() == 0 || window.back().timestamp < point.timestamp - 1) {
            // Add a new data point to the end of the window
            window.push_back(point);
        } else {
            // Remove outdated data points from the beginning of the window
            while (window.size() > 0 && window.front().timestamp < point.timestamp - windowSize) {
                window.pop_front();
            }
            // Add a new data point to the end of the window
            window.push_back(point);
        }
        // Compute and update the moving average distance
        double sum = 0;
        for (auto& p : window) {
            sum += std::sqrt((p.latitude - point.latitude) * (p.latitude - point.latitude) +
                             (p.longitude - point.longitude) * (p.longitude - point.longitude));
        }
        movingAverageDistance = sum / window.size();
    }

private:
    // Window size for computing the moving average distance
    int windowSize;

    // Vector of data points in the window
    std::vector<DataPoint> window;

    // Moving average distance between consecutive points
    double movingAverageDistance;

