}
```

### JsonUtils class

The `JsonUtils` class provides methods to serialize and deserialize JSON data in Java. It uses the Jackson library for JSON parsing and serialization.

```java
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

public class JsonUtils {

  private static final ObjectMapper objectMapper = new ObjectMapper();

  public static <T> String toJson(T value) {
    try {
      return objectMapper.writeValueAsString(value);
    } catch (JsonProcessingException e) {
      throw new RuntimeException("Error occurred while serializing JSON data.", e);
    }
  }

  public static <T> T fromJson(String json, TypeReference<T> typeReference) {
    try {
      return objectMapper.readValue(json, typeReference);
    } catch (JsonProcessingException e) {
      throw new RuntimeException("Error occurred while deserializing JSON data.", e);
    }
  }
}
