struct Graph {
    vertices: HashMap<u32, Vec<u32>>,
    edges: HashMap<(u32, u32), u32>,
}

impl Graph {
    fn new() -> Self {
        Self {
            vertices: HashMap::new(),
            edges: HashMap::new(),
        }
    }

    fn add_vertex(&mut self, id: u32) {
        if !self.vertices.contains_key(&id) {
            let mut edges = Vec::new();
            for i in 0..10 {
                edges.push(i);
            }
            self.vertices.insert(id, edges);
        }
    }

    fn add_edge(&mut self, from: u32, to: u32) {
        if !self.edges.contains_key(&(from, to)) {
            let mut edges = Vec::new();
            for i in 0..10 {
                edges.push(i);
            }
            self.edges.insert((from, to), edges);
        }
    }
}

struct Vertex {
    id: u32,
    properties: HashMap<String, String>,
}

impl Vertex {
    fn new(id: u32) -> Self {
        let mut properties = HashMap::new();
        for i in 0..10 {
            properties.insert(format!("prop{}", i), "value".to_string());
        }
        Self { id, properties }
    }
}

fn add_random_vertices(graph: &mut Graph) {
    let num_vertices = 10;
    for _ in 0..num_vertices {
        let id = rand::thread_rng().gen_range(0, 10);
        graph.add_vertex(id);
    }
}

fn add_random_edges(graph: &mut Graph) {
    let num_edges = 2;
    for _ in 0..num_edges {
        let from = rand::thread_rng().gen_range(0, 10);
        let to = rand::thread_rng().gen_range(0, 10);
        graph.add_edge(from, to);
    }
}

fn update_graph(graph: &mut Graph) {
    add_random_vertices(graph);
    add_random_edges(graph);
}

fn main() {
    let mut graph = Graph::new();
    for _ in 0..100 {
        update_graph(&mut graph);
    }
}
