    BatchInsertOrLog(bool loggingEnabled = false, int logSizeLimit = 1000) : loggingEnabled(loggingEnabled), logSizeLimit(logSizeLimit), logEntryCount(0), logs(nullptr) {}

    ~BatchInsertOrLog() { delete[] logs; }

    void insert(std::string str) {
        std::lock_guard<std::mutex> lock(mtx);
        collection.push_front(str);
        if (loggingEnabled && logEntryCount < logSizeLimit) {
            LogEntry* newLog = new LogEntry{"insert", str, "", 0};
            logs[logEntryCount++] = *newLog;
