            if (it != collection.end()) {
                // Insert the second string after the first occurrence of the first string in the forward list
                it = it++;
                collection.insert_after(it, pair.second);
            } else {
                // Append the second string at the end of the forward list
                collection.push_front(pair.second);
            }
            if (loggingEnabled && logEntryCount < logSizeLimit) {
                LogEntry* newLog = new LogEntry{"insertOrLog", pair.first, pair.second, 0};
                logs[logEntryCount++] = *newLog;
