using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using System.Collections.Generic;

namespace RobustSQLService
{
    public class SQLService : IDisposable
    {
        private readonly string _connectionString;
        private readonly Dictionary<string, SqlCommand> _commandCache = new();
        private readonly List<SqlConnection> _connections = new();
        private readonly object _syncRoot = new();

        public SQLService(string connectionString)
        {
            _connectionString = connectionString;
        }

        public async Task<IEnumerable<T>> ExecuteQueryAsync<T>(string query, params SqlParameter[] parameters)
        {
            var results = new List<T>();

            using (var conn = await CreateConnectionAsync())
            {
                using (var cmd = conn.CreateCommand())
                {
                    AddParameters(cmd, parameters);
                    cmd.CommandText = query;

                    using (var reader = await cmd.ExecuteReaderAsync())
                    {
                        while (await reader.ReadAsync())
                        {
                            results.Add((T)reader[0]);
                        }
                    }
                }
            }

            return results;
        }

        public async Task ExecuteNonQueryAsync(string query, params SqlParameter[] parameters)
        {
            using (var conn = await CreateConnectionAsync())
            {
                using (var cmd = conn.CreateCommand())
                {
                    AddParameters(cmd, parameters);
                    cmd.CommandText = query;
                    await cmd.ExecuteNonQueryAsync();
                }
            }
        }

        public async Task<T> ExecuteScalarAsync<T>(string query, params SqlParameter[] parameters)
        {
            using (var conn = await CreateConnectionAsync())
            {
                using (var cmd = conn.CreateCommand())
                {
                    AddParameters(cmd, parameters);
                    cmd.CommandText = query;
                    var result = await cmd.ExecuteScalarAsync();
                    return (T)result;
                }
            }
        }

        public async Task<SqlTransaction> BeginTransactionAsync()
        {
            using (var conn = await CreateConnectionAsync())
            {
                return await conn.BeginTransactionAsync();
            }
        }

        public async Task CommitTransactionAsync(SqlTransaction transaction)
        {
            using (var conn = await CreateConnectionAsync())
            {
                await transaction.CommitAsync();
            }
        }

        public async Task RollbackTransactionAsync(SqlTransaction transaction)
        {
            using (var conn = await CreateConnectionAsync())
            {
                await transaction.RollbackAsync();
            }
        }

        private async Task<SqlConnection> CreateConnectionAsync()
        {
            var conn = new SqlConnection(_connectionString);
            await conn.OpenAsync();
            _connections.Add(conn);
            return conn;
        }

        private void AddParameters(SqlCommand cmd, SqlParameter[] parameters)
        {
            foreach (var param in parameters)
            {
                cmd.Parameters.Add(param);
            }
        }

        public void Dispose()
        {
            lock (_syncRoot)
            {
                foreach (var conn in _connections)
                {
                    conn?.Dispose();
                }
            }
        }
    }
}
```
