use std::env;
use std::fs;
use std::path::PathBuf;

pub fn create_directory(name: &str) -> Result<(), String> {
    // Check if the environment variable is already set. If so, use the existing value.
    let env_var = env::var("CUSTOM_DIRECTORY").map_err(|e| e.to_string())?;
    let custom_directory = PathBuf::from(env_var);
    if custom_directory.exists() {
        return Ok(());
    }

    // Create the directory and set the environment variable accordingly.
    fs::create_dir(custom_directory).map_err(|e| e.to_string())?;
    env::set_var("CUSTOM_DIRECTORY", &custom_directory);

    Ok(())
}
