using Microsoft.AspNetCore.Identity;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace AuthService
{
    public class AuthenticationService : IAuthenticationService
    {
        private readonly UserManager<ApplicationUser> _userManager;
        private readonly SignInManager<ApplicationUser> _signInManager;
        private readonly OAuthClient _oauthClient;
        private readonly LoggingService _loggingService;

        public AuthenticationService(UserManager<ApplicationUser> userManager, SignInManager<ApplicationUser> signInManager, OAuthClient oauthClient, LoggingService loggingService)
        {
            _userManager = userManager;
            _signInManager = signInManager;
            _oauthClient = oauthClient;
            _loggingService = loggingService;
        }

        public async Task<bool> ValidateCredentials(string username, string password)
        {
            var user = await _userManager.FindByNameAsync(username);
            if (user == null)
                return false;

            var result = await _signInManager.PasswordSignInAsync(user, password, isPersistent: true, lockoutOnFailure: true);

            if (!result.Succeeded)
                return false;

            return true;
        }

        public async Task<bool> ValidateMfaToken(string username, string mfaToken)
        {
            var user = await _userManager.FindByNameAsync(username);
            if (user == null)
                return false;

            var result = await _oauthClient.ValidateMfaTokenAsync(user, mfaToken);

            if (!result.Succeeded)
                return false;

            return true;
        }

        public async Task<string> GetAccessToken(string username, string password, string[] scopes = null)
        {
            var user = await _userManager.FindByNameAsync(username);
            if (user == null)
                throw new InvalidOperationException("User not found");

            var result = await _signInManager.PasswordSignInAsync(user, password, isPersistent: true, lockoutOnFailure: true);

            if (!result.Succeeded)
                throw new AuthenticationException("Invalid credentials");

            var accessToken = await _oauthClient.GetAccessTokenAsync(user, scopes);

            return accessToken;
        }
    }
}
