#define MIN_THREADS 2
#define MAX_THREADS 8
#define THREAD_CHECK_INTERVAL 100 // ms
#define DEBOUNCE_DELAY 1000 // ms
#define CACHE_SIZE 5000
#define DEFAULT_THRESHOLD 1000

// Structures
typedef struct {
    char* logFilePath;
    FILE* fileHandle;
} logFile_t;

typedef struct {
    int rnti;
    unsigned long msgCount;
} nasMsgCounts_t;

typedef struct {
    pthread_mutex_t mutex;
    nasMsgCounts_t counts[MAX_LOG_FILES];
} nasMsgCountCache_t;

typedef struct {
    int threadId;
    logFile_t* logFiles[MAX_LOG_FILES];
    pthread_mutex_t mutex;
} threadData_t;

// Global variables
sem_t semaphore;
pthread_barrier_t barrier;
nasMsgCountCache_t nasMsgCounts;
int threadCount = MIN_THREADS;
int logFileIndex[MAX_LOG_FILES];
logFile_t* logFiles[MAX_LOG_FILES];
pthread_t threads[MAX_THREADS];

// Function prototypes
void* parseNASLogs(void*);
void handleNASTraffic(char*, int, int, nasMsgCountCache_t*, threadData_t*);
void updateNasMsgCounts(nasMsgCountCache_t*, int, int, int);
int getNasMsgCount(nasMsgCountCache_t*, int, int);
void printNasMsgCounts();
void checkThreadCount();
void adjustThreadCount(pthread_barrier_t*);

// Function definitions

/**
 * @brief Initialize the NAS log processing library.
 * 
 */
int initProcessNASLogs() {
    // Create semaphore and barrier
    if (sem_init(&semaphore, 0, 1) < 0) {
        perror("Error creating semaphore");
        return -1;
    }
    pthread_barrier_init(&barrier, NULL, threadCount);

    // Initialize NAS message counts cache and thread data structures
    nasMsgCounts.mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        logFiles[i] = NULL;
        nasMsgCounts.counts[i].rnti = -1;
        nasMsgCounts.counts[i].msgCount = 0;
    }

    // Start parsing threads
    for (int i = 0; i < threadCount; i++) {
        pthread_create(&threads[i], NULL, parseNASLogs, NULL);
    }
    return 0;
}

/**
 * @brief Shut down the NAS log processing library.
 * 
 */
void shutdownProcessNASLogs() {
    // Join all parsing threads
    for (int i = 0; i < threadCount; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up semaphore and barrier
    pthread_barrier_destroy(&barrier);
    sem_destroy(&semaphore);
}

/**
 * @brief Parse and validate NAS messages in a log file.
 * 
 * @param threadData Pointer to thread data structure.
 */
void* parseNASLogs(void* threadData) {
    // Get thread data
    threadData_t* td = (threadData_t*) threadData;

    // Loop over log files for this thread
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        // Check if the log file is still valid and open
        if (!td->logFiles[i] || ferror(td->logFiles[i]->fileHandle)) {
            continue;
        }

        // Parse NAS messages in this log file
        while (1) {
            // Acquire semaphore to prevent race condition with other threads
            if (sem_wait(&semaphore) < 0) {
                perror("Error acquiring semaphore");
            }

            // Check if the log file is still valid and open
            if (!td->logFiles[i] || ferror(td->logFiles[i]->fileHandle)) {
                break;
            }

            // Parse NAS message header
            char* msgHeader = NULL;
            int rnti = 0;
            int msgType = 0;
            if (fscanf(td->logFiles[i]->fileHandle, "%*[^:]:%d", &rnti) == 1) {
                fscanf(td->logFiles[i]->fileHandle, "%d", &msgType);
                msgHeader = (char*) malloc(50 * sizeof(char)); // enough to hold the entire header
                sprintf(msgHeader, "RNTI:%d:MsgType:%d", rnti, msgType);
            } else {
                break;
            }

            // Release semaphore after header is parsed
            if (sem_post(&semaphore) < 0) {
                perror("Error releasing semaphore");
            }

            // Check for errors in parsing header
            if (!msgHeader || ferror(td->logFiles[i]->fileHandle)) {
                break;
            }

            // Validate NAS message header and update message counts cache
            int cacheIndex = getNasMsgCount(&nasMsgCounts, rnti, msgType);
            if (cacheIndex >= 0) {
                nasMsgCounts.counts[cacheIndex].msgCount++;
                free(msgHeader);
            } else {
                break;
            }
        }
    }

    // Adjust thread count and join this thread with main parsing thread
    adjustThreadCount(&barrier);
    pthread_join(pthread_self(), NULL);
    return 0;
}

/**
 * @brief Get the number of NAS messages of a specific type for a given RNTI.
 * 
 * @param nasMsgCounts Pointer to NAS message counts cache.
 * @param rnti The RNTI value.
 * @param msgType The NAS message type.
 * @return int The number of NAS messages of the specified type for the given RNTI, or -1 if error.
 */
int getNasMsgCount(nasMsgCounts_t* nasMsgCounts, int rnti, int msgType) {
    // Lock message counts cache
    pthread_mutex_lock(&nasMsgCounts->mutex);

    // Check if the RNTI is in the message counts cache
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        if (nasMsgCounts->counts[i].rnti == rnti) {
            int msgCount = nasMsgCounts->counts[i].msgCount;
            pthread_mutex_unlock(&nasMsgCounts->mutex);
            return msgCount;
        }
    }

    // RNTI is not in the message counts cache, add it
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        if (nasMsgCounts->counts[i].rnti == -1) {
            nasMsgCounts->counts[i].rnti = rnti;
            nasMsgCounts->counts[i].msgCount = 0;
            break;
        }
    }
    pthread_mutex_unlock(&nasMsgCounts->mutex);
    return -1;
}

/**
 * @brief Update the number of NAS messages of a specific type for a given RNTI.
 * 
 * @param nasMsgCounts Pointer to NAS message counts cache.
 * @param rnti The RNTI value.
 * @param msgType The NAS message type.
 * @return int The previous number of NAS messages of the specified type for the given RNTI, or -1 if error.
 */
int updateNasMsgCount(nasMsgCounts_t* nasMsgCounts, int rnti, int msgType) {
    // Lock message counts cache
    pthread_mutex_lock(&nasMsgCounts->mutex);

    // Check if the RNTI is in the message counts cache
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        if (nasMsgCounts->counts[i].rnti == rnti) {
            int msgCount = nasMsgCounts->counts[i].msgCount;
            pthread_mutex_unlock(&nasMsgCounts->mutex);
            return msgCount;
        }
    }

    // RNTI is not in the message counts cache, add it
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        if (nasMsgCounts->counts[i].rnti == -1) {
            nasMsgCounts->counts[i].rnti = rnti;
            nasMsgCounts->counts[i].msgCount = 0;
            break;
        }
    }
    pthread_mutex_unlock(&nasMsgCounts->mutex);
    return -1;
}

/**
 * @brief Print the current number of NAS messages for each RNTI.
 * 
 */
void printNasMsgCounts() {
    // Lock message counts cache
    pthread_mutex_lock(&nasMsgCounts->mutex);

    // Print message counts for all RNTIs
    printf("Current NAS message counts:\n");
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        if (nasMsgCounts->counts[i].rnti != -1) {
            printf("RNTI:%d:MsgType:%d:%d\n", nasMsgCounts->counts[i].rnti, nasMsgCounts->counts[i].msgCount);
        }
    }
    pthread_mutex_unlock(&nasMsgCounts->mutex);
}

/**
 * @brief Adjust the thread count based on the current number of NAS messages.
 * 
 * @param barrier Pointer to a barrier object.
 */
void adjustThreadCount(barrier_t* barrier) {
    // Get the current number of NAS messages
    int nasMsgCount = getNasMsgCount();

    // Adjust the thread count based on the current number of NAS messages
    if (nasMsgCount < 1000) {
        pthread_barrier_wait(barrier);
    } else {
        pthread_cancel(pthread_self());
    }
}
