### Implementation of the `barrier_t` structure and functions

The `barrier_t` structure is used to manage the barriers in the program. It contains a mutex, a condition variable, and a counter that indicates how many threads are currently waiting for the barrier. The `init`, `wait`, and `destroy` functions are used to initialize, wait on, and destroy the barrier respectively.
```c
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t condition;
    int counter;
} barrier_t;

void initBarrier(barrier_t* barrier) {
    barrier->counter = 0;
    pthread_mutex_init(&barrier->mutex, NULL);
    pthread_cond_init(&barrier->condition, NULL);
}

void waitBarrier(barrier_t* barrier) {
    pthread_mutex_lock(&barrier->mutex);
    while (barrier->counter != 0) {
        pthread_cond_wait(&barrier->condition, &barrier->mutex);
    }
    barrier->counter++;
    pthread_mutex_unlock(&barrier->mutex);
}

void destroyBarrier(barrier_t* barrier) {
    pthread_mutex_destroy(&barrier->mutex);
    pthread_cond_destroy(&barrier->condition);
}
```

### Implementation of the `nasMsgCounts` structure and functions

The `nasMsgCounts` structure is used to manage the NAS message counts in the program. It contains a mutex, an array of `int` to store the number of NAS messages for each RNTI, and a counter that indicates how many threads are currently waiting for the barrier. The `init`, `wait`, and `destroy` functions are used to initialize, wait on, and destroy the NAS message counts respectively.
```c
typedef struct {
    pthread_mutex_t mutex;
    int* nasMsgCounts;
    int counter;
} nasMsgCounts_t;

void initNasMsgCounts(nasMsgCounts_t* nasMsgCounts) {
    nasMsgCounts->counter = 0;
    nasMsgCounts->nasMsgCounts = (int*)malloc(sizeof(int) * MAX_LOG_FILES);
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        nasMsgCounts->nasMsgCounts[i] = -1;
    }
    pthread_mutex_init(&nasMsgCounts->mutex, NULL);
}

void waitNasMsgCounts(nasMsgCounts_t* nasMsgCounts) {
    pthread_mutex_lock(&nasMsgCounts->mutex);
    while (nasMsgCounts->counter != 0) {
        pthread_cond_wait(&nasMsgCounts->condition, &nasMsgCounts->mutex);
    }
    nasMsgCounts->counter++;
    pthread_mutex_unlock(&nasMsgCounts->mutex);
}

void destroyNasMsgCounts(nasMsgCounts_t* nasMsgCounts) {
    free(nasMsgCounts->nasMsgCounts);
    pthread_mutex_destroy(&nasMsgCounts->mutex);
}
```

