import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceMonitor {
    private static final String SERVICE_ID = "ServiceX";

    // Thread pool for concurrent lifecycle operations
    private static ExecutorService threadPool = Executors.newFixedThreadPool(10);

    // Logging mechanism for centralized logging
    private static Logger logger = new Logger();

    public void start() {
        // Start service and log metrics
        long startTime = System.currentTimeMillis();
        ServiceX.start();
        log("Service started at " + startTime);

        // Wait for service to be ready
        while (!ServiceX.isReady()) {
            try {
                TimeUnit.MILLISECONDS.sleep(100);
            } catch (InterruptedException e) {
                break;
            }
        }
        long endTime = System.currentTimeMillis();
        log("Service is ready at " + endTime);
    }

    public void stop() {
        // Stop service and log metrics
        long startTime = System.currentTimeMillis();
        ServiceX.stop();
        log("Service stopped at " + startTime);

        // Wait for service to be shutdown
        while (!ServiceX.isShutdown()) {
            try {
                TimeUnit.MILLISECONDS.sleep(100);
            } catch (InterruptedException e) {
                break;
            }
        }
        long endTime = System.currentTimeMillis();
        log("Service shutdown at " + endTime);
    }

    // Custom C function to format and append logs
    private void log(String message) {
        StringBuilder sb = new StringBuilder();
        sb.append(System.currentTimeMillis());
        sb.append(" ");
        sb.append(SERVICE_ID);
        sb.append(" ");
        sb.append(message);
        logger.log(sb.toString());
    }
}
```
