// API integration and resource management
use http::Request;
use semaphore::Semaphore;

fn main() {
    // Initialize the semaphore with a limit of 10 concurrent requests
    let mut semaphore = Semaphore::new(10);

    // Create an HTTP client for each API endpoint
    let api_clients = vec![
        ClientBuilder::new().build(),
        ClientBuilder::new().build(),
        ClientBuilder::new().build(),
    ];

    // Define the request headers and body for each API
    let requests = vec![
        Request::new("GET", "https://api1.example.com/resource"),
        Request::new("POST", "https://api2.example.com/resource", Some(Body::from("hello world"))),
        Request::new("PUT", "https://api3.example.com/resource", Some(Body::from("goodbye world"))),
    ];

    // Execute the requests concurrently and manage the semaphore
    let mut futures = Vec::new();
    for request in &requests {
        let client = api_clients[0].clone();
        let semaphore = semaphore.clone();
        futures.push(async move {
            // Acquire a permit from the semaphore before making the request
            let _permit = semaphore.acquire().await;
            client.execute(request).await.unwrap()
        });
    }

    // Join all the futures and collect the results
    let responses = join_all(futures).await;

    // Print the response bodies for each API call
    for (i, response) in responses.iter().enumerate() {
        println!("API {}: {}", i + 1, response.body());
    }
