<?php
class SecureSessionTokenManager {
    private $authenticationService;
    private $cache;
    private $config;

    public function __construct(AuthenticationService $authenticationService, Cache $cache, Config $config) {
        $this->authenticationService = $authenticationService;
        $this->cache = $cache;
        $this->config = $config;
    }

    public function generateToken($userId, $context) {
        // Generate a secure session token using a cryptographically strong algorithm
        $token = bin2hex(random_bytes(32));
        // Store the token in the cache for a short period of time to ensure it's used immediately
        $this->cache->set('token', $token, 60);
        return $token;
    }

    public function checkRateLimit($userId) {
        // Get the rate limit threshold from the config
        $rateLimitThreshold = $this->config->get('rate_limit');
        // Check if there have been too many requests in the past 10 seconds
        $recentRequests = $this->cache->get('recent_requests', [], 10);
        if (count($recentRequests) > $rateLimitThreshold) {
            return false;
        }
        // Add the current request to the list of recent requests
        $recentRequests[] = time();
        $this->cache->set('recent_requests', $recentRequests, 10);
        return true;
    }

    public function verifyToken($token) {
        // Verify the token using the authentication service
        if ($this->authenticationService->verifyToken($token)) {
            return true;
        }
        // If the token is invalid, remove it from the cache
        $this->cache->delete('token');
        return false;
    }
}
