            var encryptedData = File.ReadAllBytes(encryptedDataPath);

            // initialize a thread pool for concurrent batch processing
            using var semaphore = new SemaphoreSlim(MaxConcurrency, MaxConcurrency);
            using var batchQueue = new ConcurrentQueue<byte[]>();

            // split the data into batches and enqueue them for concurrent processing
            var remainingBatchSize = encryptedData.Length;
            while (remainingBatchSize > 0)
            {
                // calculate the size of the next batch
                var batchSize = Math.Min(remainingBatchSize, BatchSize);

                // enqueue the batch for processing
                batchQueue.Enqueue(encryptedData.Take(batchSize).ToArray());

