#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <curl/curl.h>
#include <openssl/ssl.h>

// Custom memory pool for efficient memory management
struct MemoryPool {
  struct MemoryBlock* first;
  struct MemoryBlock* last;
};

struct MemoryBlock {
  void* data;
  size_t size;
  struct MemoryBlock* next;
};

void initMemoryPool(struct MemoryPool* pool) {
  pool->first = NULL;
  pool->last = NULL;
}

void* allocateMemory(struct MemoryPool* pool, size_t size) {
  // Allocate memory from the custom memory pool if available
  if (pool->first != NULL && pool->last->size - pool->last->data >= size) {
    void* data = pool->last->data;
    pool->last->data += size;
    return data;
  } else {
    // Otherwise, allocate memory from the system heap
    return malloc(size);
  }
}

void freeMemory(struct MemoryPool* pool, void* data) {
  // Free memory back to the custom memory pool if possible
  struct MemoryBlock* block = (struct MemoryBlock*)data;
  if (pool->first != NULL && block->next == NULL && pool->last->size - pool->last->data >= size) {
    pool->last->data -= block->size;
    free(block);
  } else {
    // Otherwise, free memory back to the system heap
    free(data);
  }
}

