  int maxRetries = 5;
  int currentRetry = 0;
  do {
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      currentRetry++;
      if (currentRetry >= maxRetries) {
        printf("FetchAndProcessBundle: Failed to retrieve bundle from %s after %d retries\n", url, maxRetries);
        return -1;
      } else {
        // Exponential backoff with random jitter to avoid thundering herds
        int delay = (int)pow(2.0, currentRetry) + rand() % 500;
        printf("FetchAndProcessBundle: Retrying in %d seconds\n", delay / 1000);
        sleep(delay);
      }
