}

// Write memory callback for HTTP client library
size_t writeMemory(void* ptr, size_t size, size_t nmemb, void* userdata) {
  struct MemoryBlock** block = (struct MemoryBlock**)userdata;
  size_t realSize = size * nmemb;
  if (realSize == 0) {
    return 0;
  }
  struct MemoryBlock* newBlock = (struct MemoryBlock*)malloc(sizeof(struct MemoryBlock));
  if (newBlock == NULL) {
    return -1;
  }
  newBlock->data = ptr;
  newBlock->size = realSize;
  newBlock->next = *block;
  *block = newBlock;
  return realSize;
}

// Process items and free memory callback for processing items
int processItems(int itemCount, void (*processItem)(void*)) {
  // Allocate memory for the items
  void** items = (void**)malloc(sizeof(void*) * itemCount);
  if (items == NULL) {
    return -1;
  }

  // Parse the items and process each one
  int i = 0;
  while (i < itemCount) {
    void* item = items[i];
    processItem(item);
    freeMemory(&pool, item);
    i++;
  }

  // Clean up and return
  free(items);
  return 0;
}

// Process and free memory callback for processing and freeing items
void processAndFreeMemory(void* item) {
  // Process the item
  int result = processItem(item);
  if (result != 0) {
    printf("FetchAndProcessBundle: Failed to process item\n");
    return;
  }

  // Free the memory for the item
  freeMemory(&pool, item);
}']

