// File Storage System

#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <fstream>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>
#include <fcntl.h>

using namespace std;

class FileStorage {
public:
    // Constructor
    FileStorage(string filepath) {
        this->filepath = filepath;
    }

    // Destructor
    ~FileStorage() {
        close();
    }

    // Open a file for reading or writing
    bool open(string mode) {
        int flags = 0;
        if (mode == "r") {
            flags = O_RDONLY;
        } else if (mode == "w") {
            flags = O_WRONLY | O_CREAT | O_TRUNC;
        }
        fd = open(filepath.c_str(), flags, S_IRUSR | S_IWUSR);
        return fd != -1;
    }

    // Close the file
    void close() {
        if (fd > 0) {
            close(fd);
            fd = 0;
        }
    }

    // Read from the file
    size_t read(void *buffer, size_t length) {
        return pread(fd, buffer, length, 0);
    }

    // Write to the file
    size_t write(const void *buffer, size_t length) {
        return pwrite(fd, buffer, length, 0);
    }

private:
    int fd = 0;
    string filepath;
};

// FileMetadata class to store file metadata
class FileMetadata {
public:
    // Constructor
    FileMetadata(string filename) : filename(filename) {}

    // Destructor
    ~FileMetadata() {}

    // Get the file name
    string getFilename() {
        return filename;
    }

    // Set the file size
    void setSize(size_t size) {
        this->size = size;
    }

    // Get the file size
    size_t getSize() {
        return size;
    }

private:
    string filename;
    size_t size = 0;
};

// FileSystem class to manage files and their metadata
class FileSystem {
public:
    // Constructor
    FileSystem(string rootdir) : rootdir(rootdir) {}

    // Destructor
    ~FileSystem() {
        close();
    }

    // Open the file system
    bool open() {
        if (rootdir.empty()) {
            return false;
        }
        fd = open(rootdir.c_str(), O_RDONLY | O_DIRECTORY, S_IRUSR | S_IWUSR);
        return fd != -1;
    }

    // Close the file system
    void close() {
        if (fd > 0) {
            close(fd);
            fd = 0;
        }
    }

    // List files in the directory
    vector<string> listFiles() {
        vector<string> filenames;
        struct dirent *entry;
        DIR *dirp = opendir(rootdir.c_str());
        if (dirp) {
            while ((entry = readdir(dirp)) != NULL) {
                filenames.push_back(string(entry->d_name));
            }
            closedir(dirp);
        }
        return filenames;
    }

    // Get file metadata
    FileMetadata getFileMetadata(string filename) {
        FileMetadata metadata(filename);
        struct stat sb;
        string path = rootdir + "/" + filename;
        if (stat(path.c_str(), &sb) == 0) {
            metadata.setSize(sb.st_size);
        }
        return metadata;
    }

private:
    int fd = 0;
    string rootdir;
};

// FileSystem class to manage files and their metadata
class VersionedFileStorage : public FileStorage {
public:
    // Constructor
    VersionedFileStorage(string filepath) : FileStorage(filepath) {}

    // Destructor
    ~VersionedFileStorage() {}

    // Open the file for reading or writing
    bool open(string mode) {
        // Check if the file exists and create it if necessary
        struct stat sb;
        string path = filepath + ".1";
        int fd = -1;
        if (stat(path.c_str(), &sb) == 0) {
            // File already exists, open for read/write
            return FileStorage::open(mode);
        } else {
            // File does not exist, create it and open for writing
            fd = creat(path.c_str(), S_IRUSR | S_IWUSR);
            if (fd != -1) {
                close(fd);
            }
        }
        return FileStorage::open(mode);
    }

    // Write to the file
    size_t write(const void *buffer, size_t length) {
        // Get the current version number
        int version = getVersion();

        // Open the file for writing
        bool success = FileStorage::open("w");
        if (success) {
            // Write the data to the file
            size_t written = 0;
            while (written < length) {
                ssize_t n = FileStorage::write(buffer + written, length - written);
                if (n == -1) {
                    break;
                }
                written += n;
            }

            // Close the file
            FileStorage::close();

            // Create a new version of the file
            string path = filepath + "." + to_string(version + 1);
            fd = creat(path.c_str(), S_IRUSR | S_IWUSR);
            if (fd != -1) {
                close(fd);
            }
        }

        return written;
    }

private:
    int getVersion() {
        // Get the version number from the file path
        size_t pos = filepath.rfind(".", string::npos);
        if (pos != string::npos) {
            string versionStr = filepath.substr(pos + 1, string::npos);
            try {
                int version = stoi(versionStr);
                return version;
            } catch (const std::invalid_argument &e) {
                // Invalid argument, use default value of 0
                return 0;
            }
        } else {
            // No version number in the file path, use default value of 0
            return 0;
        }
    }
};']

