// Function to refresh specific dialog fields based on a given resource ID and URL
refreshFields(resourceId, url) {
    // Send a request to the parent window for updates
    parent.postMessage({ resourceId, url }, '*');

    // Define a callback function for handling responses from the parent window
    const handleResponse = (event) => {
        // Check if the response is from the correct origin and has the correct resource ID
        if (event.origin === parentOrigin && event.data.resourceId === resourceId) {
            // Update the dialog fields with the received data
            for (const field of this.fieldsToRefresh) {
                if (field in event.data) {
                    this[field] = event.data[field];
                }
            }
        }
    };

    // Add the callback function to the parent window's message listener
    parent.addEventListener('message', handleResponse);

    // Send a request to the server for the data corresponding to the given resource ID and URL
    this.$http.get(url).then((response) => {
        const data = response.data;

        // Update the dialog fields with the received data
        for (const field of this.fieldsToRefresh) {
            if (field in data) {
                this[field] = data[field];
            }
        }
    }).catch((error) => {
        // Handle error
    });
}
