const Aggregator = (function() {
  let apiClients = {}; // Map of API endpoints to client instances
  let aggregationAlgorithms = {}; // Map of aggregation algorithms to implementations

  function initApiClient(endpoint) {
    if (!apiClients[endpoint]) {
      apiClients[endpoint] = new ApiClient(endpoint);
    }
  }

  function getAggregatedValues(endpoints, params, algorithm) {
    let values = [];

    for (let endpoint of endpoints) {
      initApiClient(endpoint);

      // Make API call and retrieve response
      let response = apiClients[endpoint].getValues(params);

      // Aggregate values using selected algorithm
      values.push(...aggregationAlgorithms[algorithm](response));
    }

    return Promise.resolve(values);
  }

  function registerAggregationAlgorithm(name, implementation) {
    aggregationAlgorithms[name] = implementation;
  }

  function getApiClient(endpoint) {
    if (!apiClients[endpoint]) {
      throw new Error(`API endpoint not found: ${endpoint}`);
    }

    return apiClients[endpoint];
  }

  return {
    getAggregatedValues,
    registerAggregationAlgorithm,
    getApiClient,
  };
})();
```
