    NFAPI_CRC_INDICATION_PDU_T* crc_indications = generate_crc_indications(num_crc_indications);

    if (!crc_indications) {
        printf("Error: Failed to generate CRC indications. Number of CRC indications: %d\n", num_crc_indications);
        return;
    }

    // Check that each RNTI is unique and the CRCFLAG is set to 1
    for (int i = 0; i < num_crc_indications; i++) {
        if (i > 0 && crc_indications[i].RNTI == crc_indications[i - 1].RNTI) {
            printf("Error: Duplicate RNTIs in CRC indications. Number of CRC indications: %d\n", num_crc_indications);
            free(crc_indications);
            return;
        }
        if (crc_indications[i].CRCFLAG != 1) {
            printf("Error: CRCFLAG is not set to 1 for RNTI %d. Number of CRC indications: %d\n", crc_indications[i].RNTI, num_crc_indications);
            free(crc_indications);
            return;
        }
    }

    // Free the memory allocated for the list of CRC indication PDUs
