// Define the DynamicServiceProxy class
class DynamicServiceProxy {
private:
    // Vector of service endpoints
    vector<string> endpoints_;

    // Map of service instances to their last successful request time
    unordered_map<string, chrono::time_point<chrono::system_clock>> instanceMap_;

    // Mutex for protecting the instanceMap_
    mutex instanceMutex_;

    // Condition variable for notifying threads of new available service instances
    condition_variable availableInstanceCondVar_;

    // Maximum number of threads to be created by the thread pool
    int maxThreads_;

    // Thread pool for handling requests
    vector<thread> threadPool_;

    // Mutex for protecting the thread pool
    mutex threadMutex_;

    // Condition variable for notifying threads of new available service instances
    condition_variable availableThreadPoolCondVar_;

    // Vector of queued requests
    vector<string> requestQueue_;

    // Mutex for protecting the request queue
    mutex requestMutex_;

    // Condition variable for notifying threads of new queued requests
    condition_variable requestCondVar_;

public:
    // Constructor
    DynamicServiceProxy(vector<string> endpoints, int maxThreads) :
            endpoints_(endpoints), maxThreads_(maxThreads),
            instanceMap_(), instanceMutex_(), availableInstanceCondVar_(),
            threadPool_(), threadMutex_(), availableThreadPoolCondVar_(),
            requestQueue_(), requestMutex_(), requestCondVar_() {
        // Initialize the service endpoints
        for (const auto& endpoint : endpoints_) {
            instanceMap_.emplace(endpoint, chrono::system_clock::now());
        }
    }

    // Destructor
    ~DynamicServiceProxy() = default;

    // Adds a new service endpoint to the list of available instances
    void addEndpoint(const string& endpoint) {
        lock_guard<mutex> instanceLock(instanceMutex_);
        instanceMap_.emplace(endpoint, chrono::system_clock::now());
        availableInstanceCondVar_.notify_all();
    }

    // Removes a service endpoint from the list of available instances
    void removeEndpoint(const string& endpoint) {
        lock_guard<mutex> instanceLock(instanceMutex_);
        instanceMap_.erase(endpoint);
        availableInstanceCondVar_.notify_all();
    }

    // Sends a request to the specified service endpoint and returns the response
    string sendRequest(const string& endpoint, const string& request) {
        lock_guard<mutex> instanceLock(instanceMutex_);
        if (!instanceMap_.count(endpoint)) {
