int num_providers = 0;
dns_provider **providers = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to load the DNS providers from environment variables
void load_dns_providers() {
  num_providers = getenv("NUM_PROVIDERS") ? atoi(getenv("NUM_PROVIDERS")) : 0;
  if (num_providers > 0) {
    providers = malloc(sizeof(dns_provider *) * num_providers);
    for (int i = 0; i < num_providers; ++i) {
      char name[256];
      snprintf(name, sizeof(name), "DNS_PROVIDER_%d", i + 1);
      providers[i] = malloc(sizeof(dns_provider));
      providers[i]->name = getenv(name) ? strdup(getenv(name)) : NULL;
    }
  }
}

// Function to initialize the DNS cache
void init_cache() {
  pthread_mutex_lock(&cache_lock);
  // Initialize the DNS cache
  int num_entries = getenv("NUM_ENTRIES") ? atoi(getenv("NUM_ENTRIES")) : 0;
  if (num_entries > 0) {
    dns_cache **cache = malloc(sizeof(dns_cache *) * num_entries);
    for (int i = 0; i < num_entries; ++i) {
      cache[i] = malloc(sizeof(dns_cache));
      cache[i]->domain = NULL;
      cache[i]->ip = NULL;
      cache[i]->expiration = 0;
    }
    // Set the DNS cache
    dns_cache *cache = malloc(sizeof(dns_cache) * num_entries);
    for (int i = 0; i < num_entries; ++i) {
      cache[i] = malloc(sizeof(dns_cache));
      cache[i]->domain = NULL;
      cache[i]->ip = NULL;
      cache[i]->expiration = 0;
    }
    pthread_mutex_unlock(&cache_lock);
  }
}

// Function to query the DNS providers asynchronously
void *query_dns(void *args) {
  dns_query *query = (dns_query *) args;
  SSL *ssl = NULL;
  char *response = NULL;
  for (int i = 0; i < num_providers; ++i) {
    // Create a new SSL context
    ssl = SSL_new(SSL_CTX_new(TLSv1_client_method()));
    // Set the SSL hostname
    SSL_set_hostname(ssl, providers[i]->url);
    // Connect to the DNS provider
    if (SSL_connect(ssl) != 1) {
      printf("Failed to connect to DNS provider: %s\n", providers[i]->name);
      continue;
    }
    // Set the SSL timeout
    SSL_set_fd(ssl, query->id);
    SSL_set_read_timeout(ssl, 5000);
    SSL_set_write_timeout(ssl, 5000);
    // Send the DNS query
    if (SSL_write(ssl, "GET /dns-query?q=", strlen("GET /dns-query?q=")) != 1) {
      printf("Failed to send DNS query: %s\n", providers[i]->name);
      SSL_free(ssl);
      continue;
    }
    // Receive the DNS response
    int len = SSL_read(ssl, &response, sizeof(response));
    if (len <= 0) {
      printf("Failed to receive DNS response: %s\n", providers[i]->name);
      SSL_free(ssl);
      continue;
    }
    // Process the DNS response
    dns_cache *cache = malloc(sizeof(dns_cache));
    cache->domain = query->domain;
    cache->ip = strdup(response);
    cache->expiration = time(NULL) + 3600; // Expire after one hour
    pthread_mutex_lock(&cache_lock);
    dns_cache *head = cache;
    for (int i = 0; i < num_entries; ++i) {
      if (strcmp(head->domain, cache->domain) == 0 && strcmp(head->ip, cache->ip) == 0) {
        break;
      }
      head = head->next;
    }
    // Insert the DNS response into the cache
    if (head != NULL) {
      head->next = cache;
      cache->prev = head;
    } else {
      cache->next = NULL;
      cache->prev = NULL;
    }
    pthread_mutex_unlock(&cache_lock);
    SSL_free(ssl);
  }
}

// Function to query the DNS providers synchronously
char *query_dns_sync(char *domain) {
  dns_query *query = malloc(sizeof(dns_query));
  query->domain = domain;
  query->id = -1;
  query->ssl = NULL;
  query->response = NULL;
  SSL_new(SSL_CTX_new(TLSv1_client_method()));
  SSL_set_hostname(query->ssl, providers[i]->url);
  SSL_connect(query->ssl);
  SSL_write(query->ssl, "GET /dns-query?q=", strlen("GET /dns-query?q="));
  int len = SSL_read(query->ssl, &response, sizeof(response));
  if (len <= 0) {
    printf("Failed to receive DNS response: %s\n", providers[i]->name);
    SSL_free(query->ssl);
    return NULL;
  }
  dns_cache *cache = malloc(sizeof(dns_cache));
  cache->domain = query->domain;
  cache->ip = strdup(response);
  cache->expiration = time(NULL) + 3600; // Expire after one hour
  pthread_mutex_lock(&cache_lock);
  dns_cache *head = cache;
  for (int i = 0; i < num_entries; ++i) {
    if (strcmp(head->domain, cache->domain) == 0 && strcmp(head->ip, cache->ip) == 0) {
      break;
    }
    head = head->next;
  }
  // Insert the DNS response into the cache
  if (head != NULL) {
    head->next = cache;
    cache->prev = head;
  } else {
    cache->next = NULL;
    cache->prev = NULL;
  }
  pthread_mutex_unlock(&cache_lock);
  SSL_free(query->ssl);
}

// Function to retrieve the IP address from a domain name
char *get_ip_address(char *domain) {
  dns_cache *head = NULL;
  pthread_mutex_lock(&cache_lock);
  for (int i = 0; i < num_entries; ++i) {
    if (strcmp(head->domain, domain) == 0) {
      break;
    }
    head = head->next;
  }
  pthread_mutex_unlock(&cache_lock);
  if (head != NULL) {
    return strdup(head->ip);
  } else {
    // Query the DNS providers asynchronously
    query_dns((void *) domain);
    // Wait for the DNS response to be received
    pthread_join(query_dns, (void **) &response);
    if (response != NULL) {
      return strdup(response);
    } else {
      // Query the DNS providers synchronously
      char *ip = query_dns_sync(domain);
      if (ip != NULL) {
        return ip;
      } else {
        printf("Failed to resolve IP address for domain: %s\n", domain);
        return NULL;
      }
    }
  }
}

int main() {
  char *domain = "example.com";
  char *ip = get_ip_address(domain);
  if (ip != NULL) {
    printf("IP address for domain %s is: %s\n", domain, ip);
  } else {
    printf("Failed to resolve IP address for domain: %s\n", domain);
  }
  return 0;
}']

