from typing import List

class DataIngestionPipeline:
    def __init__(self):
        self.data_sources = []
        self.downstream_services = []
        self.error_handler = None
        self.monitoring_system = None
        self.anomaly_detection_model = None

    def add_data_source(self, data_source: str):
        self.data_sources.append(data_source)

    def remove_data_source(self, data_source: str):
        if data_source in self.data_sources:
            self.data_sources.remove(data_source)

    def add_downstream_service(self, downstream_service: str):
        self.downstream_services.append(downstream_service)

    def remove_downstream_service(self, downstream_service: str):
        if downstream_service in self.downstream_services:
            self.downstream_services.remove(downstream_service)

    def set_error_handler(self, error_handler: callable):
        self.error_handler = error_handler

    def set_monitoring_system(self, monitoring_system: callable):
        self.monitoring_system = monitoring_system

    def set_anomaly_detection_model(self, anomaly_detection_model: callable):
        self.anomaly_detection_model = anomaly_detection_model

    def process_data(self):
        for data_source in self.data_sources:
            try:
                response = requests.get(data_source)
                if response.status_code == 200:
                    data = json.loads(response.text)
                    for downstream_service in self.downstream_services:
                        requests.post(downstream_service, data=data)
            except Exception as e:
                if self.error_handler:
                    self.error_handler(e)

    def monitor(self):
        for downstream_service in self.downstream_services:
            try:
                response = requests.get(downstream_service)
                if response.status_code == 200:
                    data = json.loads(response.text)
                    self.monitoring_system(data)
            except Exception as e:
                if self.error_handler:
                    self.error_handler(e)

    def detect_anomalies(self):
        for downstream_service in self.downstream_services:
            try:
                response = requests.get(downstream_service)
                if response.status_code == 200:
                    data = json.loads(response.text)
                    anomaly_score = self.anomaly_detection_model(data)
                    if anomaly_score > 0.5:
                        print(f"Anomaly detected in {downstream_service}: {anomaly_score}")
            except Exception as e:
                if self.error_handler:
                    self.error_handler(e)
