```java
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class StateService {
    private static final Logger logger = Logger.getLogger(StateService.class.getName());

    // Map to store the state objects by their file paths
    private ConcurrentHashMap<String, Object> stateMap = new ConcurrentHashMap<>();

    // Configuration parameters for caching and LRU
    private int cacheSize;
    private long maxFileAge;

    public StateService(int cacheSize, long maxFileAge) {
        this.cacheSize = cacheSize;
        this.maxFileAge = maxFileAge;
    }

    /**
     * Loads the state object from the given file path and adds it to the map.
     * If the file does not exist or is empty, returns null.
     */
    public Object loadState(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object state = ois.readObject();
            if (state == null) {
                logger.info("Could not read state from " + filePath);
                return null;
            }
            stateMap.put(filePath, state);
            return state;
        } catch (Exception e) {
            logger.severe("Error reading state from " + filePath + ": " + e.getMessage());
            return null;
        }
    }

    /**
     * Returns the state object for the given file path, if it exists.
     */
    public Object getState(String filePath) {
        return stateMap.get(filePath);
    }

    /**
     * Removes the state object for the given file path from the map.
     */
    public void removeState(String filePath) {
        stateMap.remove(filePath);
    }

    /**
     * Updates the cache size and max file age parameters.
     */
    public void updateConfiguration(int cacheSize, long maxFileAge) {
        this.cacheSize = cacheSize;
        this.maxFileAge = maxFileAge;
    }

    /**
     * Returns the current cache size and max file age parameters.
     */
    public int[] getConfiguration() {
        return new int[]{this.cacheSize, this.maxFileAge};
    }
}
```
