// Modular, extensible C++ library for batch job orchestration in a hybrid cloud environment
#include <iostream>
#include <vector>
#include <unordered_map>
#include <memory>

class BatchJobOrchestrator {
public:
    // Constructor
    BatchJobOrchestrator();

    // Destructor
    ~BatchJobOrchestrator();

    // Initialize the orchestrator with external services and platforms
    void init(const std::vector<std::string>& service_urls, const std::unordered_map<std::string, int>& queue_sizes);

    // Submit a batch job to the orchestrator
    bool submitJob(const std::string& job_name, const std::string& job_data);

    // Retrieve the next available job from the queue
    std::shared_ptr<BatchJob> getNextJob();

    // Update the status of a completed job
    void updateJobStatus(const std::string& job_name, const BatchJobStatus& status);

private:
    // Map of job names to job objects
    std::unordered_map<std::string, std::shared_ptr<BatchJob>> jobs_;

    // Vector of available job queues
    std::vector<std::queue<std::shared_ptr<BatchJob>>> job_queues_;

    // Lock for synchronizing access to the job queues
    std::mutex job_lock_;
};

// Batch job status enum
enum class BatchJobStatus {
    CREATED,
    QUEUED,
    RUNNING,
    COMPLETED,
    FAILED
};

// Batch job class
class BatchJob {
public:
    // Constructor
    BatchJob(const std::string& name, const std::string& data);

    // Getter for the job name
    const std::string& getName() const;

    // Setter for the job status
    void setStatus(const BatchJobStatus& status);

    // Getter for the job status
    const BatchJobStatus& getStatus() const;

private:
    // Job name
    std::string name_;

    // Job data
    std::string data_;

    // Job status
    BatchJobStatus status_;
};
```

