func (m *LogManager) WriteLogEntry(ctx context.Context, entry *LogEntry) error {
	sinks := m.GetSinks()
	for _, sink := range sinks {
		if err := sink.WriteLogEntry(ctx, entry); err != nil {
			return err
		}
	}
	return nil
}

func (m *LogManager) RegisterSink(sink LogSink) error {
	// Implement me!
	return nil
}

func main() {
	ctx := context.Background()
	entry := &LogEntry{
		ID:        uuid.NewString(),
		Timestamp: time.Now(),
		Level:     "INFO",
		Message:   "Test log entry",
	}
	if err := LogManager.WriteLogEntry(ctx, entry); err != nil {
		fmt.Println("Error writing log entry:", err)
	}
}
```
