    data = request.get_json()
    employee = Employee(name=data['name'], city=data['city'], address=data['address'], department=data['department'], manager_id=data['manager_id'])
    session.add(employee)
    session.commit()
    return jsonify({'status': 'success', 'message': f'Employee {employee.name} created successfully.'})

@app.route('/employees/<int:id>', methods=['GET'])
def get_employee(id):
    # Get employee by ID
    employee = session.query(Employee).get(id)
    if employee is None:
        return jsonify({'status': 'error', 'message': f'Employee with ID {id} not found.'})
    return jsonify(employee)

@app.route('/employees/<int:id>', methods=['PUT'])
def update_employee(id):
    # Update employee by ID and commit to database
    data = request.get_json()
    employee = session.query(Employee).get(id)
    if employee is None:
        return jsonify({'status': 'error', 'message': f'Employee with ID {id} not found.'})
    for key, value in data.items():
        setattr(employee, key, value)
    session.commit()
    return jsonify({'status': 'success', 'message': f'Employee {employee.name} updated successfully.'})

@app.route('/employees/<int:id>', methods=['DELETE'])
def delete_employee(id):
    # Delete employee by ID and commit to database
    employee = session.query(Employee).get(id)
    if employee is None:
        return jsonify({'status': 'error', 'message': f'Employee with ID {id} not found.'})
    session.delete(employee)
    session.commit()
    return jsonify({'status': 'success', 'message': f'Employee {employee.name} deleted successfully.'})

# Define caching strategies for frequently accessed data
