```rust
#[derive(Debug)]
pub struct CryptoService {
    pub clients: Vec<CryptoServiceClient>,
}

impl CryptoService {
    pub fn new() -> Self {
        Self {
            clients: Vec::new(),
        }
    }

    pub fn add_client(&mut self, config: CryptoServiceConfig) {
        let client = CryptoServiceClient::new(config);
        self.clients.push(client);
    }

    pub fn get_random_number(&self) -> u64 {
        if self.clients.len() == 0 {
            return MersenneTwister::new().random_number();
        }

        let mut random_numbers = Vec::new();
        for client in &self.clients {
            let random_number = client.get_random_number();
            random_numbers.push(random_number);
        }

        // compute the average of the random numbers
        let sum: u64 = random_numbers.iter().sum();
        let avg: f64 = (sum as f64) / (random_numbers.len() as f64);
        let rounded_avg: u64 = avg.round() as u64;
        return rounded_avg;
    }
}
