        // Check if the clinic ID exists in the resources array
        if (isset($this->resources[$clinicId])) {
            // Update the status and last modified IP address
            $this->resources[$clinicId]['status'] = $status;
            $this->resources[$clinicId]['lastModifiedIp'] = $lastModifiedIp;
            $this->resources[$clinicId]['lastModifiedDate'] = $lastModifiedDate;
