        if (!json) {
            sleep(delay / 1000);
            retries--;
            continue;
        }

        // Parse JSON data and extract "data" field
        json_object_object_get_ex(json, "data", &data);
        if (!data) {
            json_object_put(json);
            sleep(delay / 1000);
            retries--;
            continue;
        }

        // Populate NFAPI_CRC_INDICATION_PDU_T structure from JSON data
        for (int i = 0; i < *size; i++) {
            (*arr)[i].data = strdup(json_object_get_string(data));
            (*arr)[i].crci = json_object_get_int(data);
        }

        // Free JSON object and return
        json_object_put(json);
        return;
    }

    // If we reach this point, it means all retries have failed, so log an error and exit
    fprintf(stderr, "Error: unable to retrieve data from external source\n");
    exit(-1);
