    pthread_mutex_t mutex;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZED;
    int ready = 0;
    int done = 0;
    int i = 0;

    // Initialize mutex and condition variable for synchronization
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Launch threads to populate the NFAPI_CRC_INDICATION_PDU_T structures in parallel
    while (i < *size) {
        // Create a new thread for population and add it to the array of active threads
        pthread_create(&threads[i], NULL, &populate_thread, arr);
        i++;
    }

    // Wait for all threads to finish before continuing
    while (ready < *size) {
        pthread_mutex_lock(&mutex);
        if (ready == done) {
            pthread_cond_wait(&cond, &mutex);
        } else {
            pthread_mutex_unlock(&mutex);
        }
    }

    // Clean up mutex and condition variable
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
}

