    int temperature;
    int humidity;
    int pressure;
    string location;
};

// Define a class to handle the processing of sensor readings
class SensorReader {
public:
    // Constructor
    SensorReader(const vector<string>& sensorNames) : sensors_(sensorNames.size()) {
        for (int i = 0; i < sensors_.size(); ++i) {
            sensors_[i] = make_shared<Sensor>(sensorNames[i]);
        }
    }

    // Process a new sensor reading
    void processReading(const SensorReading& reading) {
        for (int i = 0; i < sensors_.size(); ++i) {
            if (reading.location == sensors_[i]->getName()) {
                sensors_[i]->addReading(reading);
            }
        }
    }

    // Get the most recent sensor readings
    vector<SensorReading> getMostRecentReadings() {
        vector<SensorReading> readings;
        for (int i = 0; i < sensors_.size(); ++i) {
            SensorReading reading = sensors_[i]->getMostRecentReading();
            readings.push_back(reading);
        }
        return readings;
    }

private:
    // Define a class to represent a sensor
    class Sensor {
    public:
        // Constructor
        Sensor(const string& name) : name_(name), readings_() {}

        // Add a new sensor reading
        void addReading(const SensorReading& reading) {
            readings_.push_back(reading);
        }

        // Get the most recent sensor reading
        SensorReading getMostRecentReading() {
            if (readings_.size() == 0) {
                return SensorReading{};
            } else {
                return readings_[readings_.size() - 1];
            }
        }

    private:
        // The name of the sensor
        string name_;

        // The most recent sensor readings
        vector<SensorReading> readings_;
    };

    // The sensors
    vector<shared_ptr<Sensor>> sensors_;
};

int main() {
    // Initialize the sensor reader
    SensorReader reader({"sensor1", "sensor2", "sensor3"});

    // Process a new sensor reading
    SensorReading reading = {45, 50, 98765, "sensor1"};
    reader.processReading(reading);

    // Get the most recent sensor readings
    vector<SensorReading> readings = reader.getMostRecentReadings();

    // Print the most recent sensor readings
    for (int i = 0; i < readings.size(); ++i) {
        cout << "Sensor " << readings[i].location << " reading: " << endl;
        cout << "\tTemperature: " << readings[i].temperature << endl;
        cout << "\tHumidity: " << readings[i].humidity << endl;
        cout << "\tPressure: " << readings[i].pressure << endl;
    }
}
```
