// Define functions for NFA API CRC management
void generateNfaApiCrcList(char* url) {
    // Acquire mutex and semaphore
    pthread_mutex_lock(&nfaApiCrcListMutex);
    sem_wait(&nfaApiCrcListSemaphore);

    // Allocate memory for new NFA API CRC entry if necessary
    if (nfaApiCrcListSize == 0) {
        nfaApiCrcList = malloc(sizeof(NFAAPICrcIndicationPduT) * INITIAL_NFA_API_CRC_LIST_SIZE);
        if (!nfaApiCrcList) {
            fprintf(stderr, "ERROR: Memory allocation failed in generateNfaApiCrcList()");
            exit(1);
        }
    } else if (nfaApiCrcListSize == MAX_NFA_API_CRC_LIST_SIZE) {
        nfaApiCrcList = realloc(nfaApiCrcList, sizeof(NFAAPICrcIndicationPduT) * (nfaApiCrcListSize + NFA_API_CRC_INCREMENT_SIZE));
        if (!nfaApiCrcList) {
            fprintf(stderr, "ERROR: Memory allocation failed in generateNfaApiCrcList()");
            exit(1);
        }
    }

    // Insert new NFA API CRC entry into the list
    nfaApiCrcList[nfaApiCrcListSize].crc = crc32(url, strlen(url));
    nfaApiCrcList[nfaApiCrcListSize].url = url;

    // Update list size and release mutex and semaphore
    nfaApiCrcListSize++;
    pthread_mutex_unlock(&nfaApiCrcListMutex);
    sem_post(&nfaApiCrcListSemaphore);
}

// Define functions for asynchronous database services
void databaseConnection(DatabaseConnectionT* connection) {
    // Acquire mutex and semaphore
    pthread_mutex_lock(&databaseConnectionsMutex);
    sem_wait(&databaseConnectionsSemaphore);

    // Allocate memory for new database connection if necessary
    if (databaseConnectionsSize == 0) {
        databaseConnections = malloc(sizeof(DatabaseConnectionT) * INITIAL_DATABASE_CONNECTIONS_SIZE);
        if (!databaseConnections) {
            fprintf(stderr, "ERROR: Memory allocation failed in databaseConnection()");
            exit(1);
        }
    } else if (databaseConnectionsSize == MAX_DATABASE_CONNECTIONS_SIZE) {
        databaseConnections = realloc(databaseConnections, sizeof(DatabaseConnectionT) * (databaseConnectionsSize + DATABASE_CONNECTIONS_INCREMENT_SIZE));
        if (!databaseConnections) {
            fprintf(stderr, "ERROR: Memory allocation failed in databaseConnection()");
            exit(1);
        }
    }

    // Insert new database connection into the list
    databaseConnections[databaseConnectionsSize].connectionId = ++nextConnectionId;
    databaseConnections[databaseConnectionsSize].hostname = connection->hostname;
    databaseConnections[databaseConnectionsSize].port = connection->port;
    databaseConnections[databaseConnectionsSize].username = connection->username;
    databaseConnections[databaseConnectionsSize].password = connection->password;

    // Update list size and release mutex and semaphore
    databaseConnectionsSize++;
    pthread_mutex_unlock(&databaseConnectionsMutex);
    sem_post(&databaseConnectionsSemaphore);
}

// Define functions for encryption and security
void setEncryptionKey(char* key) {
    // Acquire mutex and semaphore
    pthread_mutex_lock(&encryptionKeyMutex);
    sem_wait(&encryptionKeySemaphore);

    // Allocate memory for new encryption key if necessary
    size_t keySize = strlen(key);
    if (encryptionKeySize < keySize) {
        encryptionKey = realloc(encryptionKey, sizeof(char) * keySize);
        if (!encryptionKey) {
            fprintf(stderr, "ERROR: Memory allocation failed in setEncryptionKey()");
            exit(1);
        }
    }

    // Set new encryption key and update size
    memcpy(encryptionKey, key, keySize);
    encryptionKeySize = keySize;

    // Update modified flag and release mutex and semaphore
    encryptionKeyModified = true;
    pthread_mutex_unlock(&encryptionKeyMutex);
    sem_post(&encryptionKeySemaphore);
}

