void generateNfaApiCrcList(NFAPI_CRC_INDICATION_PDU_T** nfaCrcList, size_t* capacity) {
    // dynamically populate an array of NFAPI_CRC_INDICATION_PDU_T structures

    // 1. check if the current capacity is exceeded
    if (*capacity == 0) {
        *capacity = 8; // initial capacity
        *nfaCrcList = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*capacity));
        assert(*nfaCrcList != NULL);
