#include <stdbool.h>
#include <string.h>
#include <pthread.h>
#include "nfa_api_crc_indication_pdu.h"

// Struct to hold the state of the function
struct NfaApiCrcList {
  size_t count; // Number of elements in the list
  size_t capacity; // Capacity of the list
  NFAPI_CRC_INDICATION_PDU_T* elements; // Pointer to the list of elements
  pthread_mutex_t mutex; // Mutex for thread safety
};

// Function to generate a list of NFA API CRC indication PDUs dynamically
NfaApiCrcList* generateNfaApiCrcList(size_t size) {
  // Allocate memory for the list struct
  NfaApiCrcList* list = (NfaApiCrcList*)malloc(sizeof(NfaApiCrcList));
  if (!list) {
    return NULL;
  }

  // Initialize the mutex and count to 0
  pthread_mutex_init(&list->mutex, NULL);
  list->count = 0;
  list->capacity = size;

  // Allocate memory for the elements array
  NFAPI_CRC_INDICATION_PDU_T* elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
  if (!elements) {
    free(list);
    return NULL;
  }

  // Initialize the elements array with random CRCFLAG values
  for (size_t i = 0; i < size; i++) {
    elements[i].RX_UE_INFORMATION_TAG = (rand() % 2 == 0) ? 1 : 2;
    elements[i].RNTI = rand() % 65536;
    elements[i].CRC_INDICATION_REL8_TAG = rand() % 65536;
    elements[i].CRCFLAG = (rand() % 2 == 0) ? true : false;
  }

  // Store the elements array in the list struct and return it
  list->elements = elements;
  return list;
}

// Function to dynamically resize the list of NFA API CRC indication PDUs
void nfaApiCrcListResize(NfaApiCrcList* list, size_t newSize) {
  // If the requested size is less than or equal to the current capacity, return early
  if (newSize <= list->capacity) {
    return;
  }

  // Otherwise, acquire the mutex and resize the elements array
  pthread_mutex_lock(&list->mutex);
  NFAPI_CRC_INDICATION_PDU_T* newElements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize);
  if (!newElements) {
    pthread_mutex_unlock(&list->mutex);
    return;
  }

  list->capacity = newSize;
  list->elements = newElements;
  pthread_mutex_unlock(&list->mutex);
}

// Function to insert an element into the list of NFA API CRC indication PDUs
void nfaApiCrcListInsert(NfaApiCrcList* list, const NFAPI_CRC_INDICATION_PDU_T* element) {
  // If the list is full, resize it before inserting the new element
  if (list->count == list->capacity) {
    nfaApiCrcListResize(list, list->capacity * 2);
  }

  // Acquire the mutex and insert the element into the list
  pthread_mutex_lock(&list->mutex);
  memcpy(&list->elements[list->count], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->count++;
  pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve an element from the list of NFA API CRC indication PDUs
void nfaApiCrcListGet(NfaApiCrcList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T* output) {
  // If the requested index is out of bounds, return early
  if (index >= list->count) {
    return;
  }

  // Acquire the mutex and retrieve the element from the list
  pthread_mutex_lock(&list->mutex);
  memcpy(output, &list->elements[index], sizeof(NFAPI_CRC_INDICATION_PDU_T));
  pthread_mutex_unlock(&list->mutex);
}

// Function to remove an element from the list of NFA API CRC indication PDUs
void nfaApiCrcListRemove(NfaApiCrcList* list, size_t index) {
  // If the requested index is out of bounds, return early
  if (index >= list->count) {
    return;
  }

  // Acquire the mutex and remove the element from the list
  pthread_mutex_lock(&list->mutex);
  memmove(&list->elements[index], &list->elements[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - index - 1));
  list->count--;
  pthread_mutex_unlock(&list->mutex);
}

// Function to release the resources of a list of NFA API CRC indication PDUs
void nfaApiCrcListDestroy(NfaApiCrcList* list) {
  // If the list is null, return early
  if (!list) {
    return;
  }

  // Acquire the mutex and release the resources of the list
  pthread_mutex_lock(&list->mutex);
  free(list->elements);
  free(list);
  pthread_mutex_unlock(&list->mutex);
}

// Function to update a list of NFA API CRC indication PDUs with a new element
void nfaApiCrcListUpdate(NfaApiCrcList* list, const NFAPI_CRC_INDICATION_PDU_T* element) {
  // Acquire the mutex and update the list with the new element
  pthread_mutex_lock(&list->mutex);
  nfaApiCrcListRemove(list, 0);
  nfaApiCrcListInsert(list, element);
  pthread_mutex_unlock(&list->mutex);
}
```

This implementation provides a thread-safe way to manipulate the list of NFA API CRC indication PDUs. The `nfaApiCrcListCreate` function creates a new list with an initial capacity of 10 and returns it to the caller. The `nfaApiCrcListResize` function dynamically resizes the elements array in the list if it becomes full. The `nfaApiCrcListInsert` function inserts a new element into the list at the end. The `nfaApiCrcListGet` function retrieves an element from the list at a specific index. The `nfaApiCrcListRemove` function removes an element from the list at a specific index. The `nfaApiCrcListUpdate` function updates the list with a new element by removing the first element and inserting the new one at the end. Finally, the `nfaApiCrcListDestroy` function releases the resources of the list and sets it to null.']

