    pthread_mutex_lock(&buffer->mutex);
    buffer->list.head = (struct LogEntry*) realloc(buffer->list.head, sizeof(struct LogEntry));
    buffer->list.tail = (struct LogEntry*) realloc(buffer->list.tail, sizeof(struct LogEntry));
    memcpy(&buffer->list.head->message, &entry->message, sizeof(char*));
    buffer->list.head->timestamp = entry->timestamp;
    buffer->list.head++;
}

// Define a function to flush the log buffer to the configured destination
void flushLogBuffer(struct LogBuffer* buffer) {
