                break;
            case DATABASE:
                // Implement database write logic here
                break;
        }
        list->head = (struct LogEntry*) realloc(list->head, sizeof(struct LogEntry));
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Define a function to update the logging level of the log buffer
void setLogLevel(struct LogBuffer* buffer, enum LogLevel level) {
