    sprintf(message, "Logging Error: %d", errnum);
    log_message(message);
    free(message);
}

bool is_valid_rx_ue_information(struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->UE_information.number_of_ues == 0) {
        return false;
    }
    for (int i = 0; i < pdu->UE_information.number_of_ues; i++) {
        if (strcmp(pdu->UE_information.ue_list[i].RNTI, "") == 0) {
            return false;
        }
    }
    return true;
}

void handle_log_request(struct log_queue *entry, struct log_cache *cache) {
    char *message = malloc(strlen(entry->entry->message) + CACHE_SIZE);
    sprintf(message, "%s", entry->entry->message);
    pthread_mutex_lock(&log_lock);
    while (cache->is_full) {
        sem_wait(&semaphore);
    }
    cache->head++;
    if (cache->head == CACHE_SIZE) {
        cache->head = 0;
    }
    strcpy(cache->message[cache->head], message);
    cache->is_full = true;
    pthread_mutex_unlock(&log_lock);
}

void handle_log_response(struct log_queue *entry, struct log_cache *cache) {
    int index = (cache->tail + 1) % CACHE_SIZE;
    char *message = cache->message[index];
    if (strcmp(message, "") == 0) {
        return;
    }
    pthread_mutex_lock(&log_lock);
    log_count++;
    free(entry->entry->message);
    entry->entry->message = malloc(strlen(message) + 100);
    sprintf(entry->entry->message, "%s", message);
    cache->tail++;
    if (cache->tail == CACHE_SIZE) {
        cache->tail = 0;
    }
    free(message);
    pthread_mutex_unlock(&log_lock);
}

void handle_log_error(struct log_queue *entry, struct log_cache *cache) {
    pthread_mutex_lock(&log_lock);
    log_count++;
    free(entry->entry->message);
    entry->entry->message = malloc(100);
    sprintf(entry->entry->message, "Logging Error");
    cache->tail++;
    if (cache->tail == CACHE_SIZE) {
        cache->tail = 0;
    }
    pthread_mutex_unlock(&log_lock);
}

void *logging_thread_routine(void *arg) {
    int thread_id = (int)arg;
    struct log_cache *cache = malloc(sizeof(struct log_cache));
    cache->head = 0;
    cache->tail = 0;
    cache->is_full = false;
    while (true) {
        pthread_mutex_lock(&log_lock);
        if (!is_logging || cache->is_full) {
            sem_post(&semaphore);
            pthread_mutex_unlock(&log_lock);
            break;
        }
        struct log_queue *entry = TAILQ_FIRST(&log_queue_head);
        if (entry == NULL) {
            sem_post(&semaphore);
            pthread_mutex_unlock(&log_lock);
            break;
        }
        handle_log_request(entry, cache);
        TAILQ_REMOVE(&log_queue_head, entry, entries);
        free_log_queue(entry);
        pthread_mutex_unlock(&log_lock);
    }
    free_log_cache(cache);
    return NULL;
}

int create_socket(const char *host, const char *port) {
    struct addrinfo hints;
    struct addrinfo *result;
    int sockfd;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(host, port, &hints, &result) != 0) {
        return -1;
    }
    sockfd = socket(result->ai_family, result->ai_socktype, result->ai_protocol);
    freeaddrinfo(result);
    if (sockfd == -1) {
        return -1;
    }
    return sockfd;
}

int send_message(int sockfd, char *buffer, int len) {
    int n = send(sockfd, buffer, len, 0);
    if (n == -1) {
        return -1;
    }
    return n;
}

int receive_message(int sockfd, char *buffer, int len) {
    int n = recv(sockfd, buffer, len, 0);
    if (n == -1) {
        return -1;
    }
    return n;
}

bool is_valid_log_request(struct log_queue *entry) {
    if (!is_valid_rx_ue_information(entry->entry)) {
        return false;
    }
    return true;
}

void handle_log_fallback(struct log_queue *entry, struct log_cache *cache) {
    log_error(-1);
    pthread_mutex_lock(&log_lock);
    free(entry->entry->message);
    entry->entry->message = malloc(100);
    sprintf(entry->entry->message, "Logging Fallback");
    cache->tail++;
    if (cache->tail == CACHE_SIZE) {
        cache->tail = 0;
    }
    pthread_mutex_unlock(&log_lock);
}

void free_log_queue(struct log_queue *entry) {
    free(entry->entry->message);
    free(entry->entry);
    free(entry);
}

void free_log_cache(struct log_cache *cache) {
    free(cache);
}
```
This is a simple logging module that allows you to log messages in a thread-safe way. It takes a message and logs it asynchronously, so the caller does not have to wait for the log operation to complete before continuing. The log message can be any string, and it will be stored in a queue until it is fetched by the logging module's internal thread.

The logging module uses a producer-consumer pattern to store the log messages in a queue. It has two threads: the main thread that receives the log messages and stores them in the queue, and a background thread that consumes the queue and writes the log messages to the file or console. The main thread uses a mutex to protect the queue from concurrent access, while the background thread uses a semaphore to wait for new messages to be added to the queue.

The `log` function is called by the caller to log a message. It first checks if the logging module has been initialized and if the message is valid. If so, it creates a `log_queue_entry` struct and adds it to the queue using the mutex. The background thread consumes the queue and writes the messages to the file or console asynchronously.

The `init_logging` function initializes the logging module by creating the required threads and starting the background thread that consumes the queue. It also sets the logging level and other parameters.

The `free_log_queue` and `free_log_cache` functions are used to clean up the resources when the logging module is no longer needed. They free the memory allocated for the queue entries and the cache, respectively.

Here's an example of how you can use the logging module:
```c
#include <stdio.h>
#include "logging.h"

int main() {
    init_logging(LOGGING_LEVEL_INFO);
    log("Hello, world!");
    free_log_queue();
    return 0;
}
