using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using System.Diagnostics;
using Microsoft.Extensions.Logging;
using Serilog;

public class AsyncQueryService : IAsyncQueryService
{
    private readonly ILogger<AsyncQueryService> _logger;
    private readonly IDictionary<string, string> _connectionStrings;
    private readonly IDictionary<string, DbProviderFactory> _dbProviderFactories;

    public AsyncQueryService(IConfiguration configuration)
    {
        _logger = LoggerFactory.CreateLogger<AsyncQueryService>();
        _connectionStrings = configuration.GetSection("ConnectionStrings").Get<IDictionary<string, string>>();
        _dbProviderFactories = new Dictionary<string, DbProviderFactory>
        {
            ["SqlServer"] = SqlClientFactory.Instance
        };
    }

    public async Task<QueryResult> ExecuteAsync(string query, string dbProviderName)
    {
        if (string.IsNullOrEmpty(query))
        {
            throw new ArgumentException("Invalid query", nameof(query));
        }

        if (!_connectionStrings.ContainsKey(dbProviderName))
        {
            throw new ArgumentException($"Unknown database provider: {dbProviderName}", nameof(dbProviderName));
        }

        var connectionString = _connectionStrings[dbProviderName];
        using (var connection = _dbProviderFactories[dbProviderName].CreateConnection())
        {
            try
            {
                connection.ConnectionString = connectionString;
                await connection.OpenAsync();

                using (var command = new SqlCommand(query, connection))
                {
                    command.CommandType = CommandType.Text;
                    return await GetQueryResultAsync(command);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to execute query");
                throw;
            }
        }
    }

    private async Task<QueryResult> GetQueryResultAsync(SqlCommand command)
    {
        using (var reader = await command.ExecuteReaderAsync())
        {
            var result = new QueryResult();
            while (await reader.ReadAsync())
            {
                result.AddRow(reader);
            }
            return result;
        }
    }

    public class QueryResult
    {
        private readonly List<Dictionary<string, object>> _rows = new List<Dictionary<string, object>>();

        public void AddRow(IDataRecord record)
        {
            var row = new Dictionary<string, object>();
            for (var i = 0; i < record.FieldCount; i++)
            {
                row[record.GetName(i)] = record[i];
            }
            _rows.Add(row);
        }

        public IEnumerable<Dictionary<string, object>> Rows => _rows;
    }
}
```
