        };

        public Client(string baseUrl) : this(baseUrl, null) {}

        public Client(string baseUrl, OAuth2Authentication oauth2Authentication)
        {
            _httpClient = new HttpClient();
            _oauth2Authentication = oauth2Authentication;

            if (oauth2Authentication != null)
            {
                _oauth2Authentication.OnRefreshToken += OAuth2Authentication_OnRefreshToken;
            }
        }

        public async Task<HttpResponseMessage> GetAsync(string url, CancellationToken cancellationToken = default)
        {
            return await SendRequestAsync(url, HttpMethod.Get, null, cancellationToken);
        }

        public async Task<HttpResponseMessage> PostAsync<T>(string url, T data, CancellationToken cancellationToken = default) where T : class
        {
            var jsonData = JsonConvert.SerializeObject(data);
            return await SendRequestAsync(url, HttpMethod.Post, new StringContent(jsonData, Encoding.UTF8, "application/json"), cancellationToken);
        }

        public async Task<HttpResponseMessage> PutAsync<T>(string url, T data, CancellationToken cancellationToken = default) where T : class
        {
            var jsonData = JsonConvert.SerializeObject(data);
            return await SendRequestAsync(url, HttpMethod.Put, new StringContent(jsonData, Encoding.UTF8, "application/json"), cancellationToken);
        }

        public async Task<HttpResponseMessage> DeleteAsync(string url, CancellationToken cancellationToken = default)
        {
            return await SendRequestAsync(url, HttpMethod.Delete, null, cancellationToken);
        }

        private async Task<HttpResponseMessage> SendRequestAsync(string url, HttpMethod method, HttpContent content, CancellationToken cancellationToken = default)
        {
            using var request = new HttpRequestMessage(method, url)
            {
                Content = content
            };

            if (_oauth2Authentication != null)
            {
                _oauth2Authentication.ApplyAuthenticationHeaders(request);
            }

            foreach (var header in DefaultHeaders)
            {
                request.Headers.Add(header.Key, header.Value);
            }

            var response = await _httpClient.SendAsync(request, cancellationToken).ConfigureAwait(false);
            return response;
        }

        private void OAuth2Authentication_OnRefreshToken()
        {
            // TODO: handle refresh token here
        }

        public void Dispose()
        {
            _httpClient.Dispose();
        }
    }
}
