#define MAX_DEVICES 100
#define MAX_SENSORS 20
#define MAX_LINE_LENGTH 1024

typedef struct {
    char *device_id;
    time_t timestamp;
    float sensor_values[MAX_SENSORS];
    float moving_average;
} device_data_t;

// Reads a line from the log file and parses it into a device_data_t struct.
int parse_line(char *line, device_data_t *data) {
    // Split the line into three parts: device ID, timestamp, and sensor values.
    char *token = strtok(line, ",");
    if (!token) return -1;
    data->device_id = token;

    token = strtok(NULL, ",");
    if (!token) return -2;
    int year, month, day, hour, minute, second;
    if (sscanf(token, "%d-%d-%d %d:%d:%d", &year, &month, &day, &hour, &minute, &second) != 6) {
        fprintf(stderr, "Invalid timestamp: %s\n", token);
        return -3;
    }
    data->timestamp = timegm(&date) * 1000 + second;

    for (int i = 0; i < MAX_SENSORS && (token = strtok(NULL, ",")); ++i) {
        if (!isdigit(*token)) {
            fprintf(stderr, "Invalid sensor value: %s\n", token);
            return -4;
        }
        data->sensor_values[i] = atof(token);
    }

    // Compute the moving average of the last three sensor values.
    int num_values = sizeof(data->sensor_values) / sizeof(*data->sensor_values);
    float sum = 0;
    for (int i = max(num_values - 3, 0); i < num_values; ++i) {
        sum += data->sensor_values[i];
    }
    data->moving_average = sum / 3;

    return 0;
}

// Reads the log file line by line and processes each device's data.
int process_file(FILE *file) {
    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line into a device_data_t struct.
        device_data_t data;
        if (parse_line(line, &data) != 0) {
            fprintf(stderr, "Error parsing line: %s\n", line);
            continue;
        }

        // Validate the input data.
        for (int i = 0; i < MAX_SENSORS; ++i) {
            if (!isnan(data.sensor_values[i])) {
                // Check for non-numeric sensor values and timestamps outside a valid range.
                if (!isdigit(*token)) {
                    fprintf(stderr, "Invalid sensor value: %f\n", data.sensor_values[i]);
                    return -1;
                } else if (data.timestamp > time(NULL) + 3600 * 24 * 365) {
                    fprintf(stderr, "Invalid timestamp: %ld\n", data.timestamp);
                    return -2;
                }
            }
        }

        // Handle lines with varying lengths.
        int line_length = strlen(line);
        if (line_length < 10) {
            fprintf(stderr, "Invalid line length: %d\n", line_length);
            return -3;
        } else if (line_length > MAX_LINE_LENGTH - 10) {
            fprintf(stderr, "Line too long: %s\n", line);
            return -4;
        }

        // Write the processed data to a new file.
        FILE *outfile = fopen("processed_data.csv", "a");
        if (!outfile) {
            perror("Error opening output file");
            return -5;
        }
        fprintf(outfile, "%s,%ld,", data.device_id, data.timestamp);
        for (int i = 0; i < MAX_SENSORS; ++i) {
            if (!isnan(data.sensor_values[i])) {
                fprintf(outfile, "%f,", data.sensor_values[i]);
            } else {
                break;
            }
        }
        fprintf(outfile, "%f\n", data.moving_average);
        if (fclose(outfile)) {
            perror("Error closing output file");
            return -6;
        }
    }
    return 0;
}

int main() {
    // Open the log file and process it line by line.
    FILE *file = fopen("log_file.csv", "r");
    if (!file) {
        perror("Error opening input file");
        exit(1);
    }
    int result = process_file(file);
    if (fclose(file)) {
        perror("Error closing input file");
        exit(1);
    }

    // Log any errors to a separate error log file.
    FILE *error_log = fopen("error.log", "a");
    if (!error_log) {
        perror("Error opening error log file");
        exit(1);
    }
    if (result < 0) {
        fprintf(error_log, "Error processing line %d: %s\n", result, strerror(-result));
    }
    if (fclose(error_log)) {
        perror("Error closing error log file");
        exit(1);
    }

    return 0;
}
