#include <openssl/ssl.h>
#include <openssl/err.h>
#include <openssl/x509v3.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

// Define the TLS 1.3 communication library structure
struct TlsLibrary {
    SSL_CTX* ctx; // SSL context
    SSL* ssl; // SSL object
    X509* cert; // Certificate
    BIO* bio; // BIO for SSL connections
    int port; // Port number for server socket
};

// Function to initialize the TLS 1.3 communication library
void initLibrary(struct TlsLibrary* lib) {
    // Initialize SSL context and set up cipher suites based on client capabilities
    lib->ctx = SSL_CTX_new(TLSv1_3_client_method());
    SSL_CTX_set_options(lib->ctx, SSL_OP_NO_COMPRESSION | SSL_OP_SINGLE_ECDH_USE);
    SSL_CTX_set_cipher_list(lib->ctx, "HIGH:!aNULL@STRENGTH");

    // Initialize SSL object and set up certificate verification callback
    lib->ssl = SSL_new(lib->ctx);
    SSL_set_verify(lib->ssl, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

    // Initialize BIO for SSL connections and set up port number for server socket
    lib->bio = BIO_new_socket(lib->port, BIO_NOCLOSE);
}

// Function to establish a TLS 1.3 connection with a remote server
int connectToServer(struct TlsLibrary* lib, const char* hostname, int port) {
    // Set up SSL object and initialize handshake
    SSL_set_connect_state(lib->ssl);
    SSL_set_fd(lib->ssl, lib->bio);

    // Perform TLS 1.3 handshake with server
    if (SSL_do_handshake(lib->ssl) <= 0) {
        printf("Error: failed to establish connection with server\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Verify server certificate and set up certificate chain
    X509* cert = SSL_get_peer_certificate(lib->ssl);
    if (cert == NULL) {
        printf("Error: failed to verify server certificate\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Set up client authentication with certificate chain
    SSL_set_certificate(lib->ssl, cert);
    SSL_CTX_use_certificate(lib->ctx, cert);

    // Return successful connection establishment
    return 0;
}

// Function to send data over the TLS 1.3 connection
int sendData(struct TlsLibrary* lib, const char* data) {
    // Set up SSL object and initialize handshake
    SSL_set_connect_state(lib->ssl);
    SSL_set_fd(lib->ssl, lib->bio);

    // Perform TLS 1.3 handshake with server
    if (SSL_do_handshake(lib->ssl) <= 0) {
        printf("Error: failed to establish connection with server\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Verify server certificate and set up certificate chain
    X509* cert = SSL_get_peer_certificate(lib->ssl);
    if (cert == NULL) {
        printf("Error: failed to verify server certificate\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Set up client authentication with certificate chain
    SSL_set_certificate(lib->ssl, cert);
    SSL_CTX_use_certificate(lib->ctx, cert);

    // Send data over TLS 1.3 connection
    int len = strlen(data);
    if (SSL_write(lib->ssl, data, len) <= 0) {
        printf("Error: failed to send data over TLS 1.3 connection\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Return successful data transmission
    return len;
}

// Function to receive data over the TLS 1.3 connection
int receiveData(struct TlsLibrary* lib, char* buffer) {
    // Set up SSL object and initialize handshake
    SSL_set_connect_state(lib->ssl);
    SSL_set_fd(lib->ssl, lib->bio);

    // Perform TLS 1.3 handshake with server
    if (SSL_do_handshake(lib->ssl) <= 0) {
        printf("Error: failed to establish connection with server\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Verify server certificate and set up certificate chain
    X509* cert = SSL_get_peer_certificate(lib->ssl);
    if (cert == NULL) {
        printf("Error: failed to verify server certificate\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Set up client authentication with certificate chain
    SSL_set_certificate(lib->ssl, cert);
    SSL_CTX_use_certificate(lib->ctx, cert);

    // Receive data over TLS 1.3 connection
    int len = SSL_read(lib->ssl, buffer, 1024);
    if (len <= 0) {
        printf("Error: failed to receive data over TLS 1.3 connection\n");
        SSL_free(lib->ssl);
        return -1;
    }

    // Return successful data reception
    return len;
}

// Function to handle handshake failures and recover from them
void handleHandshakeFailures(struct TlsLibrary* lib, int fd) {
    // Check for connection failure
    if (SSL_get_error(lib->ssl, -1) == SSL_ERROR_SYSCALL && errno == ECONNRESET) {
        printf("Error: handshake failed due to connection reset\n");
        SSL_free(lib->ssl);
        close(fd);
    }

    // Check for invalid certificate
    if (SSL_get_error(lib->ssl, -1) == SSL_ERROR_SYSCALL && errno == ECONNREFUSED) {
        printf("Error: handshake failed due to invalid certificate\n");
        SSL_free(lib->ssl);
        close(fd);
    }

    // Check for other handshake failures and recover from them
    if (SSL_get_error(lib->ssl, -1) == SSL_ERROR_SYSCALL && errno != ECONNRESET && errno != ECONNREFUSED) {
        printf("Error: handshake failed due to other reasons\n");
        SSL_free(lib->ssl);
        close(fd);
    }
}

// Function to handle TLS 1.3 connection termination
void handleConnectionTermination(struct TlsLibrary* lib, int fd) {
    // Check for connection closure by server
    if (SSL_get_error(lib->ssl, -1) == SSL_ERROR_ZERO_RETURN) {
        printf("Error: TLS 1.3 connection terminated by server\n");
        SSL_free(lib->ssl);
        close(fd);
    }

    // Check for other reasons of TLS 1.3 connection termination
    if (SSL_get_error(lib->ssl, -1) != SSL_ERROR_ZERO_RETURN) {
        printf("Error: TLS 1.3 connection terminated due to other reasons\n");
        SSL_free(lib->ssl);
        close(fd);
    }
}

// Main function for the client
int main() {
    // Initialize library
    SSL_library_init();

    // Load certificate and private key
    FILE* fp = fopen("cert.crt", "r");
    X509* cert = PEM_read_X509(fp, NULL, NULL, NULL);
    EVP_PKEY* pkey = EVP_PKEY_new();
    fclose(fp);

    // Create SSL context and set certificate and private key
    SSL_CTX* ctx = SSL_CTX_new(TLSv1_2_client_method());
    SSL_CTX_use_certificate(ctx, cert);
    SSL_CTX_use_PrivateKey(ctx, pkey);

    // Create new TLS 1.2 client object
    SSL* ssl = SSL_new(ctx);

    // Set socket as file descriptor for TLS 1.2 client
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    SSL_set_fd(ssl, fd);

    // Connect to server
    if (connect(fd, (struct sockaddr*) &serverAddr, sizeof(serverAddr)) < 0) {
        perror("Error connecting to server");
        return -1;
    }

    // Perform TLS 1.2 handshake
    if (SSL_connect(ssl) <= 0) {
        perror("Error performing TLS 1.2 handshake");
        SSL_free(ssl);
        close(fd);
        return -1;
    }

    // Send data over TLS 1.2 connection
    char buffer[1024];
    strcpy(buffer, "Hello, world!");
    int len = send(fd, buffer, strlen(buffer), 0);
    if (len < 0) {
        perror("Error sending data over TLS 1.2 connection");
        SSL_free(ssl);
        close(fd);
        return -1;
    }

    // Receive data over TLS 1.2 connection
    char response[1024];
    len = recv(fd, response, 1024, 0);
    if (len < 0) {
        perror("Error receiving data over TLS 1.2 connection");
        SSL_free(ssl);
        close(fd);
        return -1;
    }

    // Print received data
    printf("Response from server: %s\n", response);

    // Clean up and exit
    SSL_free(ssl);
    close(fd);
    return 0;
}
