// Third-party libraries
#include "video_processing_library.h"
#include "metadata_repository.h"
#include "storage_service.h"

// System constants
const int NUM_SERVICE_INSTANCES = 5; // Number of service instances to distribute tasks across
const int MIN_THREADS_PER_INSTANCE = 2; // Minimum number of threads per instance for processing transcoding requests
const int MAX_THREADS_PER_INSTANCE = 8; // Maximum number of threads per instance for processing transcoding requests
const int QUEUE_SIZE = 1000; // Size of the request queue to handle pending transcoding jobs
const int POLLING_INTERVAL = 100; // Polling interval in milliseconds to check for completed transcoding jobs
const int CACHE_EXPIRATION_TIME = 3600; // Time in seconds that the cache will store frequently requested formats and resolutions
const int MAX_JOB_FAILURES = 5; // Maximum number of retries for a job before marking it as failed

// Global variables
std::vector<int> service_instance_count(NUM_SERVICE_INSTANCES, 0); // Number of active threads per service instance
std::mutex request_queue_mutex; // Mutex to protect the request queue
std::condition_variable request_queue_cv; // Condition variable to signal changes in the request queue
std::deque<TranscodingJob> request_queue; // Queue of pending transcoding jobs
std::map<std::string, TranscodingResult> result_cache; // Cache of frequently requested formats and resolutions

// Function definitions
void init_service_instances();
void submit_transcoding_job(TranscodingJob job);
void process_transcoding_request(int instance_id, int thread_id);
void update_job_status(TranscodingJob job, TranscodingResult result);
bool is_format_supported(std::string format);
bool is_resolution_supported(int resolution);

// Main function
int main() {
    init_service_instances(); // Initialize service instances with appropriate number of threads
    while (true) {
        std::unique_lock<std::mutex> lock(request_queue_mutex);
        request_queue_cv.wait(lock, [](){return !request_queue.empty() || service_instance_count[0] == 0;}); // Wait for a pending request or all instances being idle
        if (!request_queue.empty()) {
            TranscodingJob job = request_queue.front();
            int instance_id = get_next_service_instance(job); // Get the next service instance to handle the request
            submit_transcoding_job(job);
            process_transcoding_request(instance_id, 0); // Submit the transcoding job to the selected service instance
        } else {
            std::cout << "All instances are idle. Shutting down." << std::endl;
            return 0;
        }
    }
}

// Initialize service instances with appropriate number of threads
void init_service_instances() {
    for (int i = 0; i < NUM_SERVICE_INSTANCES; ++i) {
        int num_threads = std::max(std::min(MAX_THREADS_PER_INSTANCE, get_available_thread_count()), MIN_THREADS_PER_INSTANCE); // Calculate the appropriate number of threads for the instance
        service_instance_count[i] = num_threads;
        std::cout << "Initializing service instance " << i << " with " << num_threads << " threads." << std::endl;
    }
}

// Submit a transcoding job to the request queue and update the cache if necessary
void submit_transcoding_job(TranscodingJob job) {
    std::lock_guard<std::mutex> lock(request_queue_mutex);
    request_queue.push_back(job);
    if (result_cache.find(job.format + "_" + std::to_string(job.resolution)) == result_cache.end()) { // Check if the format and resolution are already cached
        TranscodingResult result = run_video_transcoding(job.input_file, job.output_file, job.format, job.resolution); // Run transcoding on the input file and get the result
        result_cache[job.format + "_" + std::to_string(job.resolution)] = result; // Update the cache with the new result
    }
}

// Get the next service instance to handle a transcoding request based on load balancing criteria
int get_next_service_instance(TranscodingJob job) {
    int max_load = 0;
    int selected_instance = -1;
    for (int i = 0; i < NUM_SERVICE_INSTANCES; ++i) {
        if (service_instance_count[i] > max_load && service_instance_count[i] < MAX_THREADS_PER_INSTANCE) { // Select the instance with the lowest load that is not at capacity
            selected_instance = i;
            max_load = service_instance_count[i];
        }
    }
    return selected_instance;
}

// Process a transcoding request for a given service instance
void process_transcoding_request(int instance_id, int thread_id) {
    std::lock_guard<std::mutex> lock(request_queue_mutex);
    TranscodingJob job = request_queue.front();
    if (thread_id < service_instance_count[instance_id]) { // Check if the instance has available threads to process the request
        result_cache[job.format + "_" + std::to_string(job.resolution)].copy_to_file(job.output_file); // Copy the cached transcoded file to the output file
        update_job_status(job, result_cache[job.format + "_" + std::to_string(job.resolution)]); // Update the job status with the transcoding result
        request_queue.pop_front(); // Remove the completed request from the queue
    } else { // If there are no available threads, wait for a while before retrying
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        process_transcoding_request(instance_id, 0); // Retry with the same instance and thread ID
    }
}

// Update the job status with the transcoding result
void update_job_status(TranscodingJob job, TranscodingResult result) {
    std::lock_guard<std::mutex> lock(request_queue_mutex);
    for (auto& j : request_queue) { // Search through the queue for the completed job and update its status accordingly
        if (j.job_id == job.job_id) {
            j.status = result.status;
            break;
        }
    }
}

// Check if a given video format is supported by the system
bool is_format_supported(std::string format) {
    return format == "mp4" || format == "mov" || format == "avi"; // Supported formats are mp4, mov, and avi
}

// Check if a given resolution is supported by the system
bool is_resolution_supported(int resolution) {
    return resolution > 0 && resolution <= 1080; // Resolutions between 1 and 1080 are supported
}']

