#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <future>

class DynamicDatabaseConnectionPool {
public:
    DynamicDatabaseConnectionPool(int initialSize = 0) : size_(initialSize), connections_(initialSize) {}

    void initializeConnections(int count) {
        for (int i = 0; i < count; i++) {
            connections_.push_back(std::make_shared<DatabaseConnection>());
        }
    }

    int getConnectionCount() { return size_; }

    void setConnectionCount(int count) {
        if (count <= 0 || count > maxSize_) {
            throw std::invalid_argument("Invalid connection count");
        }
        size_ = count;
    }

    int getMaxSize() { return maxSize_; }

    void setMaxSize(int maxSize) { maxSize_ = maxSize; }

    void resizePool(int newSize, bool forceResize = false) {
        if (newSize <= 0 || newSize > maxSize_) {
            throw std::invalid_argument("Invalid pool size");
        }
        if (!forceResize && newSize == size_) {
            return;
        }
        // Shrink the pool if necessary.
        while (size_ > newSize) {
            connections_.pop_back();
            size_--;
        }
        // Grow the pool if necessary.
        for (int i = 0; i < newSize - size_; i++) {
            connections_.push_back(std::make_shared<DatabaseConnection>());
            size_++;
        }
    }

    std::shared_ptr<DatabaseConnection> getConnection() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (connections_.empty()) {
            conditionVariable_.wait(lock);
        }
        auto connection = connections_.back();
        connections_.pop_back();
        return connection;
    }

    void releaseConnection(const std::shared_ptr<DatabaseConnection>& connection) {
        std::unique_lock<std::mutex> lock(mutex_);
        connections_.push_back(connection);
        conditionVariable_.notify_all();
    }

    ~DynamicDatabaseConnectionPool() {
        for (auto& connection : connections_) {
            connection->close();
        }
    }

private:
    int size_;
    int maxSize_;
    std::vector<std::shared_ptr<DatabaseConnection>> connections_;
    std::mutex mutex_;
    std::condition_variable conditionVariable_;
};
```
