        {
            _algorithms = algorithms;
            _serviceProvider = serviceProvider;
        }

        public async Task<string> DecryptMessageAsync(string base64EncodedData, string key, string iv, string algorithm)
        {
            var securityAlgorithm = _algorithms.FirstOrDefault(a => a.GetType().Name == algorithm);
            if (securityAlgorithm == null)
                throw new ArgumentException("Invalid encryption algorithm", nameof(algorithm));

            var encryptedData = Convert.FromBase64String(base64EncodedData);
            using var decryptor = securityAlgorithm.CreateDecryptor();
            using var msDecrypt = new MemoryStream(encryptedData, 0, encryptedData.Length);
            using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
            var plainTextBytes = await csDecrypt.ReadAsync();
            return Encoding.UTF8.GetString(plainTextBytes);
        }

        public async Task<string> ProcessDataAsync(string encryptedDataPath, string[] keyPairs, string iv, int batchSize)
        {
            var encryptedData = File.ReadAllLines(encryptedDataPath);
            var processedData = new List<string>();

            foreach (var encryptedLine in encryptedData)
            {
                var keyPair = keyPairs[new Random().Next(keyPairs.Length)];
                var key = keyPair.Split(':')[0];
                var iv = keyPair.Split(':')[1];
                var algorithm = _algorithms[new Random().Next(_algorithms.Count)]
                    .GetType()
                    .Name;

                using var encryptor = await GetEncryptorAsync(algorithm);
                using var msEncrypt = new MemoryStream();
                using var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write);
                await csEncrypt.WriteAsync(encryptedLine, 0, encryptedLine.Length);
                csEncrypt.FlushFinalBlock();
                processedData.Add(Convert.ToBase64String(msEncrypt.ToArray()));
            }

            return string.Join(',', processedData);
        }
    }
}
