using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace SecureDataProcessor
{
    public class DataProcessor
    {
        private readonly object _lock = new object();
        private readonly Dictionary<string, EncryptionAlgorithm> _encryptionAlgorithms = new Dictionary<string, EncryptionAlgorithm>();
        private readonly Dictionary<string, DecryptionAlgorithm> _decryptionAlgorithms = new Dictionary<string, DecryptionAlgorithm>();

        public async Task<byte[]> ProcessDataAsync(byte[] encryptedData, string encryptionAlgorithmName, string decryptionAlgorithmName)
        {
            if (!_encryptionAlgorithms.ContainsKey(encryptionAlgorithmName))
                throw new NotSupportedException($"Encryption algorithm '{encryptionAlgorithmName}' is not supported.");

            if (!_decryptionAlgorithms.ContainsKey(decryptionAlgorithmName))
                throw new NotSupportedException($"Decryption algorithm '{decryptionAlgorithmName}' is not supported.");

            var encryptionAlgorithm = _encryptionAlgorithms[encryptionAlgorithmName];
            var decryptionAlgorithm = _decryptionAlgorithms[decryptionAlgorithmName];

            var encryptedDataStream = new MemoryStream(encryptedData);
            var decryptedDataStream = await DecryptAsync(encryptedDataStream, encryptionAlgorithmName);
            var processedDataStream = ProcessDataAsync(decryptedDataStream, decryptionAlgorithmName);
            return processedDataStream.ToArray();
        }

        private async Task<MemoryStream> DecryptAsync(MemoryStream encryptedDataStream, string encryptionAlgorithmName)
        {
            if (!_encryptionAlgorithms.ContainsKey(encryptionAlgorithmName))
                throw new NotSupportedException($"Encryption algorithm '{encryptionAlgorithmName}' is not supported.");

            var encryptionAlgorithm = _encryptionAlgorithms[encryptionAlgorithmName];
            var decryptedDataStream = new MemoryStream();
            await Task.Run(() => encryptionAlgorithm.Decrypt(encryptedDataStream, decryptedDataStream));
            return decryptedDataStream;
        }

        private async Task<MemoryStream> ProcessDataAsync(MemoryStream decryptedDataStream, string decryptionAlgorithmName)
        {
            if (!_decryptionAlgorithms.ContainsKey(decryptionAlgorithmName))
                throw new NotSupportedException($"Decryption algorithm '{decryptionAlgorithmName}' is not supported.");

            var decryptionAlgorithm = _decryptionAlgorithms[decryptionAlgorithmName];
            var processedDataStream = new MemoryStream();
            await Task.Run(() => decryptionAlgorithm.Process(decryptedDataStream, processedDataStream));
            return processedDataStream;
        }
    }
}
