    int event_value;
} NetworkEvent;

NetworkEvent* initialize_array(int size) {
    // Allocate memory for the array of NetworkEvents
    NetworkEvent *events = malloc(size * sizeof(NetworkEvent));
    if (events == NULL) {
        printf("Error: Unable to allocate memory for events array\n");
        return NULL;
    }

    // Initialize each element in the array with a default value
    for (int i = 0; i < size; i++) {
        memset(events[i].event_type, '\0', sizeof(events[i].event_type));
        events[i].event_value = -1;
    }

    return events;
}

void populate_array(NetworkEvent* events, int size) {
    // Read events from the external event ingestion service and populate the array
    while (size > 0) {
        NetworkEvent current_event;

        if (!external_event_ingest(&current_event)) {
            printf("Error: Unable to retrieve an event from the external service\n");
            break;
        }

        events[size - 1] = current_event;
        size--;
    }
}

void cleanup(NetworkEvent* events) {
    // Release memory allocated for the events array
    free(events);
}
