// Define a struct to represent the sensor data
struct SensorData {
  double temperature;
  double humidity;
  double pressure;
  std::string sensor_location;
  std::chrono::time_point<std::chrono::system_clock> timestamp;
};

// Define a function to process the data from all the sensors
void processSensorData(const std::vector<SensorData>& data) {
  // Iterate over the data and calculate the average temperature, humidity, and pressure for each location
  std::unordered_map<std::string, double> locationAverages;
  for (const auto& d : data) {
    locationAverages[d.sensor_location] += d.temperature;
    locationAverages[d.sensor_location] += d.humidity;
    locationAverages[d.sensor_location] += d.pressure;
  }

  // Calculate the average temperature, humidity, and pressure for all locations
  double totalTemperature = std::accumulate(locationAverages.begin(), locationAverages.end(), 0.0);
  double totalHumidity = std::accumulate(locationAverages.begin(), locationAverages.end(), 0.0);
  double totalPressure = std::accumulate(locationAverages.begin(), locationAverages.end(), 0.0);
  size_t numSensors = data.size();

  // Print the average temperature, humidity, and pressure for all locations
  std::cout << "Average temperature: " << totalTemperature / numSensors << std::endl;
  std::cout << "Average humidity: " << totalHumidity / numSensors << std::endl;
  std::cout << "Average pressure: " << totalPressure / numSensors << std::endl;
}

// Define a function to handle incoming data from the sensors
void handleIncomingData(const SensorData& d) {
  // Add the data to the vector of sensor data
  sensorData.push_back(d);

  // If the vector has enough data, process it
  if (sensorData.size() >= 10) {
    processSensorData(sensorData);
    // Clear the vector
    sensorData.clear();
  }
}

