        this->processors.resize(apiEndpoints.size());
    }

    // Add a new API endpoint to the list of available endpoints
    void addEndpoint(const string& endpoint) {
        lock_guard<mutex> guard(this->endpointsMutex);
        this->apiEndpoints.push_back(endpoint);
    }

    // Remove an API endpoint from the list of available endpoints
    void removeEndpoint(const string& endpoint) {
        lock_guard<mutex> guard(this->endpointsMutex);
        this->apiEndpoints.erase(remove(begin(this->apiEndpoints), end(this->apiEndpoints), endpoint), end(this->apiEndpoints));
    }

    // Process a data stream record
    void processRealtimeStream(DATA_STREAM_RECORD& record) {
        lock_guard<mutex> guard(this->processorsMutex);

        // Determine the next processor to use based on the record's source ID
        int nextProcessor = (record.sourceId % this->apiEndpoints.size());

        // Pass the record to the appropriate processor for processing
        this->processors[nextProcessor]->push(record);
    }

private:
    // Vector of API endpoints
    vector<string> apiEndpoints;

    // Map of stream processors, one for each endpoint
    map<string, unique_ptr<StreamProcessor>> processors;

    // Mutexes to protect access to the vectors and maps
    mutex endpointsMutex;
    mutex processorsMutex;
};

int main() {
    // Initialize the stream processor with multiple API endpoints
    vector<string> apiEndpoints = {"api1", "api2", "api3"};
    StreamProcessor streamProcessor(apiEndpoints);

    // Add additional API endpoints as needed
    streamProcessor.addEndpoint("api4");

    // Remove an API endpoint from the list of available endpoints
    streamProcessor.removeEndpoint("api2");

    // Process a data stream record using the appropriate processor
    DATA_STREAM_RECORD record;
    record.timestamp = chrono::high_resolution_clock::now().time_since_epoch().count();
    record.sourceId = 100;
    record.dataType = 2;
    record.metadata["key"] = "value";
    streamProcessor.processRealtimeStream(record);
}']

