public class DynamicObjectDeserializer {
    private static final int BATCH_SIZE = 1000; // adjust as needed
    private static final long BYTE_ARRAY_LIMIT = 10 * 1024 * 1024; // 10MB
    private static final Map<String, Object> DESERIALIZATION_STRATEGIES = Map.of(
        "classA", new ClassADeserializationStrategy(),
        "classB", new ClassBDeserializationStrategy()
    );

    public List<Object> deserializeObjects(byte[] byteArray) throws Exception {
        if (byteArray.length > BYTE_ARRAY_LIMIT) {
            throw new IllegalArgumentException("Byte array size exceeds limit");
        }

        List<Object> objects = new ArrayList<>();
        try (CompletableFuture<List<Object>> deserializationResult = deserializeObjectsInBatches(byteArray)) {
            objects.addAll(deserializationResult.get());
        } catch (Exception e) {
            // handle error
        }

        return objects;
    }

    private CompletableFuture<List<Object>> deserializeObjectsInBatches(byte[] byteArray) throws Exception {
        int batchCount = (int) Math.ceil((double) byteArray.length / BATCH_SIZE);
        List<CompletableFuture<List<Object>>> batchDeserializationResults = new ArrayList<>();

        for (int i = 0; i < batchCount; i++) {
            int startIndex = i * BATCH_SIZE;
            int endIndex = Math.min(byteArray.length, (i + 1) * BATCH_SIZE);
            byte[] currentBatch = Arrays.copyOfRange(byteArray, startIndex, endIndex);
            batchDeserializationResults.add(deserializeObjectsInSingleBatch(currentBatch));
        }

        return CompletableFuture.allOf(batchDeserializationResults.toArray(new CompletableFuture[0])).thenApply(v -> {
            List<Object> objects = new ArrayList<>();
            for (CompletableFuture<List<Object>> batchResult : batchDeserializationResults) {
                objects.addAll(batchResult.join());
            }
            return objects;
        });
    }

    private CompletableFuture<List<Object>> deserializeObjectsInSingleBatch(byte[] byteArray) throws Exception {
