                byte[] objectBytes = getObjectBytesFromByteArray(byteArray, className);
                deserializedObjects.put(className, object);
            } catch (Exception e) {
                // handle error
            }
        }

        return CompletableFuture.completedFuture(deserializedObjects.values());
    }

