    struct Node *head;
    struct Node *tail;
    int num_nodes;
    int num_jobs;
};

// Initialize a job with an ID and name
void init_job(struct Job *job, int id, char *name) {
    job->id = id;
    job->name = name;
}

// Create a new job with an ID and name
struct Job* create_job(int id, char *name) {
    struct Job *job = (struct Job*) malloc(sizeof(struct Job));
    init_job(job, id, name);
    return job;
}

// Initialize a queue of jobs
void init_queue(struct Queue *queue) {
    queue->head = NULL;
    queue->tail = NULL;
}

// Create a new queue of jobs
struct Queue* create_queue() {
    struct Queue *queue = (struct Queue*) malloc(sizeof(struct Queue));
    init_queue(queue);
    return queue;
}

// Add a job to the end of the queue
void enqueue(struct Queue *queue, struct Job *job) {
    if (queue->tail == NULL) {
        queue->head = job;
        queue->tail = job;
    } else {
        queue->tail->next = job;
        queue->tail = job;
    }
}

// Remove the first job from the queue
struct Job* dequeue(struct Queue *queue) {
    struct Job *job = queue->head;
    if (job == NULL) {
        return NULL;
    }
    queue->head = job->next;
    if (queue->tail == job) {
        queue->tail = NULL;
    }
    job->next = NULL;
    return job;
}

// Initialize a node with an ID and name
void init_node(struct Node *node, int id, char *name) {
    node->id = id;
    node->name = name;
    init_queue(&node->queue);
}

// Create a new node with an ID and name
struct Node* create_node(int id, char *name) {
    struct Node *node = (struct Node*) malloc(sizeof(struct Node));
    init_node(node, id, name);
    return node;
}

