    struct Service *service = (struct Service*) malloc(sizeof(struct Service));
    init_service(service, num_nodes);
    return service;
}

// Add a node to the end of the list of nodes in the service
void add_node(struct Service *service, struct Node *node) {
    if (service->tail == NULL) {
        service->head = node;
        service->tail = node;
    } else {
        service->tail->next = node;
        service->tail = node;
    }
}

// Remove a node from the list of nodes in the service
struct Node* remove_node(struct Service *service, struct Node *node) {
    struct Node *prev_node = NULL;
    struct Node *curr_node = service->head;
    while (curr_node != NULL && curr_node != node) {
        prev_node = curr_node;
        curr_node = curr_node->next;
    }
    if (curr_node == NULL) {
        return NULL;
    }
    if (prev_node == NULL) {
        service->head = curr_node->next;
        if (service->tail == curr_node) {
            service->tail = NULL;
        }
    } else {
        prev_node->next = curr_node->next;
        if (service->tail == curr_node) {
