#include <functional>

// Geolocation libraries
#include "geolocation/ip2location.h"
#include "geolocation/maxmind.h"

// Thread pool
class ThreadPool {
public:
    ThreadPool(size_t numThreads) : numThreads_(numThreads), workers_(numThreads) {}

    ~ThreadPool() {
        // Wait for all threads to complete their work
        for (auto& worker : workers_) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

    void addTask(std::function<void()> task) {
        tasks_.push_back(task);

        // If the queue is full, wait for a thread to finish its work before adding more
        if (tasks_.size() >= maxQueueSize_) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            conditionVariable_.wait(lock, [this] { return tasks_.size() < maxQueueSize_; });
        }

        // Add the task to the queue and notify a thread that it can start working
        std::unique_lock<std::mutex> lock(queueMutex_);
        tasks_.push_back(task);
        conditionVariable_.notify_one();
    }

    void waitForEmptyQueue() {
        // Wait for all tasks to complete
        while (tasks_.size() > 0) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            conditionVariable_.wait(lock, [this] { return tasks_.empty(); });
        }
    }

private:
    size_t numThreads_;
    size_t maxQueueSize_ = 10;
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex queueMutex_;
    std::condition_variable conditionVariable_;
};
```
