YAML_CONFIGURATION_FILE_PATH* read_configuration_file(char* configuration_file) {
  // Initialize variables
  YAML_CONFIGURATION_FILE_PATH* config = malloc(sizeof(YAML_CONFIGURATION_FILE_PATH));
  FILE* file = fopen(configuration_file, "r");

  // Read the number of files to process from the configuration file
  char* line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, file)) != -1) {
    if (strncmp(line, "num_files", 9) == 0) {
      char* num_files_str = strtok(line + 9, "\n");
      config->num_files = atoi(num_files_str);
    } else if (strncmp(line, "input_directory", 14) == 0) {
      char* input_directory_str = strtok(line + 15, "\n");
      config->input_directory = input_directory_str;
    } else if (strncmp(line, "output_directory", 15) == 0) {
      char* output_directory_str = strtok(line + 16, "\n");
      config->output_directory = output_directory_str;
    } else if (strncmp(line, "compression_level", 17) == 0) {
      char* compression_level_str = strtok(line + 18, "\n");
      config->compression_level = atoi(compression_level_str);
    } else if (strncmp(line, "encryption_key", 14) == 0) {
      char* encryption_key_str = strtok(line + 15, "\n");
      config->encryption_key = encryption_key_str;
    }
  }

  // Close the configuration file and return the processing parameters
  fclose(file);
  return config;
}

