    struct thread_context *thread_contexts = NULL;
    pthread_t signal_handler_thread;
    semaphore_t semaphore = semaphore_create(1, 0);

    // Initialize the log processing threads
    for (int i = 0; i < num_threads; i++) {
        struct thread_context *ctx = malloc(sizeof(struct thread_context));
        if (ctx == NULL) {
            error_exit("Error allocating memory for thread context");
        }
        ctx->file_ctx = file_contexts;
        semaphore_wait(semaphore);
        pthread_create(&ctx->thread_id, NULL, read_file, (void *) ctx);
    }

    // Initialize the signal handler thread
    pthread_create(&signal_handler_thread, NULL, signal_handler, NULL);

    // Wait for all threads to finish processing log files
    for (struct file_context *file_ctx = file_contexts; file_ctx != NULL; file_ctx = file_ctx->next) {
        semaphore_post(semaphore);
        pthread_join(file_ctx->thread_id, NULL);
    }

    // Clean up resources and exit the program
    semaphore_destroy(semaphore);
    free(file_contexts);
    free(thread_contexts);
    return 0;
}
