#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARN 2
#define LOG_LEVEL_ERROR 3

// Define logging levels as macros
#define DEBUG(format, ...) log_message(LOG_LEVEL_DEBUG, __func__, format, ##__VA_ARGS__)
#define INFO(format, ...) log_message(LOG_LEVEL_INFO, __func__, format, ##__VA_ARGS__)
#define WARN(format, ...) log_message(LOG_LEVEL_WARN, __func__, format, ##__VA_ARGS__)
#define ERROR(format, ...) log_message(LOG_LEVEL_ERROR, __func__, format, ##__VA_ARGS__)

// Define logging function as a static inline
static inline void log_message(int level, const char *function, const char *format, ...) {
    va_list args;
    va_start(args, format);
    switch (level) {
        case LOG_LEVEL_DEBUG:
            printf("[%s] [Debug] ", function);
            break;
        case LOG_LEVEL_INFO:
            printf("[%s] [Info] ", function);
            break;
        case LOG_LEVEL_WARN:
            printf("[%s] [Warn] ", function);
            break;
        case LOG_LEVEL_ERROR:
            printf("[%s] [Error] ", function);
            break;
    }
    vprintf(format, args);
    va_end(args);
}

// Define configuration options as macros
#define DEFAULT_LOGGING_LEVEL LOG_LEVEL_INFO
#define DEFAULT_OUTPUT_FORMAT "%s"

// Define function to modify filename with extension
char *modifyFilename(const char *filename, const char *new_ext) {
    // Check for NULL pointers and empty strings
    if (!filename || !*filename || !new_ext || !*new_ext) {
        ERROR("Invalid input: %s\n", filename);
        return NULL;
    }

    // Initialize variables
    int len = strlen(filename);
    char *modified_filename = malloc(len + 1);
    memcpy(modified_filename, filename, len);
    modified_filename[len] = '\0';

    // Check if file extension already exists
    char *ext = strrchr(modified_filename, '.');
    if (ext) {
        // Replace existing extension with new one
        int ext_len = strlen(new_ext);
        memcpy(ext, new_ext, ext_len + 1);
    } else {
        // Append new extension to filename
        len += strlen(new_ext) + 1;
        modified_filename = realloc(modified_filename, len);
        snprintf(modified_filename + len - 1, 2, ".%s", new_ext);
    }

    // Log original and modified filenames
    DEBUG("Original filename: %s\n", filename);
    INFO("Modified filename: %s\n", modified_filename);

    return modified_filename;
}

// Define thread-safe function to log messages
void log_message_threadsafe(int level, const char *function, const char *format, ...) {
    va_list args;
    va_start(args, format);
    pthread_mutex_lock(&log_mutex);
    switch (level) {
        case LOG_LEVEL_DEBUG:
            printf("[%s] [Debug] ", function);
            break;
        case LOG_LEVEL_INFO:
            printf("[%s] [Info] ", function);
            break;
        case LOG_LEVEL_WARN:
            printf("[%s] [Warn] ", function);
            break;
        case LOG_LEVEL_ERROR:
            printf("[%s] [Error] ", function);
            break;
    }
    vprintf(format, args);
    va_end(args);
    pthread_mutex_unlock(&log_mutex);
}

// Define mutex for thread-safe logging
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Test function with different inputs and logging levels
    const char *filename = "test.txt";
    DEBUG("Testing with filename %s\n", filename);
    INFO("Modified filename: %s\n", modifyFilename(filename, ".pdf"));
    WARN("Testing with NULL pointer input\n");
    ERROR("Invalid input: %s\n", NULL);
    DEBUG("Testing with empty string input\n");
    INFO("Modified filename: %s\n", modifyFilename("", ".pdf"));
    return 0;
}

// Unit tests for the function
