const asyncReduce = (array, initialValue, callback) => {
  // Retry mechanism
  const retryStrategy = new Retry(backoffOptions);
  const fetchDataFromAPI = async (dataURL, params) => {
    try {
      const response = await fetch(dataURL, params);
      return await response.json();
    } catch (error) {
      console.log(`Error fetching data from API: ${error}`);
      retryStrategy.retry(fetchDataFromAPI, [dataURL, params]);
    }
  };

  // Reduction function
  const reduce = async (accumulator, currentValue) => {
    try {
      const response = await fetchDataFromAPI(`${currentValue}.json`, {});
      if (!response || !response.success) {
        throw new Error("Invalid API response");
      }
      const data = response.data;
      return callback(accumulator, currentValue, data);
    } catch (error) {
      console.log(`Error processing data: ${error}`);
      retryStrategy.retry(reduce, [accumulator, currentValue]);
    }
  };

  // Initialization and execution
  let accumulator = initialValue;
  let isCancelled = false;
  const cancel = () => {
    isCancelled = true;
  };
  const progress = {};
  (async function run() {
    for (let i = 0; i < array.length && !isCancelled; i++) {
      accumulator = await reduce(accumulator, array[i]);
      progress.currentStep = i;
      progress.totalSteps = array.length;
      progress.estimatedCompletionTime =
        new Date(new Date().getTime() + (progress.totalSteps - i) * 1000);
    }
    if (!isCancelled) {
      console.log(`Reduction complete: ${accumulator}`);
    }
  })();

  // Exposed functions and properties
  return {
    reduce,
    accumulator,
    cancel,
    progress,
    retryStrategy,
    fetchDataFromAPI,
  };
};
```
