// Define the function to perform atomic operations on the database
bool atomic_operation(transaction_constraint_t *constraint, void (*func)(sqlite3*)) {
  // Check if a lock is already held by this thread
  if (constraint->thread_id == pthread_self()) {
    return false;
  }

  // Acquire the lock and perform the operation
  constraint->mutex = pthread_mutex_lock(&(constraint->mutex));
  func(constraint->db);
  constraint->mutex = pthread_mutex_unlock(&(constraint->mutex));

  return true;
}

// Define the function to handle thread-safe processing across multiple concurrent threads
bool handle_concurrent_access() {
  // Create a new transaction constraint for this thread
  transaction_constraint_t *constraint = malloc(sizeof(transaction_constraint_t));

  // Check if memory allocation failed
  if (!constraint) {
    handle_memory_allocation_failure();
  }

  // Initialize the constraint with a new database connection and a mutex for thread synchronization
  constraint->db = sqlite3_open("database.sqlite", &(constraint->mutex));

  // Check if the database could not be opened
