            : this(logger, analyticsServices, deviceConnectionStrings, maxConcurrentThreads, minMessageQueueSize, connectionTimeout, retryInterval, fallbackStrategy, useFallbackStrategy, useLocalBuffering, useHealthCheckEndpoint, useAutomatedTesting, useResourceUtilizationMonitoring, false)
        { }

