        {
            _logger = logger;
            _analyticsServices = analyticsServices.ToList();
            _deviceConnectionStrings = deviceConnectionStrings.ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
            _maxConcurrentThreads = maxConcurrentThreads;
            _minMessageQueueSize = minMessageQueueSize;
            _connectionTimeout = connectionTimeout;
