        public async Task<bool> ProcessMessageAsync(string deviceId, string message)
        {
            if (!_deviceConnectionStrings.ContainsKey(deviceId))
            {
                throw new ArgumentException("Device ID not found.", nameof(deviceId));
            }

            if (_dataProcessors.TryGetValue(deviceId, out IDeviceTelemetryDataProcessor dataProcessor) && dataProcessor != null)
            {
                await dataProcessor.ProcessMessageAsync(message);
            }
            else
            {
                // Create a new data processor for the device if one does not already exist.
                var dataProcessor = new DeviceTelemetryDataProcessor(_logger, _analyticsServices, deviceId, message, _fallbackStrategy, _connectionTimeout, _retryInterval);
                await dataProcessor.InitializeAsync();
                _dataProcessors[deviceId] = dataProcessor;
            }

            return true;
        }

        public async Task<bool> ProcessMessageBatchAsync(IEnumerable<KeyValuePair<string, string>> messages)
        {
            foreach (var message in messages)
            {
                if (!await ProcessMessageAsync(message.Key, message.Value))
                {
                    return false;
                }
            }

            return true;
        }

        public async Task<bool> InitializeAsync()
        {
            foreach (var deviceId in _deviceConnectionStrings.Keys)
            {
                var dataProcessor = new DeviceTelemetryDataProcessor(_logger, _analyticsServices, deviceId, null, _fallbackStrategy, _connectionTimeout, _retryInterval);
                await dataProcessor.InitializeAsync();
                _dataProcessors[deviceId] = dataProcessor;
            }

            return true;
        }

        public async Task<bool> ShutdownAsync()
        {
            foreach (var deviceId in _deviceConnectionStrings.Keys)
            {
                if (_dataProcessors.TryGetValue(deviceId, out IDeviceTelemetryDataProcessor dataProcessor))
                {
                    await dataProcessor.ShutdownAsync();
                }
            }

            return true;
        }
    }
