namespace IoTTelemetryService
{
    public class TelemetryService : IDisposable
    {
        private const int DefaultBufferSize = 1024 * 1024; // 1MB
        private const int DefaultWorkerCount = Environment.ProcessorCount;
        private readonly ConcurrentQueue<TelemetryMessage> _messageQueue = new();
        private readonly List<Task> _workerTasks = new(DefaultWorkerCount);
        private readonly object _locker = new();
        private CancellationTokenSource _cts = new();
        private bool _disposedValue;

        public TelemetryService()
        {
            // Initialize the worker tasks and message queue
            for (int i = 0; i < DefaultWorkerCount; i++)
            {
                Task.Factory.StartNew(ProcessMessages, _cts.Token);
            }
        }

        public void Dispose()
        {
            if (!_disposedValue)
            {
                // Stop the worker tasks and dispose of managed resources
                _cts.Cancel();
                foreach (var task in _workerTasks)
                {
                    task.Wait(TimeSpan.FromSeconds(5));
                    task.Dispose();
                }
                _messageQueue.Dispose();

                _disposedValue = true;
            }
        }

        public void EnqueueMessage(TelemetryMessage message)
        {
            lock (_locker)
            {
                _messageQueue.Enqueue(message);
            }
        }

        private async Task ProcessMessages()
        {
            while (!_cts.IsCancellationRequested)
            {
                TelemetryMessage message;
                if (_messageQueue.TryDequeue(out message))
                {
