                lock (_locker)
                {
                    _messageQueue.Enqueue(message);
                }
                return;
            }

            // Resume processing upon reconnection
            if (!IsReconnectionError(ex))
            {
                await ProcessMessage(message);
                return;
            }

            // Ensure data consistency and integrity
            using (var dbContext = new IoTTelemetryDbContext())
            {
