typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t *crc;
    uint8_t length;
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_list(NFAPI_CRC_INDICATION_PDU_T **list, int list_size) {
    // Allocate memory for the list of structures
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size);
    if (*list == NULL) {
        // Handle allocation failure
    }

    // Initialize the elements in the list
    for (int i = 0; i < list_size; i++) {
        (*list)[i].crc = NULL;
        (*list)[i].length = 0;
    }
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T **list, int list_size, uint8_t *data, int data_len) {
    // Check for valid input parameters
    if (list == NULL || data == NULL || data_len <= 0) {
        return;
    }

    // Create a temporary buffer to store the CRC values
    uint8_t *tmp_buf = (uint8_t *)malloc(data_len);
    if (tmp_buf == NULL) {
        // Handle allocation failure
    }

    // Compute the CRC values for each element in the list
    int crc_size = sizeof(uint8_t);  // Size of a CRC value (in bytes)
    for (int i = 0; i < list_size; i++) {
        memcpy(tmp_buf, data + i * data_len / list_size, data_len / list_size);
        (*list)[i].crc = crc32(tmp_buf, data_len / list_size);
        (*list)[i].length = data_len;
    }

    // Free the temporary buffer
    free(tmp_buf);
}

void destroy_list(NFAPI_CRC_INDICATION_PDU_T **list, int list_size) {
    if (list != NULL) {
        for (int i = 0; i < list_size; i++) {
            // Free the memory allocated for each element in the list
            free((*list)[i].crc);
        }
        free(*list);
        *list = NULL;
