// RealTimeDataEngine Framework

#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <thread>
#include <future>
#include <chrono>

class RealTimeDataEngine {
private:
    std::mutex mutex_;
    std::vector<std::string> dataSources_;
    std::map<std::string, std::function<void(const std::string&)>> callbacks_;

public:
    RealTimeDataEngine() {
        // Initialize data sources and callbacks
        dataSources_.push_back("source1");
        dataSources_.push_back("source2");
        callbacks_["source1"] = [](const std::string& data) { std::cout << "Callback 1: " << data << std::endl; };
        callbacks_["source2"] = [](const std::string& data) { std::cout << "Callback 2: " << data << std::endl; };
    }

    void addDataSource(const std::string& source) {
        mutex_.lock();
        dataSources_.push_back(source);
        callbacks_[source] = [](const std::string& data) { std::cout << "New Source: " << data << std::endl; };
        mutex_.unlock();
    }

    void removeDataSource(const std::string& source) {
        mutex_.lock();
        dataSources_.erase(std::remove(dataSources_.begin(), dataSources_.end(), source), dataSources_.end());
        callbacks_.erase(source);
        mutex_.unlock();
    }

    void setCallback(const std::string& source, const std::function<void(const std::string&)>& callback) {
        mutex_.lock();
        callbacks_[source] = callback;
        mutex_.unlock();
    }

    void start() {
        // Start processing data sources asynchronously
        for (const auto& source : dataSources_) {
            std::async([this, source]() {
                while (!stopped_) {
                    try {
                        auto data = readData(source);
                        if (!data.empty()) {
                            // Execute callbacks in parallel
                            for (const auto& [key, value] : callbacks_) {
                                std::async([value, data]() { value(data); });
                            }
                        }
                    } catch (const std::exception& e) {
                        std::cerr << "Error processing data from source: " << source << std::endl;
                    }
                }
            });
        }
    }

    void stop() {
        // Stop processing data sources
        stopped_ = true;
        for (const auto& source : dataSources_) {
            removeDataSource(source);
        }
    }

private:
    std::vector<std::string> readData(const std::string& source) {
        // Read data from the specified source
        std::vector<std::string> data;
        if (source == "source1") {
            data.push_back("Data from Source 1");
        } else if (source == "source2") {
            data.push_back("Data from Source 2");
        }
        return data;
    }

    bool stopped_ = false;
};

int main() {
    RealTimeDataEngine engine;
    engine.addDataSource("new-source");
    engine.setCallback("new-source", [](const std::string& data) { std::cout << "New Callback: " << data << std::endl; });
    engine.start();
    // Do other things...
    engine.stop();
    return 0;
}']

