use std::fs;

fn create_directory(name: &str) -> Result<(), Box<dyn Error>> {
    if let Some(path) = std::env::var("SOME_ENV_VAR") {
        // Use the existing value of the environment variable.
        println!("Using existing directory path {}", path);
    } else {
        // Create a new directory with the specified name and set the environment variable.
        let dir = fs::create_dir(name)?;
        std::env::set_var("SOME_ENV_VAR", dir.path());
    }
    Ok(())
}
