#include <iostream>
#include <forward_list>

void insert(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    auto iter = std::find(list.begin(), list.end(), str1);
    if (iter != list.end()) {
        // Insert the second string after the first occurrence of the first string.
        list.insert_after(iter, str2);
    } else {
        // If the first string is not found in the list, insert it at the end.
        list.push_back(str1);
        list.push_back(str2);
    }
}
