    vector<Result> data; // array of cached results
};

// Function to check if a request is in the result cache
bool isInCache(uint8_t* message, uint32_t length) {
    lock_guard<mutex> cacheLock(resultCacheMutex);
    return resultCache.keys.find(hash(message)) != resultCache.keys.end();
}

// Function to retrieve data from the result cache
Result getFromCache(uint8_t* message, uint32_t length) {
    lock_guard<mutex> cacheLock(resultCacheMutex);
    return resultCache.data[hash(message)];
}
