        String token = cache.getIfPresent(username);
        if (token != null) {
            return validateToken(token);
        }

        // If the user's token is not in the cache, fetch it from the identity service and relational database system
        Connection connection = pool.getConnection();
        try {
            Token token = connection.fetchToken(username);
            if (validateToken(token)) {
                cache.put(username, token.toString());
                return true;
            }
        } catch (Exception e) {
            // Handle errors from external dependencies
            return false;
        } finally {
            pool.releaseConnection(connection);
        }

        return false;
    }
}
```
