    public void verifyPasswordReset(String username, String token) {
        // Check if the password reset token is valid for the user and remove it from the secure storage mechanism
        Account account = accountStorage.getAccount(username);
        if (account != null && !account.isDeleted() && validateToken(token, account.getResetTokens())) {
            accountStorage.removeResetToken(username, token);
        } else {
