using namespace std;

struct RX_UE_INFORMATION_TAG {
    // ...
};

struct RNTI {
    // ...
};

struct CRC_INDICATION_REL8_TAG {
    // ...
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInformation;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

class Octree {
public:
    // Initialize the octree with a given capacity and number of leaf nodes
    void setup(int capacity, int numLeafNodes) {
        this->capacity = capacity;
        this->numLeafNodes = numLeafNodes;
        this->data.reserve(capacity);
    }

    // Add a new element to the octree and return its index
    int add(const NFAPI_CRC_INDICATION_PDU_T& elem) {
        int idx = -1;
        if (this->data.size() < this->capacity) {
            idx = this->data.size();
            this->data.push_back(elem);
        } else {
            // Handle memory allocation failures gracefully by returning -1
            return idx;
        }
    }

    // Remove an element from the octree and return its index
    int remove(const NFAPI_CRC_INDICATION_PDU_T& elem) {
        auto it = find(this->data.begin(), this->data.end(), elem);
        if (it != this->data.end()) {
            idx = distance(this->data.begin(), it);
            this->data.erase(it);
        } else {
            // Handle removal failures gracefully by returning -1
            return idx;
        }
    }

    // Return the number of elements in the octree
    int size() {
        return this->data.size();
    }

    // Return the capacity of the octree
    int getCapacity() {
        return this->capacity;
    }

private:
    vector<NFAPI_CRC_INDICATION_PDU_T> data;
    int capacity, numLeafNodes;
};

void setup_octree_with_crc_indications(Octree& octree, int capacity, int numLeafNodes) {
    // Set up the octree with a given capacity and number of leaf nodes
    octree.setup(capacity, numLeafNodes);

    // Generate random RNTIs for each element in the octree
    vector<RNTI> rntis;
    uniform_int_distribution<int> distribution(0, 1000);
    default_random_engine engine;
    for (int i = 0; i < capacity; i++) {
        RNTI rnti;
        rnti.value = distribution(engine);
        octree.add(NFAPI_CRC_INDICATION_PDU_T{rnti});
    }
}

void handle_crc_indication_pdu(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    // Handle a new CRC indication PDU by adding it to the octree
    if (octree.add(pdu)) {
        cout << "Added new CRC indication PDU with RNTI: " << pdu.rnti << endl;
    } else {
        // Handle memory allocation failures gracefully by returning -1
        cout << "Failed to add CRC indication PDU with RNTI: " << pdu.rnti << endl;
    }
}

void handle_crc_indication_pdu(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    // Handle a new CRC indication PDU by removing it from the octree
    if (octree.remove(pdu)) {
        cout << "Removed CRC indication PDU with RNTI: " << pdu.rnti << endl;
    } else {
        // Handle removal failures gracefully by returning -1
        cout << "Failed to remove CRC indication PDU with RNTI: " << pdu.rnti << endl;
    }
}

void handle_crc_indications(const vector<NFAPI_CRC_INDICATION_PDU_T>& pdus) {
    // Handle a list of CRC indication PDUs by adding or removing them from the octree
    for (auto& pdu : pdus) {
        if (octree.add(pdu)) {
            cout << "Added new CRC indication PDU with RNTI: " << pdu.rnti << endl;
        } else if (octree.remove(pdu)) {
            cout << "Removed CRC indication PDU with RNTI: " << pdu.rnti << endl;
        } else {
            // Handle memory allocation failures gracefully by returning -1
            cout << "Failed to add or remove CRC indication PDU with RNTI: " << pdu.rnti << endl;
        }
    }
}
