    RESTAPIGateway restapi_gateway;

    // Caching layer for validated tokens
    map<string, Timestamp> token_cache;

    // Logging system for debugging and monitoring
    LoggingSystem logging_system;

public:
    ImageLibrary() {
        // Initialize format handlers for supported image formats
        format_handlers["jpeg"] = [this](const string& filepath) {
