namespace DataRecoveryService
{
    public class DecryptAndDeserializeData
    {
        private readonly ILogger<DecryptAndDeserializeData> _logger;
        private readonly IDistributedCache _distributedCache;
        private readonly EncryptionApiClient _encryptionApiClient;

        public DecryptAndDeserializeData(ILogger<DecryptAndDeserializeData> logger, IDistributedCache distributedCache, EncryptionApiClient encryptionApiClient)
        {
            _logger = logger;
            _distributedCache = distributedCache;
            _encryptionApiClient = encryptionApiClient;
        }

        public async Task<T> DecryptAndDeserializeDataAsync<T>(List<Dictionary<string, object>> metadataList)
        {
            try
            {
                var decryptedData = new List<byte[]>();
                foreach (var metadata in metadataList)
                {
                    var url = (string)metadata["Url"];
                    var key = (string)metadata["Key"];
                    var iv = (string)metadata["Iv"];
                    var data = await _encryptionApiClient.GetAsync(url);
                    if (data == null || data.Length == 0)
                    {
                        continue;
                    }
                    var decryptedData = AesCbcDecrypt(key, iv, data);
                    decryptedDataList.Add(decryptedData);
                }
                var deserializedData = Deserialize<T>(decryptedData);
                return deserializedData;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to decrypt and deserialize data");
                throw;
            }
        }

        private byte[] AesCbcDecrypt(string key, string iv, byte[] data)
        {
            var encryptionKey = Convert.FromBase64String(key);
            var initializationVector = Convert.FromBase64String(iv);
            using (var aesAlgorithm = new AesCbcMode(encryptionKey))
            {
                return aesAlgorithm.Decrypt(data, initializationVector);
            }
        }

        private T Deserialize<T>(byte[] data)
        {
            try
            {
                return JsonConvert.DeserializeObject<T>(Encoding.UTF8.GetString(data));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to deserialize data");
                throw;
            }
        }
    }
}
