int generateNfaApiCrcList(char *buffer, size_t size) {
    // Check if the buffer is large enough to hold the list of CRCs
    if (size < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1;
    }

    // Initialize a random number generator
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *crcList = (NFAPI_CRC_INDICATION_PDU_T *)buffer;
    for (int i = 0; i < size / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        // Generate a random RX_UE_INFORMATION_TAG
        crcList[i].RX_UE_INFORMATION_TAG = rand();

        // Generate a random RNTI
        crcList[i].RNTI = rand();

        // Generate a random CRC_INDICATION_REL8_TAG
        crcList[i].CRC_INDICATION_REL8_TAG = rand();

        // Set the CRCFLAG to 0
        crcList[i].CRCFLAG = 0;
    }

    return size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
}
