function uploadFile(url, file) {
  // Step 1: File validation and size limit checking
  const allowedMimeTypes = ['image/jpeg', 'image/png'];
  const maxFileSize = 50 * 1024 * 1024; // 50 MB
  if (!file.type || !allowedMimeTypes.includes(file.type)) {
    throw new Error(`Unsupported file type: ${file.type}`);
  } else if (file.size > maxFileSize) {
    throw new Error(`Maximum allowed file size is ${maxFileSize} bytes.`);
  }

  // Step 2: System integration and data transfer
  const storageService = createStorageService();
  const analyticsService = createAnalyticsService();
  const cdn = createCDN();

  return storageService.upload(file).then((storageResult) => {
    // Step 3: Performance optimization and error handling
    if (storageResult.success) {
      return cdn.cacheFile(storageResult.fileUrl);
    } else {
      throw new Error(`Failed to upload file: ${storageResult.error}`);
    }
  }).catch((uploadError) => {
    // Step 4: Data persistence and resource management
    storageService.deleteFile(storageResult.fileUrl);
    throw new Error(`Failed to cache file in CDN: ${uploadError}`);
  }).finally(() => {
    analyticsService.trackUploadEvent({ fileSize: file.size });
  });
}
