// Buffer management and memory optimization
import java.util.HashMap;
import java.util.Map;

public class BufferManager {
    private static final int MIN_BUFFER_SIZE = 1024 * 1024; // 1 MB
    private static final int MAX_BUFFER_SIZE = 1024 * 1024 * 50; // 50 MB
    private static final int BUFFER_RESIZE_THRESHOLD = 80; // percentage of buffer capacity to be reached before resizing

    private Map<String, byte[]> buffers = new HashMap<>();

    public synchronized void addBuffer(String key, byte[] data) {
        if (buffers.containsKey(key)) {
            throw new IllegalStateException("Buffer already exists");
        }
        buffers.put(key, data);
    }

    public synchronized void removeBuffer(String key) {
        if (!buffers.containsKey(key)) {
            throw new IllegalArgumentException("No buffer with given key found");
        }
        buffers.remove(key);
    }

    public synchronized byte[] getBuffer(String key) {
        return buffers.get(key);
    }

    private void resizeBuffer(String key, int newSize) {
        byte[] buffer = buffers.get(key);
        if (buffer == null) {
            throw new IllegalArgumentException("No buffer with given key found");
        }
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(buffer, 0, newBuffer, 0, Math.min(buffer.length, newSize));
        buffers.put(key, newBuffer);
    }

    public synchronized void updateBuffer(String key, int newSize) {
        if (newSize < MIN_BUFFER_SIZE || newSize > MAX_BUFFER_SIZE) {
            throw new IllegalArgumentException("Invalid buffer size");
        }
        resizeBuffer(key, newSize);
    }
}

