int cipher_init(struct kms_client *kms) {
    if (check_key_size(kms->key_size)) {
        // Initialize cipher context
        struct cipher_context *ctx = calloc(1, sizeof(struct cipher_context));
        ctx->request_id = 0;
        ctx->key = kms_generate_key(kms);
        ctx->iv = calloc(IV_SIZE, sizeof(uint8_t));
        return ctx;
