        response->request_id = 0;
        response->status = KMS_SUCCESS;
        response->key = NULL;
        response->iv = NULL;
        return response;
    } else {
        // Log error message and return failure
        printf("Error: Unknown algorithm %s\n", kms->algorithm);
        return -1;
    }
}

int cipher_encrypt(struct cipher_context *ctx, uint8_t *plaintext, size_t plaintext_len, uint8_t **ciphertext) {
    if (check_key_size(ctx->key->key_size)) {
        // Generate initialization vector for encryption/decryption
        ctx->iv = calloc(IV_SIZE, sizeof(uint8_t));

        // Encrypt plaintext data using the KMS client
        struct kms_request request;
        request.request_id = 0;
        request.key_name = "AES-GCM";
        request.iv = ctx->iv;
        request.mode = MODE;
        struct kms_response *response = kms_request(&request);

        // Check if the KMS response was successful
        if (response->status == KMS_SUCCESS) {
            uint8_t *key = malloc(KEY_BLOCK_SIZE);
            memcpy(key, ctx->key->key_data, KEY_BLOCK_SIZE);
            *ciphertext = encrypt(plaintext, plaintext_len, key, IV_SIZE);
        } else {
            // Log error message and return failure
            printf("Error: KMS request failed with status %d\n", response->status);
            free(*ciphertext);
            return -1;
        }
    } else {
        // Log error message and return failure
        printf("Error: Invalid key size %lu\n", ctx->key->key_size);
        return -1;
    }
}

int cipher_decrypt(struct cipher_context *ctx, uint8_t *ciphertext, size_t ciphertext_len, uint8_t **plaintext) {
    if (check_key_size(ctx->key->key_size)) {
        // Decrypt ciphertext data using the KMS client
        struct kms_request request;
        request.request_id = 0;
        request.key_name = "AES-GCM";
        request.iv = ctx->iv;
        request.mode = MODE;
