        // Check if the KMS response was successful
        if (response->status == KMS_SUCCESS) {
            uint8_t *key = malloc(KEY_BLOCK_SIZE);
            memcpy(key, ctx->key->key_data, KEY_BLOCK_SIZE);
            *plaintext = decrypt(ciphertext, ciphertext_len, key, IV_SIZE);
        } else {
            // Log error message and return failure
            printf("Error: KMS request failed with status %d\n", response->status);
            free(*plaintext);
            return -1;
        }
    } else {
        // Log error message and return failure
        printf("Error: Invalid key size %lu\n", ctx->key->key_size);
        return -1;
    }
}

