        url = f"https://api.openweathermap.org/data/2.5/weather?q={location}&appid={self.api_key}"
        response = requests.get(url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Error retrieving weather data")

class MedianService:
    def __init__(self, sensors: List[Sensor], weather_api: WeatherAPI):
        self.sensors = sensors
        self.weather_api = weather_api

    def compute_median(self) -> None:
        # Sort sensor values and compute median
        for sensor in self.sensors:
            sensor.values.sort()
            sensor.median = sensor.values[len(sensor.values) // 2]

        # Fetch weather conditions for each sensor location
        for sensor in self.sensors:
            try:
                response = self.weather_api.get_weather(sensor.location)
                sensor.current_weather = response["weather"][0]["main"]
            except Exception as e:
                logging.warning(f"Error retrieving weather data for sensor {sensor.id}: {e}")

    def output_results(self) -> List[Dict[str, any]]:
        results = []
        for sensor in self.sensors:
            result = {
                "sensor_id": sensor.id,
                "median": sensor.median,
                "total_processing_time": perf_counter() - sensor.last_update,
                "weather": sensor.current_weather,
            }
            results.append(result)
        return results

# Main function
def main():
    # Initialize sensors and weather API
    sensors = [Sensor("sensor1", "New York"), Sensor("sensor2", "London"), Sensor("sensor3", "Paris")]
    weather_api = WeatherAPI("YOUR_OPENWEATHERMAP_API_KEY")

    # Create MedianService instance
    median_service = MedianService(sensors, weather_api)

    # Start computing median and fetching weather conditions
    median_service.compute_median()

    # Output results as JSON array
    print(json.dumps(median_service.output_results()))

# Driver code
if __name__ == "__main__":
    main()']

