  char *dataBuffer;
};

// Define a struct to represent a collection of image structures
struct TIFFImageCollection {
  // Array of image structures
  struct TIFFImage *images;

  // Size of the array
  unsigned int size;

  // Number of images in the collection
  unsigned int numImages;
};

// Define a function to initialize the library with valid RRC UE ID, LCg ID, and PDCP SN values
void initTIFFImageAnalyzer(unsigned int rrcUeId, unsigned int lcgId, unsigned short pdcpSn) {
  // Initialize the struct for the collection of image structures
  struct TIFFImageCollection *imageCollection = malloc(sizeof(struct TIFFImageCollection));

  // Allocate memory for the array of image structures
  imageCollection->images = malloc(sizeof(struct TIFFImage) * MAX_NUM_IMAGES);

  // Set the size and number of images in the collection to zero
  imageCollection->size = 0;
  imageCollection->numImages = 0;

  // Store the RRC UE ID, LCg ID, and PDCP SN values in a global variable for reference
  rrcUeId_ = rrcUeId;
  lcgId_ = lcgId;
  pdcpSn_ = pdcpSn;
}

// Define a function to add an image structure to the collection
void addImage(struct TIFFImage *image) {
  // Check if the struct is valid
  if (image == NULL || image->dataBuffer == NULL) {
    return;
  }

  // Increment the size of the array by one and reallocate memory if necessary
  imageCollection->size++;
  if (imageCollection->size > imageCollection->numImages) {
    imageCollection->images = realloc(imageCollection->images, sizeof(struct TIFFImage) * imageCollection->size);
  }

  // Copy the image structure to the array and update the number of images in the collection
  memcpy(&(imageCollection->images[imageCollection->numImages]), image, sizeof(struct TIFFImage));
  imageCollection->numImages++;
}

// Define a function to remove an image structure from the collection by its RRC UE ID and LCg ID
void removeImage(unsigned int rrcUeId, unsigned int lcgId) {
  // Check if the struct is valid
  if (rrcUeId == 0 || lcgId == 0) {
    return;
  }

  // Iterate through the array and find the image structure with the matching RRC UE ID and LCg ID
  for (unsigned int i = 0; i < imageCollection->numImages; i++) {
    if (imageCollection->images[i].rrcUeId == rrcUeId && imageCollection->images[i].lcgId == lcgId) {
      // Reallocate memory and decrement the number of images in the collection
      imageCollection->size--;
      imageCollection->numImages--;

      // Copy the last element to the removed index and update the size of the array
      memcpy(&(imageCollection->images[i]), &(imageCollection->images[imageCollection->numImages]), sizeof(struct TIFFImage));
      imageCollection->size--;

      // Free the memory for the removed structure
      free(imageCollection->images[imageCollection->numImages]);
      break;
    }
  }
}

// Define a function to get an image structure from the collection by its RRC UE ID and LCg ID
