  // Check if the struct is valid
  if (rrcUeId == 0 || lcgId == 0) {
    return NULL;
  }

  // Iterate through the array and find the image structure with the matching RRC UE ID and LCg ID
  for (unsigned int i = 0; i < imageCollection->numImages; i++) {
    if (imageCollection->images[i].rrcUeId == rrcUeId && imageCollection->images[i].lcgId == lcgId) {
      return &(imageCollection->images[i]);
    }
