    void addPacket(std::string sourceIP, std::string destIP) {
        NetworkPacket packet;
        packet.sourceIP = sourceIP;
        packet.destIP = destIP;
        packet.subnetID = subnetID_;
        packet.isDuplicate = false;

        // Check if the packet is a duplicate by comparing the source and destination IPs
        for (auto& it : packets_) {
            if (it.sourceIP == sourceIP && it.destIP == destIP) {
                it.isDuplicate = true;
                break;
            }
        }

        // Add the packet to the collection and increment the packet counter
        packets_.push_back(packet);
        ++numPackets_;
