  /* Calculate the size of the memory block to allocate */
  size_t mem_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus;

  /* Allocate memory for the CRC indication PDUs */
  NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(mem_size);
  if (pdu_array == NULL) {
