  populate_crc_flag(&pdu->crc_indication_rel8.crc_flag, num_pdus);

  /* Return success */
  return 0;
}

/* Function to populate the indication tag in a CRC indication PDU */
static void populate_indication_tag(NFAPI_CRC_INDICATION_TAG_T *tag, const char *rx_ue_information) {
  /* Initialize the RX UE information tag */
  tag->rx_ue_information = rx_ue_information;
}

/* Function to populate the RNTI in a CRC indication PDU */
static void populate_rnti(NFAPI_CRC_INDICATION_RNTI_T *rnti, uint32_t num_pdus) {
  /* Generate a random RNTI value */
  rnti->value = (rand() % (MAX_RNTI - MIN_RNTI)) + MIN_RNTI;
}

/* Function to populate the CRC indication REL8 tag in a CRC indication PDU */
static void populate_crc_indication_rel8_tag(NFAPI_CRC_INDICATION_REL8_TAG_T *tag, const char *rx_ue_information) {
  /* Initialize the CRC indication REL8 tag */
  tag->rx_ue_information = rx_ue_information;
}

/* Function to populate the CRCFlag in a CRC indication PDU */
static void populate_crc_flag(uint32_t *crc_flag, uint32_t num_pdus) {
  /* Generate a random CRCFlag value */
  crc_flag->value = (rand() % (MAX_CRCFLAG - MIN_CRCFLAG)) + MIN_CRCFLAG;
}

/* Function to call the NMS API and send the CRC indication PDUs */
void send_crc_indications(const char *rx_ue_information) {
  /* Initialize the number of CRC indications to populate */
  uint32_t num_pdus = 0;

  /* Populate the CRC indication PDUs */
  populate_crc_indications(rx_ue_information, &num_pdus);

  /* Call the NMS API to send the CRC indications */
  nms_api_send_crc_indications(pdu_array, num_pdus);
}
