```c
#include <stdlib.h> // for malloc() and free()
#include <string.h> // for memset()
#include <openssl/aes.h> // for AES encryption

// function to encrypt data using AES
void aesEncrypt(char *plaintext, char **ciphertext, int key_size) {
    // allocate memory for the ciphertext
    int plaintext_len = strlen(plaintext);
    *ciphertext = (char *)malloc(sizeof(char) * (plaintext_len + AES_BLOCK_SIZE));
    if (!*ciphertext) {
        return;
    }

    // initialize the encryption key and IV
    unsigned char key[AES_KEY_LENGTH];
    unsigned char iv[AES_IV_LENGTH];
    memset(key, 0, AES_KEY_LENGTH);
    memset(iv, 0, AES_IV_LENGTH);

    // encrypt the plaintext using AES-GCM
    int ciphertext_len;
    if (EVP_EncryptUpdate(ctx, *ciphertext, &ciphertext_len, plaintext, plaintext_len) <= 0) {
        free(*ciphertext);
        return;
    }

    // set the encryption key and IV
    EVP_CIPHER_CTX_set_key(ctx, key, AES_KEY_LENGTH * 8);
    EVP_CIPHER_CTX_set_iv(ctx, iv, AES_IV_LENGTH);

    // encrypt the plaintext using AES-GCM
    if (EVP_EncryptUpdate(ctx, *ciphertext + ciphertext_len, &ciphertext_len, plaintext + plaintext_len, strlen(plaintext) - plaintext_len) <= 0) {
        free(*ciphertext);
        return;
    }

    // set the encryption key and IV back to NULL
    EVP_CIPHER_CTX_set_key(ctx, NULL, AES_KEY_LENGTH * 8);
    EVP_CIPHER_CTX_set_iv(ctx, NULL, AES_IV_LENGTH);

    // return the ciphertext length
    return ciphertext_len;
}
