// Define a function for generating an NFAPI_CRC_LIST_T structure
NFAPI_CRC_LIST_T generateNfaApiCrcList() {
    // Initialize the list with a default capacity
    NFAPI_CRC_LIST_T list = {NULL, 0, 0};

    // Dynamically allocate memory for the array
