// Define a function for dynamically resizing the NFAPI_CRC_LIST_T structure
void resizeNfaApiCrcList(NFAPI_CRC_LIST_T *list) {
    // Check if the current capacity of the list is less than the desired capacity
    if (list->capacity < list->length) {
