        printf("Error: invalid values\n");
        return false;
    }

    // Check if the new transmission unit already exists in the collection
    for (int i = 0; i < MAX_PDUS; i++) {
        if (images[i].rrc_ue_id == rrc_ue_id && images[i].lcg_id == lcg_id && images[i].pdcp_sn == pdcp_sn) {
            printf("Error: duplicate transmission unit found\n");
            return false;
        }
    }

    // Add the new transmission unit to the collection
    int index = 0;
    while (index < MAX_PDUS && images[index].rrc_ue_id != 0) {
        index++;
    }
    if (index == MAX_PDUS) {
        printf("Error: maximum number of transmission units reached\n");
        return false;
    }
    images[index].rrc_ue_id = rrc_ue_id;
    images[index].lcg_id = lcg_id;
    images[index].pdcp_sn = pdcp_sn;

    // Release the mutex protecting concurrent access to the collection of transmission units
    pthread_mutex_unlock(&image_lock);

    return true;
}

