        self.time_point = time_point
        self.event_severity = event_severity
        self.sensor_readings = sensor_readings

    def __repr__(self) -> str:
        return f"NetworkEvent(time_point={self.time_point}, event_severity={self.event_severity}, sensor_readings={self.sensor_readings})"

class SensorReading:
    def __init__(self, id: int, value: float) -> None:
        self.id = id
        self.value = value

    def __repr__(self) -> str:
        return f"SensorReading(id={self.id}, value={self.value})"

class NetworkEventList:
    def __init__(self, events: List[NetworkEvent]) -> None:
        self.events = events

    def __repr__(self) -> str:
        return f"NetworkEventList(events={self.events})"

def get_network_event_list(file_path: str) -> NetworkEventList:
    with open(file_path, "r") as file:
        events = []
        for line in file:
            time_point, event_severity, sensor_readings = line.split(", ")
            events.append(NetworkEvent(time_point=int(time_point), event_severity=int(event_severity), sensor_readings=[SensorReading(id=int(sensor_reading_id), value=float(sensor_reading_value)) for sensor_reading_id, sensor_reading_value in [pair.split("=") for pair in sensor_readings.split(" ")]]))
        return NetworkEventList(events=events)

if __name__ == "__main__":
    file_path = "network_event_list.csv"
    network_event_list = get_network_event_list(file_path)
