```scss
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
const statAsync = promisify(fs.stat);
const unlinkAsync = promisify(fs.unlink);

class ModuleLoader {
  constructor() {
    this.modules = {};
    this.eventTypes = {};
    this.fileCache = new Map();
  }

  async loadModule(modulePath) {
    const moduleName = path.basename(modulePath, '.js');
    if (this.modules[moduleName]) {
      return this.modules[moduleName];
    }

    const fileContents = await readFileAsync(modulePath);
    const moduleCode = `(${fileContents})();`;
    const module = eval(moduleCode);
    this.modules[moduleName] = module;
    return module;
  }

  async unloadModule(moduleName) {
    if (this.modules[moduleName]) {
      delete this.modules[moduleName];
    }
    await unlinkAsync(`${modulePath}/${moduleName}.js`);
  }

  async getModule(moduleName) {
    const module = this.modules[moduleName];
    if (module) {
      return module;
    }
    const modulePath = `${this.baseDir}/${moduleName}.js`;
    await this.loadModule(modulePath);
    return this.modules[moduleName];
  }

  async getEventType(eventTypeName) {
    if (this.eventTypes[eventTypeName]) {
      return this.eventTypes[eventTypeName];
    }
    const module = await this.getModule('event-type-registry');
    const eventType = module[eventTypeName];
    if (!eventType) {
      throw new Error(`Event type ${eventTypeName} not found in registry`);
    }
    this.eventTypes[eventTypeName] = eventType;
    return eventType;
  }

  async generateEvents(eventTypeName, count, interval = 100) {
    const eventType = await this.getEventType(eventTypeName);
    for (let i = 0; i < count; i++) {
      setTimeout(() => {
        this.emit(eventType());
      }, i * interval);
    }
  }

  async emit(event) {
    const listeners = this.listeners(event.type);
    for (const listener of listeners) {
      try {
        await listener(event);
      } catch (error) {
        console.error(`Error handling event: ${error}`);
      }
    }
  }

  on(eventType, handler) {
    this.listeners[eventType] = this.listeners[eventType] || [];
    this.listeners[eventType].push(handler);
  }

  off(eventType, handler) {
    const listeners = this.listeners[eventType];
    if (!listeners) {
      return;
    }
    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i] === handler) {
        listeners.splice(i, 1);
        break;
      }
    }
  }
}
```
