#include <pthread.h>
#include <curl/curl.h>

#define MAX_NFAPI_CRC_INDICATION_PDU 10000
#define MAX_RNTI 256
#define MAX_CRC_INDICATION_REL8_TAG 256
#define MIN_BACKOFF_DELAY 10 // in milliseconds
#define MAX_BACKOFF_DELAY 30 // in milliseconds
#define BACKOFF_EXPONENTIAL 2
#define BACKOFF_MAX_RETRIES 5
#define MIN_CONNECTIVITY_THRESHOLD 10 // in percent
#define MAX_CONNECTIVITY_THRESHOLD 90 // in percent
#define DURABLE_STORAGE_DELAY 30 // in seconds
#define RESOURCE_ALLOCATION_GRANULARITY 5 // in number of worker threads

struct NFAPI_CRC_INDICATION_PDU {
    unsigned char RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
};

static size_t write_memory(void *ptr, size_t size, size_t nmemb, void *stream) {
    return size * nmemb;
}

void generate_NFAPI_CRC_INDICATION_PDUs() {
    struct NFAPI_CRC_INDICATION_PDU* pdu = (struct NFAPI_CRC_INDICATION_PDU*) malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU) * MAX_NFAPI_CRC_INDICATION_PDU);
    unsigned char RX_UE_INFORMATION_TAG = 0;
    unsigned int RNTI = 0;
    unsigned char CRC_INDICATION_REL8_TAG = 0;
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU; ++i) {
        pdu[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG++;
        pdu[i].RNTI = RNTI++;
        if (RNTI > MAX_RNTI) {
            RNTI = 0;
        }
        pdu[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG++;
        if (CRC_INDICATION_REL8_TAG > MAX_CRC_INDICATION_REL8_TAG) {
            CRC_INDICATION_REL8_TAG = 0;
        }
    }
}

