        printf("Error initializing hash algorithm or public key\n");
        ret = -1;
    } else {
        // Set the message digest algorithm to SHA-256
        EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);

        // Update the hash context with the plaintext message
        outlen = plaintext_size;
        ret = EVP_DigestUpdate(ctx, plaintext, outlen);
        if (ret != 1) {
            printf("Error updating hash context\n");
            ret = -1;
        } else {
            // Finalize the hash calculation and retrieve the digest value
            ret = EVP_DigestFinal_ex(ctx, digest, &outlen);
            if (ret != 1) {
                printf("Error finalizing hash calculation\n");
                ret = -1;
            } else {
                // Verify the authenticity of the message using the public key
                ret = RSA_verify(NID_sha256, digest, outlen, (unsigned char *)hash, hash_size, rsa);
