    return -1;
  }
  // Copy the measurement data into the new node
  memcpy(new_node->data, measurement, sizeof(LTE_UeMeasurement));
  // Add the new node to the end of the measurements linked list
  MeasurementNode *current = measurements;
  while (current->next != NULL) {
    current = current->next;
