    if (rc != 0) {
        fprintf(stderr, "Failed to initialize mutex for DNS cache\n");
        return NULL;
    }
    dns_cache->num_entries = 0;

    // Allocate memory for the DNS cache entries
    dns_cache->entries = (DNS_CACHE_ENTRY*) malloc(MAX_CACHE_ENTRIES * sizeof(DNS_CACHE_ENTRY));
    if (!dns_cache->entries) {
        fprintf(stderr, "Failed to allocate memory for DNS cache entries\n");
        return NULL;
    }

    // Initialize the DNS cache entries to empty strings and zero IP addresses
