        memset(&dns_cache->entries[i].ipv6_address, 0, sizeof(struct in6_addr));
    }

    return dns_cache;
}

// Adds a DNS cache entry for the given hostname and IP address.
int add_dns_cache_entry(DNS_CACHE* dns_cache, const char* hostname, struct in6_addr ipv6_address) {
    if (!dns_cache || !hostname || !ipv6_address) {
        fprintf(stderr, "Invalid input parameters for add_dns_cache_entry\n");
        return -1;
