    // Lock the mutex to prevent concurrent access to the DNS cache
    int rc = pthread_mutex_lock(&dns_cache->lock);
    if (rc != 0) {
        fprintf(stderr, "Failed to lock mutex for DNS cache\n");
        return -1;
    }

    // Check if the hostname is already in the cache
    int i;
    for (i = 0; i < dns_cache->num_entries; i++) {
        if (!strcmp(dns_cache->entries[i].hostname, hostname)) {
            // If the entry already exists, update its IP address and return
            memcpy(&dns_cache->entries[i].ipv6_address, &ipv6_address, sizeof(struct in6_addr));
            dns_cache->entries[i].last_used = time(NULL);
