    // If the hostname is not in the cache, add a new entry
    if (dns_cache->num_entries < MAX_CACHE_ENTRIES) {
        strncpy(dns_cache->entries[i].hostname, hostname, MAX_HOSTNAME_LEN);
        memcpy(&dns_cache->entries[i].ipv6_address, &ipv6_address, sizeof(struct in6_addr));
        dns_cache->num_entries++;
    } else {
        fprintf(stderr, "DNS cache is full, cannot add new entry\n");
