        return -1;
    }

    // Get output length and free context
    int out_len = len + EVP_CIPHER_CTX_block_size(ctx);
    EVP_CIPHER_CTX_free(ctx);

    return out_len;
}

int decrypt(const unsigned char *ciphertext, const size_t ciphertext_len, const key_t *key, unsigned char *plaintext, size_t plaintext_len) {
    EVP_CIPHER_CTX *ctx;
    int len;

    if ((ctx = EVP_CIPHER_CTX_new()) == NULL) {
        return -1;
    }

    // Set cipher type and mode
    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Set padding
    EVP_CIPHER_CTX_set_padding(ctx, 0);

    // Decrypt ciphertext
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Set finalize flag
    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Get output length and free context
    int out_len = len + EVP_CIPHER_CTX_block_size(ctx);
    EVP_CIPHER_CTX_free(ctx);

    return out_len;
}

int key_management(const unsigned char *data, const size_t data_len, unsigned char *key) {
    int i = get_random_key();

    // Copy key from array
    memcpy(key, keys[i].key, AES_BLOCK_SIZE);

    return 0;
}

int main() {
    unsigned char plaintext[16] = "Hello World!";
    size_t plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[16];
    size_t ciphertext_len;
    unsigned char key[AES_BLOCK_SIZE];
    int ret;

    // Generate random key and encrypt plaintext
    key_management(plaintext, plaintext_len, key);
    if ((ret = encrypt(plaintext, plaintext_len, key, ciphertext, &ciphertext_len)) < 0) {
        printf("Encryption failed\n");
        return -1;
    }

    // Decrypt ciphertext and verify result
    if ((ret = decrypt(ciphertext, ciphertext_len, key, plaintext, &plaintext_len)) < 0) {
        printf("Decryption failed\n");
        return -1;
    }

    // Print plaintext and ciphertext
    printf("Plaintext: %s\n", (char *)plaintext);
    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; ++i) {
        printf("%02x ", ciphertext[i]);
    }
    printf("\n");

    return 0;
}
```

