#include <openssl/des.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/bio.h>
#include <openssl/buffer.h>
#include <openssl/err.h>

/* Command-line arguments */
char* input_file;
char* output_file;
int cipher_mode;
int block_size;

/* Global variables */
unsigned char key[8];
unsigned char iv[8];
EVP_CIPHER_CTX *ctx;
BIO *in, *out;
pthread_mutex_t lock;

/* Function prototypes */
void init_openssl(void);
void cleanup(void);
int encrypt_cbc(unsigned char *buf, int size);
int decrypt_cbc(unsigned char *buf, int size);
int encrypt_cfb(unsigned char *buf, int size);
int decrypt_cfb(unsigned char *buf, int size);
void print_usage(void);

/* Main function */
int main(int argc, char* argv[]) {
  /* Parse command-line arguments and configure the application */
  if (argc != 6) {
    print_usage();
    return 1;
  }
  input_file = argv[1];
  output_file = argv[2];
  cipher_mode = atoi(argv[3]);
  block_size = atoi(argv[4]);

  /* Initialize OpenSSL and create BIOs for reading/writing to files */
  init_openssl();
  in = BIO_new(BIO_s_file());
  out = BIO_new(BIO_s_file());

  /* Set key and initialization vector */
  RAND_bytes(key, sizeof(key));
  RAND_bytes(iv, sizeof(iv));

  /* Initialize the cipher context with the selected mode and key */
  ctx = EVP_CIPHER_CTX_new();
  EVP_EncryptInit_ex(ctx, EVP_des_cbc(), NULL, key, iv);

  /* Process data in chunks */
  unsigned char* buf = malloc(block_size * sizeof(unsigned char));
  int size = read(fileno(in), buf, block_size);
  while (size > 0) {
    switch (cipher_mode) {
      case ECB: encrypt_cbc(buf, size); break;
      case EDE: encrypt_cfb(buf, size); break;
      case EDE3: encrypt_cfb(buf, size); break;
      default: printf("Invalid cipher mode\n"); return 1;
    }
    size = read(fileno(in), buf, block_size);
  }

  /* Cleanup and exit */
  cleanup();
  return 0;
}

/* Initialize OpenSSL */
void init_openssl(void) {
  ERR_load_crypto_strings();
  OpenSSL_add_all_algorithms();
}

/* Cleanup function to release resources */
void cleanup(void) {
  EVP_CIPHER_CTX_free(ctx);
  BIO_free(in);
  BIO_free(out);
  ERR_free_strings();
}

/* Encrypt using CBC mode */
int encrypt_cbc(unsigned char *buf, int size) {
  EVP_EncryptUpdate(ctx, buf, &size, buf, size);
  return size;
}

/* Decrypt using CBC mode */
int decrypt_cbc(unsigned char *buf, int size) {
  EVP_DecryptUpdate(ctx, buf, &size, buf, size);
  return size;
}

/* Encrypt using CFB mode */
int encrypt_cfb(unsigned char *buf, int size) {
  EVP_EncryptUpdate(ctx, buf, &size, buf, size);
  return size;
}

/* Decrypt using CFB mode */
int decrypt_cfb(unsigned char *buf, int size) {
  EVP_DecryptUpdate(ctx, buf, &size, buf, size);
  return size;
}

/* Print usage information */
void print_usage(void) {
  printf("Usage: crypt [input file] [output file] [cipher mode] [block size]\n");
}']

