    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->pdu_length = length;
    pdu->pdu = (uint8_t*)malloc(length);
    memcpy(pdu->pdu, data, length);
    return pdu;
}

void destroy_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    free(pdu->pdu);
    free(pdu);
}

int main() {
    // Create a CRC indication PDU with a length of 10 and some sample data.
    const uint8_t* data = (const uint8_t*)malloc(10);
    memset(data, 0xAB, 10);
    NFAPI_CRC_INDICATION_PDU_T* pdu = create_crc_indication_pdu(10, data);

    // Print the PDU.
    printf("CRC Indication PDU:\n");
    printf("  Length: %d\n", pdu->pdu_length);
    printf("  Data: ");
    for (int i = 0; i < pdu->pdu_length; i++) {
        printf("%02x ", pdu->pdu[i]);
    }
    printf("\n");

    // Destroy the PDU.
    destroy_crc_indication_pdu(pdu);
    free((void*)data);
