import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CloudServiceClient {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final int requestTimeout = 5000; // 5 seconds
    private final String[] serviceEndpoints = {"https://service1.com", "https://service2.com"};
    private final Map<String, ServiceInstance> serviceInstances = new HashMap<>();

    public CloudServiceClient(Configuration configuration) {
        this.configuration = configuration;
        for (String endpoint : serviceEndpoints) {
            ServiceInstance instance = new ServiceInstance(endpoint);
            serviceInstances.put(instance.getEndpoint(), instance);
        }
    }

    public void sendRequest(String request, String endpoint) throws InterruptedException, ExecutionException {
        ServiceInstance instance = serviceInstances.get(endpoint);
        if (instance == null) {
            throw new IllegalArgumentException("Invalid endpoint: " + endpoint);
        }
        Future<Response> responseFuture = executor.submit(() -> sendRequestInternal(request, instance));
        try {
            Response response = responseFuture.get(requestTimeout, TimeUnit.MILLISECONDS);
            return response;
        } catch (TimeoutException e) {
            throw new InterruptedException("Request timed out");
        } catch (ExecutionException e) {
            throw new RuntimeException("Error executing request", e);
        } finally {
            executor.shutdown();
        }
    }

    private Response sendRequestInternal(String request, ServiceInstance instance) throws IOException {
        URL url = new URL(instance.getEndpoint() + "/api/v1/send");
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("POST");
        connection.setDoOutput(true);
        connection.connect();
        OutputStreamWriter writer = new OutputStreamWriter(connection.getOutputStream());
        writer.write(request);
        writer.flush();
        int statusCode = connection.getResponseCode();
        if (statusCode == 200) {
            InputStreamReader reader = new InputStreamReader(connection.getInputStream());
            Response response = gson.fromJson(reader, Response.class);
            return response;
        } else {
            throw new IOException("Error executing request");
        }
    }

    private class ServiceInstance {
        private String endpoint;
        private String apiKey;

        public ServiceInstance(String endpoint) {
            this.endpoint = endpoint;
            this.apiKey = getApiKey();
        }

        public String getEndpoint() {
            return endpoint;
        }

        public String getApiKey() {
            // Load the API key from a secure storage (e.g., AWS Secrets Manager)
            return "YOUR_API_KEY";
        }
    }
}
```
