  public void scaleUp() {
    if (parallelism < maxParallelism) {
      parallelism++;
      executor.setMaximumPoolSize(parallelism);
    }
  }

  public void scaleDown() {
    if (parallelism > minParallelism) {
      parallelism--;
      executor.setCorePoolSize(parallelism);
    }
  }

