// Circuit breaker state
bool circuit_breaker_open = false;
int circuit_breaker_count = 0;

// Queue for pending operations
struct queue {
    nfapi_crc_indication_pdu_t *crc_indications[MAX_UE_INSTANCES];
    int front;
    int rear;
};

// Create a new database connection and initialize the circuit breaker state
void init_db(void) {
    // Connect to the MySQL server
    mysql_conn = mysql_init(NULL);
    if (!mysql_real_connect(mysql_conn, DB_HOST, DB_USER, DB_PASSWORD, DB_NAME, 0, NULL, 0)) {
        fprintf(stderr, "Failed to connect to MySQL: %s\n", mysql_error(mysql_conn));
        exit(EXIT_FAILURE);
    }

    // Initialize the circuit breaker state
    circuit_breaker_open = false;
    circuit_breaker_count = 0;
}

// Close the database connection and release resources
void close_db(void) {
    if (mysql_conn != NULL) {
        mysql_close(mysql_conn);
    }
}

// Add a new CRC indication to the queue for processing
void add_to_queue(nfapi_crc_indication_pdu_t *crc_indication) {
    // Check if the circuit breaker is open
    if (circuit_breaker_open) {
        return;
    }

    // Add the CRC indication to the queue
    struct queue *queue = (struct queue *)malloc(sizeof(struct queue));
    if (queue == NULL) {
        fprintf(stderr, "Failed to allocate memory for the queue\n");
        return;
    }
    queue->front = 0;
    queue->rear = MAX_UE_INSTANCES - 1;
    queue->crc_indications[queue->rear] = crc_indication;
    pthread_mutex_lock(&queue_mutex);
    if (queue_head == NULL) {
        queue_head = queue;
    } else {
        queue_tail->next = queue;
    }
    queue_tail = queue;
    pthread_mutex_unlock(&queue_mutex);
}

// Process a single CRC indication from the queue
void process_crc_indication(nfapi_crc_indication_pdu_t *crc_indication) {
    // Check if the database connection is valid
    if (mysql_conn == NULL || mysql_real_connect(mysql_conn, DB_HOST, DB_USER, DB_PASSWORD, DB_NAME, 0, NULL, 0)) {
        fprintf(stderr, "Failed to connect to MySQL: %s\n", mysql_error(mysql_conn));
        return;
    }

    // Check if the CRC indication is valid
    if (crc_indication == NULL || crc_indication->rx_ue_information_tag == 0) {
        fprintf(stderr, "Invalid CRC indication\n");
        return;
    }

    // Check if the UE instance exists in the database
    uint64_t rx_ue_information_tag = crc_indication->rx_ue_information_tag;
    uint32_t rnti = crc_indication->rnti;
    char *query = malloc(sizeof(char) * 1024);
    sprintf(query, "SELECT COUNT(*) FROM ue_instances WHERE rx_ue_information_tag = %ld AND rnti = %d", rx_ue_information_tag, rnti);
    int ret = mysql_query(mysql_conn, query);
    free(query);
    if (ret != 0) {
        fprintf(stderr, "Failed to execute SQL query: %s\n", mysql_error(mysql_conn));
        return;
    }

    // Create a new UE instance in the database if necessary
    MYSQL_RES *res = mysql_use_result(mysql_conn);
    int row_count = 0;
    while ((row_count = mysql_fetch_row(res)) != 0) {
        ++row_count;
    }
    mysql_free_result(res);
    if (row_count == 0) {
        query = malloc(sizeof(char) * 1024);
        sprintf(query, "INSERT INTO ue_instances (rx_ue_information_tag, rnti) VALUES(%ld, %d)", rx_ue_information_tag, rnti);
        ret = mysql_query(mysql_conn, query);
        free(query);
        if (ret != 0) {
            fprintf(stderr, "Failed to execute SQL query: %s\n", mysql_error(mysql_conn));
            return;
        }
    }

    // Save the CRC indication in the database
    query = malloc(sizeof(char) * 1024);
    sprintf(query, "INSERT INTO crc_indications (rx_ue_information_tag, rnti, payload) VALUES(%ld, %d, '%s')", rx_ue_information_tag, rnti, crc_indication->payload);
    ret = mysql_query(mysql_conn, query);
    free(query);
    if (ret != 0) {
        fprintf(stderr, "Failed to execute SQL query: %s\n", mysql_error(mysql_conn));
        return;
    }
}

// Process all the CRC indications in the queue
void process_queue(void) {
    // Check if the database connection is valid
    if (mysql_conn == NULL || mysql_real_connect(mysql_conn, DB_HOST, DB_USER, DB_PASSWORD, DB_NAME, 0, NULL, 0)) {
        fprintf(stderr, "Failed to connect to MySQL: %s\n", mysql_error(mysql_conn));
        return;
    }

    // Process all the CRC indications in the queue
    struct queue *current = queue_head;
    while (current != NULL) {
        process_crc_indication(current->crc_indications[current->front]);
        current->front = (current->front + 1) % MAX_UE_INSTANCES;
        if (current->front == current->rear) {
            queue_head = queue_tail = NULL;
        } else {
            queue_head = current->next;
        }
        free(current);
        current = queue_head;
    }
}

// Close the database connection and release resources
void close_db(void) {
    if (mysql_conn != NULL) {
        mysql_close(mysql_conn);
    }
}

int main() {
    init_db();
    process_queue();
    close_db();
    return 0;
}
