    // Use a heap-based allocation strategy for large objects to avoid fragmentation issues
    vector<ImageMetadata> largeMetadata;
    for (int i = 0; i < imageFileNames.size(); i++) {
        ImageMetadata& metadata_i = metadata[i];
        if (metadata_i.width * metadata_i.height > 1024 * 1024) {
            largeMetadata.push_back(metadata_i);
        }
    }
    // Memory pooling mechanism to mitigate fragmentation issues and improve allocation efficiency
    // Implement a memory pool that allocates large chunks of memory for the stack-based allocation strategy
    // Use a linked list to store the free blocks, with each block representing a chunk of memory
    struct Block {
        size_t size;
        Block* next;
    };
    struct MemoryPool {
        Block* head;
        size_t totalSize;
    } pool;
    pool.head = nullptr;
    pool.totalSize = 0;
    // Allocate a new block of memory from the pool
    void allocate(size_t size) {
        if (pool.totalSize < size) {
            // If the requested size is greater than the total size of the pool, create a new block and add it to the head of the linked list
            Block* block = new Block{size, pool.head};
            pool.head = block;
            pool.totalSize += size;
        } else {
            // Otherwise, find the first free block that is large enough to satisfy the request and remove it from the linked list
            Block* current = pool.head;
            while (current != nullptr && current->size < size) {
                current = current->next;
            }
            if (current == nullptr) {
                throw std::runtime_error("MemoryPool: Out of memory");
            } else {
                Block* block = current;
                current = current->next;
                pool.totalSize -= block->size;
                return block;
            }
        }
    }
    // Deallocate a block of memory back to the pool
    void deallocate(Block* block) {
        if (block == nullptr) {
            throw std::runtime_error("MemoryPool: Invalid block");
        } else {
            block->next = pool.head;
            pool.head = block;
            pool.totalSize += block->size;
        }
    }
    // Use the memory pool to allocate and deallocate memory for the metadata objects
