from typing import Dict, List, Union

class BatchImageProcessor:
    def __init__(self):
        self.image_metadata = {}
        self.tags = []

    def ingest(self, image_data: dict) -> bool:
        """Ingests image metadata from an external source."""
        try:
            file_name = image_data['FILE_NAME']
            width = image_data['WIDTH']
            height = image_data['HEIGHT']
            compression_ratio = image_data['COMPRESSION_RATIO']
            tags = image_data['TAGS']

            if not self.validate(file_name, width, height, compression_ratio, tags):
                return False

            self.image_metadata[file_name] = {
                'WIDTH': width,
                'HEIGHT': height,
                'COMPRESSION_RATIO': compression_ratio,
                'TAGS': tags
            }
        except KeyError as e:
            print(f"Invalid image data format: missing key {e}")
        except ValueError as e:
            print(f"Invalid image data format: {e}")

        return True

    def validate(self, file_name: str, width: int, height: int, compression_ratio: float, tags: List[str]) -> bool:
        """Validates the consistency and integrity of the metadata."""
        if not file_name.endswith('.jpg'):
            return False

        if width <= 0 or height <= 0:
            return False

        if compression_ratio < 0 or compression_ratio > 1:
            return False

        for tag in tags:
            if not isinstance(tag, str):
                return False

        return True

    def process_batch(self) -> Dict[str, Union[int, float]]:
        """Processes a batch of image metadata."""
        total_size = 0
        total_tags = []

        for file_name in self.image_metadata:
            width = self.image_metadata[file_name]['WIDTH']
            height = self.image_metadata[file_name]['HEIGHT']
            compression_ratio = self.image_metadata[file_name]['COMPRESSION_RATIO']
            tags = self.image_metadata[file_name]['TAGS']

            total_size += width * height
            total_tags.extend(tags)

        return {
            'TOTAL_SIZE': total_size,
            'NUM_IMAGES': len(self.image_metadata),
            'UNIQUE_TAGS': list(set(total_tags))
        }

    def save_to_file(self, file_name: str):
        """Saves the processed image metadata to a file."""
        with open(file_name, 'w') as f:
            json.dump(self.image_metadata, f)

    def monitor(self) -> Dict[str, Union[int, float]]:
        """Monitors the performance of the system."""
        return {
            'NUM_IMAGES': len(self.image_metadata),
            'TOTAL_SIZE': sum([width * height for file_name in self.image_metadata])
        }

    def handle_api_failure(self, api_url: str):
        """Handles API failures by retrying with an intelligent backoff strategy."""
        try:
            response = requests.get(api_url)
            if response.status_code == 200:
                return json.loads(response.text)
        except RequestException as e:
            print(f"API failure: {e}")

    def update_tags(self, file_name: str):
        """Updates the tags of an image in the metadata."""
        if not self.validate(file_name, width, height, compression_ratio, tags):
            return False

        self.image_metadata[file_name]['TAGS'] = tags

    def get_tags(self, file_name: str) -> List[str]:
        """Gets the tags of an image in the metadata."""
        if file_name not in self.image_metadata:
            return []

        return self.image_metadata[file_name]['TAGS']

    def get_tagged_images(self, tag: str) -> List[str]:
        """Gets a list of image file names that have the specified tag."""
        return [file_name for file_name in self.image_metadata if tag in self.image_metadata[file_name]['TAGS']]
