#define CRCFLAG true
int processCrcIndications(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return -1;
    int ret = 0;
    struct workerArgs{
        pthread_t threadID;
        NFAPI_CRC_INDICATION_PDU_T* pdu;
    }workerArgs[MAX_CONCURRENT_THREADS];
    for(int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        workerArgs[i].pdu = NULL;
        if (pthread_create(&workerArgs[i].threadID, NULL, workerThread, &workerArgs[i])){
            printf("Failed to create thread %d\n", i);
            exit(1);
        }
    }
    for(int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        if (pthread_join(workerArgs[i].threadID, NULL)) printf("Failed to join thread %d\n", i);
    }
}
void* workerThread(void *args){
    struct workerArgs* workerArgs = args;
    while(workerArgs->pdu != NULL) {
        processPdu(workerArgs->pdu);
        workerArgs->pdu = NULL;
