        sqlite3_close(db);
        return -1;
    }
    char* sql = "INSERT INTO CRC_INDICATIONS (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG) VALUES (@RX_UE_INFORMATION_TAG, @RNTI, @CRC_INDICATION_REL8_TAG, @CRCFLAG);";
    sqlite3_stmt* stmt = NULL;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK){
        printf("Failed to prepare statement\n");
        error = sqlite3_errmsg(db);
        printf("Error: %s\n", error);
        sqlite3_close(db);
        return -1;
    }
    sqlite3_bind_int(stmt, 1, pdu->RX_UE_INFORMATION_TAG);
    sqlite3_bind_int(stmt, 2, pdu->RNTI);
    sqlite3_bind_int(stmt, 3, pdu->CRC_INDICATION_REL8_TAG);
    sqlite3_bind_boolean(stmt, 4, pdu->CRCFLAG);
    if (sqlite3_step(stmt) != SQLITE_OK){
        error = sqlite3_errmsg(db);
        printf("Error: %s\n", error);
        sqlite3_close(db);
        return -1;
    }
    sqlite3_finalize(stmt);
    sqlite3_close(db);
    return 0;
}
