// Define a function to remove the value associated with a given key in the hash table
void* hashtable_remove(HashTable* hashtable, void* key) {
    if (!hashtable || !key) {
        printf("Error: Hash table or key is null!\n");
        return NULL;
    }
    int index = (int)(key - hashtable->values);
    return index >= 0 && index < hashtable->capacity ? hashtable_remove(hashtable, &index) : NULL;
}

// Define a function to clear the hash table
void hashtable_clear(HashTable* hashtable) {
    if (!hashtable) {
        printf("Error: Hash table is null!\n");
        return;
    }
    for (int i = 0; i < hashtable->capacity; i++) {
        void* value = hashtable_find(hashtable, &i);
        if (value) {
            hashtable_remove(hashtable, &i);
        }
    }
}

// Define a function to resize the hash table
void hashtable_resize(HashTable* hashtable, int newCapacity) {
    if (!hashtable) {
        printf("Error: Hash table is null!\n");
        return;
    }
    HashTable* temp = (HashTable*)malloc(sizeof(HashTable));
    temp->capacity = newCapacity;
    temp->count = 0;
    temp->values = (void**)malloc(newCapacity * sizeof(void*));
    for (int i = 0; i < hashtable->capacity; i++) {
        void* value = hashtable_find(hashtable, &i);
        if (value) {
            temp->count++;
            int index = (int)(key - temp->values);
            while (index != i) {
                index = (index + 1) % temp->capacity;
            }
            hashtable_add(temp, &index, value);
        }
    }
}']

