using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace FetchAndProcessData
{
    public class DataFetcher
    {
        private readonly HttpClient _httpClient = new HttpClient();
        private readonly JsonSerializerSettings _jsonSerializerSettings = new JsonSerializerSettings();
        private readonly BinaryFormatter _binaryFormatter = new BinaryFormatter();
        private readonly MemoryCache _memoryCache = new MemoryCache(new MemoryCacheOptions());

        public async Task<object> FetchAndProcessDataAsync(string apiUrl, string binaryFilePath)
        {
            // Handle edge cases for invalid API URLs and binary file paths
            if (string.IsNullOrEmpty(apiUrl))
                throw new ArgumentException("Invalid API URL", nameof(apiUrl));
            if (!File.Exists(binaryFilePath))
                throw new FileNotFoundException($"Binary file not found: {binaryFilePath}", binaryFilePath);

            // Load and deserialize the JSON data from the API
            JObject jsonData = await _httpClient.GetStringAsync(apiUrl).ConfigureAwait(false);
            object deserializedData = JsonConvert.DeserializeObject<object>(jsonData.ToString(), _jsonSerializerSettings);

            // Load and deserialize the binary data from the file
            byte[] binaryData = File.ReadAllBytes(binaryFilePath);
            object deserializedBinaryData = _binaryFormatter.Deserialize(new MemoryStream(binaryData));

            // Combine the JSON and binary data into a single custom data structure
            return new CustomDataStructure(deserializedData, deserializedBinaryData);
        }
    }

    public class CustomDataStructure
    {
        public object JsonData { get; set; }
        public object BinaryData { get; set; }

        public CustomDataStructure(object jsonData, object binaryData)
        {
            JsonData = jsonData;
            BinaryData = binaryData;
        }
    }
}
