    uint8_t validRxUeInformationTag;
    uint8_t crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static redisContext *redis_ctx = NULL;

// Function prototypes
static void generateCrcIndications(uint32_t num_indications, uint16_t seed);
static NFAPI_CRC_INDICATION_PDU_T* createCrcIndicationPdu(uint16_t rnti);
static void freeCrcIndicationPdus(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t num_pdus);

// Implementation
void generateCrcIndications(uint32_t num_indications, uint16_t seed) {
    // Initialize Redis connection if not already initialized
    if (!redis_ctx) {
        redis_ctx = redisConnect("localhost", 6379);
        if (redis_ctx == NULL || redis_ctx->err) {
            fprintf(stderr, "Error connecting to Redis: %s\n", redis_ctx->errstr);
            exit(1);
        }
    }

    // Create a pool allocator for efficient memory management
    PoolAllocator *alloc = createPoolAllocator();

    // Generate CRC indications using the provided seed value
    uint32_t i;
    for (i = 0; i < num_indications; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = createCrcIndicationPdu(seed);
        addToPoolAllocator(alloc, pdu);
    }

    // Store CRC indications in the Redis database
    for (i = 0; i < num_indications; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)getFromPoolAllocator(alloc);
        redisReply *reply = (redisReply *)redisCommand(redis_ctx, "SET %d %u", pdu->rnti, pdu->crcIndicationRel8Tag);
        if (reply == NULL || reply->type != REDIS_REPLY_STATUS) {
            fprintf(stderr, "Error storing CRC indication in Redis: %s\n", redis_ctx->errstr);
        }
    }

    // Release memory allocated by the pool allocator
    freePoolAllocator(alloc);
}

static NFAPI_CRC_INDICATION_PDU_T* createCrcIndicationPdu(uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->rnti = rnti;
    pdu->validRxUeInformationTag = 1; // Valid RX UE information tag
    pdu->crcIndicationRel8Tag = random() % 2 ? 0 : 1; // Randomly set CRCFLAG to either 0 or 1
    return pdu;
}

static void freeCrcIndicationPdus(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        free(pdus[i]);
    }
}
