#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <time.h>
#include <stdarg.h>

#define MAX_CRC_INDICATIONS 1000000 // maximum number of CRC indications to handle
#define MIN_SEED 0                  // minimum seed value for RNTI generation
#define MAX_SEED 65535              // maximum seed value for RNTI generation
#define DEFAULT_RX_UE_INFORMATION_TAG 12345 // default RX UE information tag
#define DEFAULT_CRC_INDICATION_REL8_TAG 90 // default CRC indication REL8 tag
#define MAX_LOG_SIZE 1024           // maximum size of log message

// structure to hold a single CRC indication
typedef struct {
    int rnti;                       // RNTI value for the UE
    int validRxUeInformationTag;    // valid RX UE information tag
    int crcIndicationRel8Tag;       // CRC indication REL8 tag
} NFAPI_CRC_INDICATION_PDU_T;

// structure to hold a list of CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crcIndications; // array of CRC indications
    int size;                     // number of CRC indications in the array
} NFAPI_CRC_INDICATION_LIST_T;

// function to generate a random RNTI value within the specified seed range
int generateRandomRnti(int minSeed, int maxSeed) {
    return rand() % (maxSeed - minSeed + 1) + minSeed;
}

// function to initialize a list of CRC indications with a specified number of elements
NFAPI_CRC_INDICATION_LIST_T *initializeCrcIndicationList(int numElements) {
    NFAPI_CRC_INDICATION_LIST_T *crcIndicationList = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    crcIndicationList->size = numElements;
    crcIndicationList->crcIndications = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return crcIndicationList;
}

// function to free a list of CRC indications
void freeCrcIndicationList(NFAPI_CRC_INDICATION_LIST_T *crcIndicationList) {
    if (crcIndicationList->crcIndications != NULL) {
        free(crcIndicationList->crcIndications);
    }
    free(crcIndicationList);
}

// function to add a new CRC indication to the list
void addCrcIndicationToList(NFAPI_CRC_INDICATION_LIST_T *crcIndicationList, int rnti, int validRxUeInformationTag, int crcIndicationRel8Tag) {
    // check if there is space in the list for a new CRC indication
    if (crcIndicationList->size < MAX_CRC_INDICATIONS) {
        crcIndicationList->crcIndications[crcIndicationList->size].rnti = rnti;
        crcIndicationList->crcIndications[crcIndicationList->size].validRxUeInformationTag = validRxUeInformationTag;
        crcIndicationList->crcIndications[crcIndicationList->size].crcIndicationRel8Tag = crcIndicationRel8Tag;
        crcIndicationList->size++;
    } else {
        // log error and return
        printf("Error: Maximum number of CRC indications exceeded\n");
        return;
    }
}

// function to remove a CRC indication from the list by RNTI value
void removeCrcIndicationFromList(NFAPI_CRC_INDICATION_LIST_T *crcIndicationList, int rnti) {
    // find index of CRC indication with specified RNTI value
    for (int i = 0; i < crcIndicationList->size; i++) {
        if (crcIndicationList->crcIndications[i].rnti == rnti) {
            // move last element to index of removed element
            memmove(&crcIndicationList->crcIndications[i], &crcIndicationList->crcIndications[crcIndicationList->size - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            crcIndicationList->size--;
            break;
        }
    }
}

// function to generate a list of CRC indications with specified number of elements and random seed values
void generateCrcIndications(int numElements, int minSeed, int maxSeed) {
    // create empty list of CRC indications
    NFAPI_CRC_INDICATION_LIST_T *crcIndicationList = initializeCrcIndicationList(numElements);
    // generate random RNTIs for each CRC indication
    for (int i = 0; i < numElements; i++) {
        int rnti = generateRandomRnti(minSeed, maxSeed);
        addCrcIndicationToList(crcIndicationList, rnti, DEFAULT_RX_UE_INFORMATION_TAG, DEFAULT_CR_INDICATION_REL8_TAG);
    }
}

// function to log CRC indications in the list
void logCrcIndications(NFAPI_CRC_INDICATION_LIST_T *crcIndicationList) {
    for (int i = 0; i < crcIndicationList->size; i++) {
        printf("CRC indication %d: RNTI=%d, validRxUeInformationTag=%d, crcIndicationRel8Tag=%d\n", i + 1, crcIndicationList->crcIndications[i].rnti, crcIndicationList->crcIndications[i].validRxUeInformationTag, crcIndicationList->crcIndications[i].crcIndicationRel8Tag);
    }
}

// function to connect to the Redis database and initialize a list of CRC indications with specified number of elements
void redisConnectAndInitializeCrcIndicationList(int numElements) {
    // establish connection to Redis database
    struct redisContext *redis = redisConnect("localhost", 6379);
    if (redis == NULL || redis->err) {
        printf("Error: Failed to connect to Redis database\n");
        return;
    }
    // initialize list of CRC indications with specified number of elements
    NFAPI_CRC_INDICATION_LIST_T *crcIndicationList = initializeCrcIndicationList(numElements);
}

// function to disconnect from the Redis database and free a list of CRC indications
void redisDisconnectAndFreeCrcIndicationList(NFAPI_CRC_INDICATION_LIST_T *crcIndicationList) {
    // disconnect from Redis database
    if (redis->err == 0) {
        redisFree(redis);
    } else {
        printf("Error: Failed to disconnect from Redis database\n");
    }
    // free list of CRC indications
    freeCrcIndicationList(crcIndicationList);
}

// function to add a new CRC indication to the list and save it to the Redis database
void redisAddAndSaveNewCrcIndication(int rnti, int validRxUeInformationTag, int crcIndicationRel8Tag) {
    // create empty list of CRC indications if one does not exist
    if (redis == NULL) {
        redisConnectAndInitializeCrcIndicationList(0);
    }
    // add new CRC indication to the list
    addCrcIndicationToList(crcIndicationList, rnti, validRxUeInformationTag, crcIndicationRel8Tag);
    // save new CRC indication to the Redis database
    redisSaveCrcIndications();
}

// function to remove a CRC indication from the list and delete it from the Redis database
void redisRemoveAndDeleteCrcIndication(int rnti) {
    // create empty list of CRC indications if one does not exist
    if (redis == NULL) {
        redisConnectAndInitializeCrcIndicationList(0);
    }
    // remove specified CRC indication from the list
    removeCrcIndicationFromList(crcIndicationList, rnti);
    // delete specified CRC indication from the Redis database
    redisDeleteCrcIndications();
}

// function to save CRC indications in the Redis database
void redisSaveCrcIndications() {
    // convert list of CRC indications to a JSON string and save it to the Redis database
    char *jsonString = json_encode(crcIndicationList);
    if (redis->err == 0) {
        redisSet(redis, "CRCIndications", jsonString);
    } else {
        printf("Error: Failed to save CRC indications in Redis database\n");
    }
}

// function to delete CRC indications from the Redis database
void redisDeleteCrcIndications() {
    // delete "CRCIndications" key and value from the Redis database
    if (redis->err == 0) {
        redisDel(redis, "CRCIndications");
    } else {
        printf("Error: Failed to delete CRC indications in Redis database\n");
    }
}

// function to retrieve CRC indications from the Redis database and initialize a list of CRC indications with them
void redisRetrieveAndInitializeCrcIndicationList() {
    // create empty list of CRC indications if one does not exist
    if (redis == NULL) {
        redisConnectAndInitializeCrcIndicationList(0);
    }
    // retrieve "CRCIndications" key and value from the Redis database
    char *jsonString = redisGet(redis, "CRCIndications");
    if (jsonString != NULL) {
        // initialize list of CRC indications with JSON string
        json_decode(crcIndicationList, jsonString);
    } else {
        printf("Error: Failed to retrieve CRC indications from Redis database\n");
    }
}
```

This code defines a `CRCIndication` struct that represents a single CRC indication, and a `CRCIList` struct that is a list of `CRCIndication` objects. The `redisConnectAndInitializeCrcIndicationList()` function establishes a connection to the Redis database and initializes an empty list of CRC indications if one does not exist. The `redisAddAndSaveNewCrcIndication()` function adds a new CRC indication to the list and saves it to the Redis database, while the `redisRemoveAndDeleteCrcIndication()` function removes a specified CRC indication from the list and deletes it from the Redis database. The `redisRetrieveAndInitializeCrcIndicationList()` function retrieves the list of CRC indications from the Redis database and initializes the local list with them.

Note that this code uses a third-party library for JSON encoding and decoding, which is not included in this repository but can be found on [GitHub](https://github.com/nlohmann/json). The `redis` library used for establishing a connection to the Redis database is also not included in this repository but can be installed using your system's package manager or by building it from source.']

