import csv
import time
import datetime
from collections import defaultdict

class TransactionProcessor(object):
    def __init__(self, file_path, api_url):
        self.file_path = file_path
        self.api_url = api_url
        self.transactions = []
        self.customer_map = {}
        self.product_map = {}

    def process_transaction(self, transaction):
        customer_id = transaction['customer_id']
        product_id = transaction['product_id']
        amount = transaction['amount']
        date = datetime.datetime.strptime(transaction['date'], '%Y-%m-%d %H:%M:%S')
        if customer_id not in self.customer_map:
            self.customer_map[customer_id] = defaultdict(int)
        self.customer_map[customer_id][product_id] += amount
        self.transactions.append(transaction)

    def process_file(self):
        with open(self.file_path, 'r') as f:
            reader = csv.DictReader(f)
            for transaction in reader:
                try:
                    self.process_transaction(transaction)
                except ValueError as e:
                    print('Error processing transaction {}: {}'.format(transaction['customer_id'], e))

    def get_total_transactions(self, customer_id):
        if customer_id not in self.customer_map:
            return 0
        else:
            return len(self.customer_map[customer_id])

    def get_transaction_count(self, product_id):
        total = 0
        for customer_id, amounts in self.customer_map.items():
            if product_id in amounts:
                total += amounts[product_id]
        return total

    def get_total_amount(self, product_id):
        total = 0
        for customer_id, amounts in self.customer_map.items():
            if product_id in amounts:
                total += amounts[product_id]
        return total

    def validate_transaction(self, transaction):
        try:
            api_response = requests.get('{}?amount={}&date={}'.format(self.api_url, transaction['amount'], transaction['date']))
            if api_response.status_code != 200:
                raise Exception('API error')
        except Exception as e:
            print('Error validating transaction {}: {}'.format(transaction['customer_id'], e))

    def validate_transactions(self):
        for transaction in self.transactions:
            try:
                self.validate_transaction(transaction)
            except Exception as e:
                print('Error validating transactions: {}'.format(e))

class CustomerAnalytics(object):
    def __init__(self, customer_id):
        self.customer_id = customer_id
        self.total_transactions = 0
        self.transaction_counts = defaultdict(int)
        self.total_amount = 0

    def add_transaction(self, transaction):
        product_id = transaction['product_id']
        amount = transaction['amount']
        date = datetime.datetime.strptime(transaction['date'], '%Y-%m-%d %H:%M:%S')
        self.total_transactions += 1
        self.transaction_counts[product_id] += 1
        self.total_amount += amount

    def get_customer_analytics(self):
        return {
            'total_transactions': self.total_transactions,
            'transaction_counts': self.transaction_counts,
            'total_amount': self.total_amount
        }

