impl BackpressureManager {
    fn new() -> Self {
        BackpressureManager {
            sources: HashMap::new(),
        }
    }

    /// Adds a new event source to the backpressure manager.
    fn add_source(&mut self, name: String) {
        self.sources.insert(name, false);
    }

    /// Sets the backpressure state of an event source.
    fn set_backpressure(&mut self, name: &str, backpressure: bool) {
        if let Some(source) = self.sources.get_mut(name) {
            *source = backpressure;
        }
    }

    /// Checks the current backpressure state of an event source.
    fn check_backpressure(&self, name: &str) -> bool {
        if let Some(backpressure) = self.sources.get(name) {
            *backpressure
        } else {
            false
        }
    }
}
