    pthread_cond_t cond;
    int num_active;
    int num_waiting;
    int data[MAX_ARRAY_SIZE];
} NFAPI_CRC_INDICATION_PDU_T_array;

void init_array(NFAPI_CRC_INDICATION_PDU_T_array *arr, size_t n) {
    arr->mutex = PTHREAD_MUTEX_INITIALIZER;
    arr->cond = PTHREAD_COND_INITIALIZER;
    arr->num_active = 0;
    arr->num_waiting = 0;
    for (size_t i = 0; i < n; i++) {
        arr->data[i] = -1;
    }
}

void deinit_array(NFAPI_CRC_INDICATION_PDU_T_array *arr) {
    pthread_mutex_destroy(&arr->mutex);
    pthread_cond_destroy(&arr->cond);
}

