    int size;
    pthread_mutex_lock(&arr->mutex);
    size = arr->num_active;
    pthread_mutex_unlock(&arr->mutex);
    return size;
}

bool push(NFAPI_CRC_INDICATION_PDU_T_array *arr, int value) {
    bool ret = false;
    pthread_mutex_lock(&arr->mutex);
    if (arr->num_active < MAX_ARRAY_SIZE) {
        arr->data[arr->num_active++] = value;
        ret = true;
    }
    pthread_cond_signal(&arr->cond);
    pthread_mutex_unlock(&arr->mutex);
    return ret;
}

bool pop(NFAPI_CRC_INDICATION_PDU_T_array *arr, int *value) {
    bool ret = false;
    pthread_mutex_lock(&arr->mutex);
    while (arr->num_active == 0) {
        pthread_cond_wait(&arr->cond, &arr->mutex);
    }
    *value = arr->data[--arr->num_active];
    ret = true;
    pthread_mutex_unlock(&arr->mutex);
    return ret;
}

void reset_array(NFAPI_CRC_INDICATION_PDU_T_array *arr) {
    int i;
    pthread_mutex_lock(&arr->mutex);
    for (i = 0; i < arr->num_active; i++) {
        arr->data[i] = -1;
    }
    arr->num_active = 0;
    pthread_cond_signal(&arr->cond);
    pthread_mutex_unlock(&arr->mutex);
