        ofstream outputFile;
        outputFile.open(outputFilePath, ios::out | ios::binary);
        for (auto& line : cache[filePath_]) {
            outputFile << line << endl;
        }
        outputFile.close();
    }

private:
    // Check if a new line is available to be processed
    bool isFinished() {
        lock_guard<mutex> lk(mtx_);
        return lines_.empty();
    }

    // Get the next line from the file and add it to the cache
    void getNextLine(string& line) {
        lock_guard<mutex> lk(mtx_);
        if (!lines_.empty()) {
            line = lines_.front();
            lines_.pop_front();
        }
    }

    // Notify that a new line was processed and add it to the cache
    void notifyNewLine() {
        lock_guard<mutex> lk(mtx_);
        conditionVariable_.notify_all();
    }

    // Get the output file path based on the input file path
    string getOutputFilePath(const string& filePath) {
        return filePath + ".out";
    }

    // Parse a line for numerical values and compute the average
    vector<int> parseLine(const string& line) {
        vector<int> numbers;
        int start = 0;
        int end = 0;
        while ((end = line.find_first_of(" ", start)) != string::npos) {
            numbers.push_back(stoi(line.substr(start, end - start)));
            start = end + 1;
        }
        return numbers;
    }

    // File path and number of worker threads
    const string filePath_;
    const int workerThreads_;

    // Cache for file paths and lines
    unordered_map<string, vector<string>> cache;

    // Mutex and condition variable for synchronizing access to the cache
    mutex mtx_;
    condition_variable conditionVariable_;

    // Queue of available lines from the file
    deque<string> lines_;
};

int main(int argc, char* argv[]) {
    if (argc < 3) {
        cerr << "Usage: " << argv[0] << " <file path> <worker threads>" << endl;
        return EXIT_FAILURE;
    }

    string filePath = argv[1];
    int workerThreads = stoi(argv[2]);

    // Create a directory for the output files if it does not exist
    // directory_creation::createDirectory(filePath + ".out");

    // Set an environment variable to the directory path only if it is not already set
    // directory_creation::setDirectoryEnvVar("OUTPUT_DIR", filePath + ".out");

    FileProcessor processor(filePath, workerThreads);
    processor.processFile();

    return EXIT_SUCCESS;
}
```
