void insertAfter(std::forward_list<std::string>& list, const std::string& first, const std::string& second) {
    auto it = std::find(list.begin(), list.end(), first);
    if (it != list.end()) {
        list.insert_after(it, second);
    } else {
        list.push_back(second);
    }
}
