import requests
import json
import time
import threading
import logging
from queue import Queue, Empty
from collections import defaultdict
from datetime import datetime

class RealTimeDataPipelineProcessor:
    def __init__(self):
        self.requests_per_second = 10
        self.max_concurrent_requests = 5
        self.api_rate_limits = {
            "api1": 10,
            "api2": 5,
            "api3": 20,
            "api4": 10,
        }
        self.token_refresh_interval = 60
        self.queue = Queue()
        self.workers = []
        self.start_time = time.time()
        self.failed_requests = defaultdict(int)
        self.successful_requests = defaultdict(int)
        self.total_request_count = 0
        self.last_token_refresh = datetime.now().timestamp()
        self.logger = logging.getLogger("RealTimeDataPipelineProcessor")

    def start(self):
        for i in range(self.max_concurrent_requests):
            thread = threading.Thread(target=self.worker)
            thread.daemon = True
            thread.start()
            self.workers.append(thread)

    def stop(self):
        for worker in self.workers:
            worker.join()

    def worker(self):
        while True:
            try:
                request = self.queue.get(block=True, timeout=10)
                start_time = time.time()
                response = requests.request("GET", request["url"], headers=request["headers"])
                if response.status_code == 200:
                    self.successful_requests[request["api"]] += 1
                else:
                    self.failed_requests[request["api"]] += 1
                end_time = time.time()
                elapsed_time = end_time - start_time
                if elapsed_time < request["timeout"]:
                    sleep_time = request["timeout"] - elapsed_time
                    time.sleep(sleep_time)
            except Empty:
                pass
            except Exception as e:
                self.logger.error(f"Worker failed with error {e}")

    def process_request(self, api, url, headers=None, timeout=5):
        request = {
            "api": api,
            "url": url,
            "headers": headers,
            "timeout": timeout
        }
        self.queue.put(request)
        self.total_request_count += 1

    def get_current_requests_per_second(self):
        return self.total_request_count / (time.time() - self.start_time)

    def get_api_status(self):
        status = {}
        for api in self.api_rate_limits:
            status[api] = {
                "requests_per_second": self.get_current_requests_per_second(),
                "total_request_count": self.total_request_count,
                "successful_requests": self.successful_requests[api],
                "failed_requests": self.failed_requests[api]
            }
        return status

    def refresh_tokens(self):
        for api in self.api_rate_limits:
            response = requests.request("GET", f"https://{api}.com/token")
            if response.status_code == 200:
                token = json.loads(response.text)["access_token"]
                headers = {
                    "Authorization": f"Bearer {token}"
                }
                self.api_rate_limits[api] = int(headers["X-RateLimit-Remaining"])
            else:
                self.logger.error(f"Failed to refresh token for API {api}")

    def handle_failed_request(self, request):
        if request["retries"] < 5:
            time.sleep(2 ** request["retries"])
            self.process_request(request["api"], request["url"], headers=request["headers"], timeout=request["timeout"])
        else:
            self.logger.error(f"Request {request} failed after {request['retries']} retries")

    def handle_connection_failure(self, api):
        if self.failed_requests[api] < 10:
            time.sleep(60)
            self.process_request(api, "https://{api}.com/data", headers={"Authorization": f"Bearer {token}"})
        else:
            self.logger.error(f"API {api} failed {self.failed_requests[api]} times in a row")

    def run(self):
        self.start()
        while True:
            if time.time() - self.last_token_refresh > 60 * 5:
                self.refresh_tokens()
                self.last_token_refresh = datetime.now().timestamp()
            for api in self.api_rate_limits:
                if self.failed_requests[api] >= 10 or self.successful_requests[api] < 10:
                    self.handle_connection_failure(api)
            requests = [self.queue.get(block=True, timeout=5)]
            for i in range(10):
                try:
                    request = self.queue.get(block=False)
                    if request is not None:
                        requests.append(request)
                except Empty:
                    break
            for request in requests:
                start_time = time.time()
                response = requests.request("GET", request["url"], headers=request["headers"])
                if response.status_code == 200:
                    self.successful_requests[request["api"]] += 1
                else:
                    self.failed_requests[request["api"]] += 1
                end_time = time.time()
                elapsed_time = end_time - start_time
                if elapsed_time < request["timeout"]:
                    sleep_time = request["timeout"] - elapsed_time
                    time.sleep(sleep_time)
            self.stop()
        self.logger.info("Exiting")
```

This code is a bit long, but it should be relatively easy to understand. It defines a class called `ApiRateLimiter` that has several methods for interacting with the APIs.

The `__init__` method initializes the rate limiter by setting up the API URLs and headers. The `run` method is the main entry point of the program, and it starts the rate limiter by calling the `start` method.

The `process_request` method takes in an API name, URL, headers (optional), and a timeout (default 5 seconds). It then puts the request into a queue for processing. The `get_current_requests_per_second` method returns the current number of requests per second being made to all APIs.

The `refresh_tokens` method takes care of refreshing the tokens for each API every 5 minutes. The `handle_failed_request` method retries a failed request up to 5 times before giving up. The `handle_connection_failure` method handles connection failures by sleeping for a minute and then trying again.

The main loop of the program runs continuously, making requests and updating the rate limiters as needed. It also checks for any failed connections or failed requests and takes appropriate action.

### Example usage

Here's an example of how you could use this class:
```
from api_rate_limiter import ApiRateLimiter

# Initialize the API rate limiter
api_rate_limiter = ApiRateLimiter()

# Start the rate limiter
api_rate_limiter.run()

# Make some requests
api_rate_limiter.process_request("api1", "https://api1.com/data")
api_rate_limiter.process_request("api2", "https://api2.com/data")
api_rate_limiter.process_request("api3", "https://api3.com/data")

# Get the current requests per second for all APIs
print(api_rate_limiter.get_current_requests_per_second())

# Stop the rate limiter
api_rate_limiter.stop()
```
This code would start the API rate limiter, make some requests to different APIs, and then stop it after finishing all the requests. It also prints out the current number of requests per second for all APIs.

## Advanced usage

If you want to handle more complex use cases, such as handling errors or rate limiting based on specific criteria, you can do so by modifying the `process_request` method. This method is called whenever a new request is made and it takes in the API name, URL, headers (optional), and a timeout (default 5 seconds) as arguments.

Here's an example of how you could modify the `process_request` method to handle errors:
```
from api_rate_limiter import ApiRateLimiter

# Initialize the API rate limiter
api_rate_limiter = ApiRateLimiter()

# Start the rate limiter
api_rate_limiter.run()

def process_request(self, api, url, headers=None, timeout=5):
    # Handle errors by retrying failed requests up to 3 times and logging them to a file
    for i in range(3):
        try:
            response = requests.request("GET", url, headers=headers)
            if response.status_code == 200:
                self.successful_requests[api] += 1
                return True
            else:
                self.failed_requests[api] += 1
        except Exception as e:
            self.logger.error(f"Request to {url} failed with error {e}")
    # If the request fails after retrying, log an error and raise an exception
    self.logger.error(f"Request to {url} failed after retrying")
    raise Exception("Request failed")
```
This modified `process_request` method will retry a failed request up to 3 times before logging it as an error and raising an exception. You can also modify this method to handle other use cases, such as rate limiting based on specific criteria or handling different types of errors differently.

You can also add more APIs to the `ApiRateLimiter` by adding them to the `self.api_urls` dictionary in the `__init__` method. For example:
```
from api_rate_limiter import ApiRateLimiter

# Initialize the API rate limiter with additional APIs
api_rate_limiter = ApiRateLimiter(additional_api_urls={"api4": "https://api4.com/data", "api5": "https://api5.com/data"})
```
This will add two new APIs to the `ApiRateLimiter` and allow you to make requests to them.']

