// Define the queue type and its associated methods
class Queue {
public:
    // Constructor that takes the maximum number of elements in the queue as an argument
    Queue(int maxElements) : maxElements_(maxElements), size_(0), head_(0), tail_(0) {}

    // Method to enqueue a new compression request into the queue
    void enqueue(const CompressionRequest& request) {
        unique_lock<mutex> lock(mutex_);

        // Check if the queue is full and wait for space to become available if necessary
        while (size_ == maxElements_) {
            condition_.wait(lock);
        }

        // Add the new request to the end of the queue
        requests_.push_back(request);
        size_++;

        // Notify any waiting threads that space has become available
        condition_.notify_all();
    }

    // Method to dequeue a compression request from the front of the queue
    CompressionRequest dequeue() {
        unique_lock<mutex> lock(mutex_);

        // Check if the queue is empty and wait for an element to become available if necessary
        while (size_ == 0) {
            condition_.wait(lock);
        }

        CompressionRequest request = requests_[head_];

        // Remove the first element from the queue
        head_++;
        size_--;

        // Notify any waiting threads that space has become available
        condition_.notify_all();

        return request;
    }

private:
    int maxElements_;     // Maximum number of elements in the queue
    int size_;           // Current number of elements in the queue
    int head_;           // Index of the front element in the queue
    int tail_;           // Index of the back element in the queue
    vector<CompressionRequest> requests_;   // Vector of compression requests
    mutex mutex_;        // Mutex to protect concurrent access to the queue
    condition_variable condition_;  // Condition variable for waiting for space to become available
};

