    uint16_t cellID;
    uint8_t  mcs;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the priority queue for handling concurrent updates
struct PriorityQueue {
    // The head of the linked list, representing the highest-priority element
    struct ListNode *head;

    // A linked list of all elements in the queue, ordered by priority
    struct ListNode *list;
};

// Define a node for the linked list used to store CRC indications
struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;

    // The next node in the linked list, if any
    struct ListNode *next;
};

// Define a function for inserting an element into the priority queue
void insertIntoQueue(struct PriorityQueue *queue, NFAPI_CRC_INDICATION_PDU_T data) {
    // Create a new node to hold the data
    struct ListNode *newNode = malloc(sizeof(struct ListNode));

    if (newNode == NULL) {
        // Handle memory exhaustion error
        printf("Error: unable to allocate memory for new node\n");
        return;
    }

    newNode->data = data;

    // Insert the node at the head of the linked list, if the queue is empty
    if (queue->head == NULL) {
        queue->head = newNode;
        queue->list = newNode;
    } else {
        // Otherwise, insert the node after the current head
        newNode->next = queue->head;
        queue->head = newNode;
    }
}

// Define a function for removing the element with the highest priority from the queue
NFAPI_CRC_INDICATION_PDU_T popFromQueue(struct PriorityQueue *queue) {
    // Remove the head node from the linked list
    struct ListNode *oldHead = queue->head;

    if (oldHead == NULL) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T data = oldHead->data;

    // Update the head pointer to the next node in the list, if any
    queue->head = oldHead->next;

    free(oldHead);

    return data;
}

// Define a function for handling CRC indication updates
void updateCrcIndications(struct PriorityQueue *queue) {
    // Loop through the linked list of CRC indications and process each one
    struct ListNode *node = queue->list;

    while (node != NULL) {
        // Process the current node's data
        NFAPI_CRC_INDICATION_PDU_T data = node->data;

        // Update the database with the CRC indication
        redisContext *redisConn = connectRedis();

        if (redisConn == NULL) {
            // Handle database connection failure error
            printf("Error: unable to connect to Redis database\n");
            return;
        }

        int status = writeCrcIndicationToDb(data, redisConn);

        if (status != 0) {
            // Handle database write failure error
            printf("Error: unable to write CRC indication to Redis database\n");
            return;
        }

        // Remove the node from the linked list
        struct ListNode *nextNode = node->next;
        free(node);

        // Update the head pointer and loop through the next node
        queue->head = nextNode;
        node = nextNode;
    }
}

// Define a function for connecting to the Redis database
redisContext *connectRedis() {
    // Connect to the Redis server using TCP
    redisContext *conn = redisConnect("localhost", 6379);

    if (conn == NULL) {
        // Handle connection failure error
        printf("Error: unable to connect to Redis database\n");
        return;
    }

    // Check the connection status and handle any errors
    if (conn->err != 0) {
        printf("Error: Redis connection failed with error code %d\n", conn->err);
        redisFree(conn);
        return NULL;
    }

    return conn;
}

// Define a function for writing CRC indications to the Redis database
int writeCrcIndicationToDb(NFAPI_CRC_INDICATION_PDU_T data, redisContext *conn) {
    // Create a new key for the CRC indication in the database
    char key[256];

    sprintf(key, "crc_indications_%d", data.cellID);

    // Write the CRC indication to the database as JSON
    redisReply *reply = (redisReply *)redisCommand(conn, "JSON.SET %s %d %d", key, data.crc, data.mcs);

    if (reply == NULL) {
        // Handle write failure error
        printf("Error: unable to write CRC indication to Redis database\n");
        return 1;
    }

    freeReplyObject(reply);

    return 0;
}
