        // grow the array by 50% when it reaches capacity
        size_t new_capacity = list->capacity + (list->capacity / 2);
        struct crc_indication *new_data = realloc(list->data, new_capacity * sizeof(struct crc_indication));
        if (!new_data) {
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->length].rnti = rnti;
    list->data[list->length].valid_rx_ue_information = valid_rx_ue_information;
