Here is a suggested implementation of the encryption service using OpenSSL:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

// Structure to hold configuration data for the encryption service
typedef struct {
    char* cipher_suites[10]; // Array of supported cipher suites
    int num_ciphers;         // Number of cipher suites in the array
    char* key_file;          // Path to the key file for encryption/decryption
    char* cert_file;         // Path to the certificate file for authentication
} EncryptionConfig;

// Function to load and configure the OpenSSL library
void initOpenSSL() {
    SSL_library_init();
    SSL_load_error_strings();
    ERR_load_BIO_strings();
}

// Function to fetch supported cipher suites from an external API
char* getSupportedCiphers() {
    // Fetch the supported cipher suites from an external API
    char* ciphers = "TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384,TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384";
    return ciphers;
}

// Function to load the configuration data from a JSON or YAML file
void loadConfig(EncryptionConfig* config) {
    // Load the key and certificate files from the configuration file
    config->key_file = "path/to/key.pem";
    config->cert_file = "path/to/certificate.pem";

    // Fetch the supported cipher suites from an external API and add them to the configuration struct
    char* supported_ciphers = getSupportedCiphers();
    config->num_ciphers = 2;
    strcpy(config->cipher_suites[0], supported_ciphers);
    free(supported_ciphers);
}

// Function to initialize the encryption service with the given configuration data
void initEncryptionService(EncryptionConfig* config) {
    // Initialize the OpenSSL library
    initOpenSSL();

    // Load the key and certificate files from the configuration file
    SSL_CTX* ctx = SSL_CTX_new(TLSv1_2_client_method());
    SSL_CTX_use_certificate_file(ctx, config->cert_file, SSL_FILETYPE_PEM);
    SSL_CTX_use_privatekey_file(ctx, config->key_file, SSL_FILETYPE_PEM);

    // Set the cipher suites for the encryption service
    SSL_CTX_set_ciphersuites(ctx, config->num_ciphers, config->cipher_suites);
}

// Function to encrypt data using the encryption service
void encryptData(EncryptionConfig* config, char* plaintext) {
    // Create a new SSL object
    SSL* ssl = SSL_new(config->ctx);

    // Set the cipher suite for the SSL object
    SSL_set_ciphersuites(ssl, config->num_ciphers, config->cipher_suites);

    // Encrypt the plaintext using the encryption service
    char* encrypted = SSL_encrypt(ssl, plaintext);

    // Clean up the SSL object
    SSL_free(ssl);

    return encrypted;
}

// Function to decrypt data using the encryption service
void decryptData(EncryptionConfig* config, char* ciphertext) {
    // Create a new SSL object
    SSL* ssl = SSL_new(config->ctx);

    // Set the cipher suite for the SSL object
    SSL_set_ciphersuites(ssl, config->num_ciphers, config->cipher_suites);

    // Decrypt the ciphertext using the encryption service
    char* plaintext = SSL_decrypt(ssl, ciphertext);

    // Clean up the SSL object
    SSL_free(ssl);

    return plaintext;
}

// Function to handle errors in the encryption service
void handleError(int error) {
    char* error_message = NULL;

    switch (error) {
        case SSL_ERROR_NONE:
            break;
        case SSL_ERROR_SSL:
            error_message = "An error occurred while encrypting/decrypting data.";
            break;
        default:
            error_message = "An unknown error occurred.";
    }

    if (error_message != NULL) {
        fprintf(stderr, "%s\n", error_message);
    }
}

// Function to reload the cipher suites when updates are detected
void reloadCiphers() {
    EncryptionConfig* config = malloc(sizeof(EncryptionConfig));

    // Load the configuration data from the JSON or YAML file
    loadConfig(config);

    // Initialize the encryption service with the new configuration data
    initEncryptionService(config);
}

// Function to monitor and respond to anomalies in real-time
void monitorAnomalies() {
    while (1) {
        // Monitor the system for anomalies

        // If an anomaly is detected, handle it appropriately
        handleError(anomaly);
    }
}

// Function to optimize resource usage by leveraging multi-threading and asynchronous I/O operations
void optimizeResourceUsage() {
    while (1) {
        // Optimize the resource usage of the encryption service

        // If the optimization fails, handle it appropriately
        handleError(optimization_error);
    }
}
