    pthread_mutex_init(&job_queue->mutex, NULL);
    semaphore_init(&job_queue->semaphore, 0);
    memset(job_queue->jobs, 0, sizeof(struct Job*) * MAX_JOBS);
    job_queue->num_jobs = 0;
}

void initConnectionPool(struct ConnectionPool* conn_pool) {
    pthread_mutex_init(&conn_pool->mutex, NULL);
    semaphore_init(&conn_pool->semaphore, 0);
    memset(conn_pool->connections, 0, sizeof(struct Connection*) * MAX_CONNECTIONS);
    conn_pool->num_connections = 0;
}

void addJobToQueue(struct JobQueue* job_queue, struct Job* job) {
    pthread_mutex_lock(&job_queue->mutex);
    job_queue->jobs[job_queue->num_jobs++] = job;
    semaphore_post(&job_queue->semaphore);
    pthread_mutex_unlock(&job_queue->mutex);
}

struct Job* getJobFromQueue(struct JobQueue* job_queue) {
    struct Job* job = NULL;
    pthread_mutex_lock(&job_queue->mutex);
    if (job_queue->num_jobs > 0) {
        job = job_queue->jobs[0];
        memmove(job_queue->jobs, job_queue->jobs + 1, sizeof(struct Job*) * (MAX_JOBS - 1));
        --job_queue->num_jobs;
    }
    pthread_mutex_unlock(&job_queue->mutex);
    return job;
}

void removeJobFromQueue(struct JobQueue* job_queue, struct Job* job) {
    pthread_mutex_lock(&job_queue->mutex);
    for (int i = 0; i < job_queue->num_jobs; ++i) {
        if (job_queue->jobs[i] == job) {
            memmove(job_queue->jobs + i, job_queue->jobs + i + 1, sizeof(struct Job*) * (MAX_JOBS - i));
            --job_queue->num_jobs;
            break;
        }
    }
    pthread_mutex_unlock(&job_queue->mutex);
}

void addConnectionToPool(struct ConnectionPool* conn_pool, struct Connection* connection) {
    pthread_mutex_lock(&conn_pool->mutex);
    if (conn_pool->num_connections < MAX_CONNECTIONS) {
        conn_pool->connections[conn_pool->num_connections++] = connection;
    }
    pthread_mutex_unlock(&conn_pool->mutex);
}

struct Connection* getConnectionFromPool(struct ConnectionPool* conn_pool) {
    struct Connection* connection = NULL;
    pthread_mutex_lock(&conn_pool->mutex);
    if (conn_pool->num_connections > 0) {
        connection = conn_pool->connections[0];
        memmove(conn_pool->connections, conn_pool->connections + 1, sizeof(struct Connection*) * (MAX_CONNECTIONS - 1));
        --conn_pool->num_connections;
    }
    pthread_mutex_unlock(&conn_pool->mutex);
    return connection;
}

void removeConnectionFromPool(struct ConnectionPool* conn_pool, struct Connection* connection) {
    pthread_mutex_lock(&conn_pool->mutex);
    for (int i = 0; i < conn_pool->num_connections; ++i) {
        if (conn_pool->connections[i] == connection) {
            memmove(conn_pool->connections + i, conn_pool->connections + i + 1, sizeof(struct Connection*) * (MAX_CONNECTIONS - i));
            --conn_pool->num_connections;
            break;
        }
    }
    pthread_mutex_unlock(&conn_pool->mutex);
}

void initResourceUtilization(struct ResourceUtilization* util) {
    memset(util, 0, sizeof(*util));
}

void addResourceUtilization(struct ResourceUtilization* util, float usage) {
    pthread_mutex_lock(&util->mutex);
    if (util->num_samples < MAX_SAMPLES) {
        util->usage[util->num_samples++] = usage;
    }
    else {
        memmove(util->usage, util->usage + 1, sizeof(float) * (MAX_SAMPLES - 1));
        util->usage[MAX_SAMPLES - 1] = usage;
    }
    pthread_mutex_unlock(&util->mutex);
}

float getResourceUtilization(struct ResourceUtilization* util) {
    float usage = 0;
    pthread_mutex_lock(&util->mutex);
    for (int i = 0; i < util->num_samples; ++i) {
        usage += util->usage[i];
    }
    usage /= util->num_samples;
    pthread_mutex_unlock(&util->mutex);
    return usage;
}

void initJobStatus(struct JobStatus* status) {
    memset(status, 0, sizeof(*status));
}

void setJobStatus(struct JobStatus* status, int status_code, char* error_message) {
    pthread_mutex_lock(&status->mutex);
    status->status = status_code;
    if (error_message != NULL) {
        status->error_message = strdup(error_message);
    }
    else {
        status->error_message = NULL;
    }
    pthread_mutex_unlock(&status->mutex);
}

int getJobStatusCode(struct JobStatus* status) {
    int code = 0;
    pthread_mutex_lock(&status->mutex);
    code = status->status;
    pthread_mutex_unlock(&status->mutex);
    return code;
}

char* getJobErrorMessage(struct JobStatus* status) {
    char* message = NULL;
    pthread_mutex_lock(&status->mutex);
    if (status->error_message != NULL) {
        message = strdup(status->error_message);
    }
    pthread_mutex_unlock(&status->mutex);
    return message;
}
