class DBConnectionPool {
public:
    // Constructor
    DBConnectionPool(int numConnections) : connections_(numConnections) {}

    // Get a connection from the pool
    void getConnection(const std::string& dbName, int connID) {
        // Check if there are available connections in the pool
        if (connections_.empty()) {
            // If not, create a new connection and add it to the pool
            connections_.push_back(new DBConnection(dbName, connID));
        } else {
            // If there are available connections, get one from the pool
            auto conn = connections_.front();
            connections_.pop_front();
            conn->connect(dbName, connID);
        }
    }

    // Return a connection to the pool
    void returnConnection(DBConnection* conn) {
        // Check if the connection is still valid
        if (conn->isValid()) {
            // If so, add it back to the pool
            connections_.push_back(conn);
        } else {
            // If not, delete the connection
