    // Set the ciphertext in the encryption context structure
    ec->ciphertext = ciphertext;

    return true;
}

// Function for decrypting data with KMS
bool kms_decrypt(struct kms_client *ctx, struct encryption_context *ec) {
    // Set the plaintext and ciphertext buffers
    Aws::Utils::ByteBuffer plaintext = ec->plaintext;
    Aws::Utils::ByteBuffer ciphertext = ec->ciphertext;

    // Decrypt the ciphertext using KMS
    auto decrypt_outcome = ctx->client->Decrypt(Aws::KMS::Model::DecryptRequest().WithKeyId("your_key_id").WithCiphertextBlob(ciphertext).WithEncryptionAlgorithm(Aws::KMS::Model::EncryptionAlgorithmSpec::SYMMETRIC_DEFAULT));
