  const query = req.query;
  const symbol = query.symbol;
  const cacheKey = `market-data:${symbol}`;
  const cachedValue = app.get('cache').get(cacheKey);
  if (cachedValue) {
    res.send(cachedValue);
  } else {
    axios.get(`https://api.example.com/market-data?symbol=${symbol}`)
