#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <json/json.h>
#include <memory>
#include <thread>
#include <future>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

struct AccessToken {
    string token;
    int expiresIn;
};

class AccessTokenManager {
private:
    atomic<bool> running;
    mutex mtx;
    condition_variable cv;
    thread* workerThread;
    vector<AccessToken> tokens;
    map<string, AccessToken> tokenMap;

public:
    AccessTokenManager() {
        running = false;
        workerThread = nullptr;
    }

    ~AccessTokenManager() {
        stop();
    }

    void start(int threadCount) {
        if (running.exchange(true)) {
            return;
        }

        workerThread = new thread([this, threadCount]() {
            while (running) {
                unique_lock<mutex> lck(mtx);
                cv.wait(lck, [this] { return !tokens.empty(); });

                vector<AccessToken> tokenBatch;
                tokenBatch.reserve(threadCount);

                for (int i = 0; i < threadCount && !tokens.empty(); i++) {
                    AccessToken token = tokens.back();
                    tokens.pop_back();
                    tokenBatch.push_back(token);
                }

                for (auto& token : tokenBatch) {
                    handleAccessToken(token);
                }
            }
        });
    }

    void stop() {
        if (!running.exchange(false)) {
            return;
        }

        cv.notify_all();
        workerThread->join();
        delete workerThread;
    }

    void addAccessToken(string token, int expiresIn) {
        unique_lock<mutex> lck(mtx);
        tokens.push_back({token, expiresIn});
        cv.notify_one();
    }

    AccessToken getAccessToken() {
        unique_lock<mutex> lck(mtx);
        while (tokens.empty()) {
            cv.wait(lck);
        }

        AccessToken token = tokens.back();
        tokens.pop_back();
        return token;
    }

private:
    void handleAccessToken(AccessToken& token) {
        // Validate and process the access token here
        cout << "Received access token: " << token.token << endl;
    }
};

int main() {
    AccessTokenManager manager;
    manager.start(4);

    for (int i = 0; i < 100; i++) {
        string token = "token" + to_string(i);
        int expiresIn = i * 60;
        manager.addAccessToken(token, expiresIn);
    }

    while (manager.running) {
        this_thread::sleep_for(chrono::seconds(1));
    }

    return 0;
}']

['#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <stdint.h>

#define MAX_UE_COUNT 1000000
#define MAX_SR_COUNT 1000000
#define MAX_QUEUE_SIZE 10000
#define DEFAULT_TIMEOUT 5

struct UE {
    int id;
    uint64_t srn;
};

struct SR {
    int id;
    struct timespec timestamp;
    struct in_addr addr;
};

struct QueueNode {
    struct SR sr;
    struct QueueNode* next;
};

struct Queue {
    struct QueueNode* head;
    struct QueueNode* tail;
};

// Global variables
int ue_count = 0;
int sr_count = 0;
struct UE* ues[MAX_UE_COUNT];
struct SR* srs[MAX_SR_COUNT];
struct Queue queues[MAX_QUEUE_SIZE];
pthread_mutex_t mutex;
pthread_cond_t cond;
uint64_t last_srn = 0;
int timeout = DEFAULT_TIMEOUT;

// Function prototypes
void* ue_manager(void*);
void* sr_manager(void*);
void process_sr(struct SR*);
void add_ue(int, uint64_t);
void remove_ue(int);
void add_sr(struct SR*);
void remove_sr(int);
void print_ues();
void print_srs();
void print_queue(struct Queue*);

// Main function
int main() {
    // Initialize variables and data structures
    for (int i = 0; i < MAX_UE_COUNT; i++) {
        ues[i] = NULL;
    }
    for (int i = 0; i < MAX_SR_COUNT; i++) {
        srs[i] = NULL;
    }
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);
    // Create thread for each UE manager and SR manager
    int num_threads = 10;
    pthread_t ue_managers[num_threads];
    pthread_t sr_managers[num_threads];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&ue_managers[i], NULL, ue_manager, NULL) != 0) {
            perror("Error creating UE manager thread");
        }
        if (pthread_create(&sr_managers[i], NULL, sr_manager, NULL) != 0) {
            perror("Error creating SR manager thread");
        }
    }
    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(ue_managers[i], NULL) != 0) {
            perror("Error joining UE manager thread");
        }
        if (pthread_join(sr_managers[i], NULL) != 0) {
            perror("Error joining SR manager thread");
        }
    }
    // Clean up
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
    return 0;
}

// Thread function for managing UEs
void* ue_manager(void* args) {
    while (1) {
        // Wait for a new UE to be added
        pthread_mutex_lock(&mutex);
        while (ue_count == 0) {
            pthread_cond_wait(&cond, &mutex);
        }
        int id = ues[0]->id;
        // Remove the first UE from the list
        struct UE* temp = ues[0];
        for (int i = 1; i < ue_count; i++) {
            ues[i - 1] = ues[i];
        }
        ue_count--;
        // Unlock the mutex and notify all other UEs to wake up
        pthread_cond_broadcast(&cond);
        pthread_mutex_unlock(&mutex);
        // Process the UE
        printf("UE %d: Removed from queue\n", id);
    }
}

// Thread function for managing SRs
void* sr_manager(void* args) {
    while (1) {
        // Wait for a new SR to be added
        pthread_mutex_lock(&mutex);
        while (sr_count == 0) {
            pthread_cond_wait(&cond, &mutex);
        }
        int id = srs[0]->id;
        // Remove the first SR from the list
        struct SR* temp = srs[0];
        for (int i = 1; i < sr_count; i++) {
            srs[i - 1] = srs[i];
        }
        sr_count--;
        // Unlock the mutex and notify all other UEs to wake up
        pthread_cond_broadcast(&cond);
        pthread_mutex_unlock(&mutex);
        // Process the SR
        printf("SR %d: Removed from queue\n", id);
    }
}

// Function for processing a new SR
void process_sr(struct SR* sr) {
    int id = sr->id;
    printf("SR %d: Added to queue\n", id);
    // Add the SR to the appropriate queue
    struct Queue* temp = &queues[id];
    temp->head = sr;
    temp->tail = sr;
    temp->count++;
}

// Function for adding a new UE to the system
void add_ue(int id, uint64_t srn) {
    // Lock the mutex and wait for all other UEs to finish processing their SRs
    pthread_mutex_lock(&mutex);
    while (ue_count != 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    // Add the new UE to the list and notify all other threads to wake up
    ues[ue_count] = malloc(sizeof(struct UE));
    ues[ue_count]->id = id;
    ue_count++;
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&mutex);
}

// Function for removing an existing UE from the system
void remove_ue(int id) {
    // Lock the mutex and wait until all other UEs have finished processing their SRs
    pthread_mutex_lock(&mutex);
    while (ue_count != 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    // Remove the UE from the list and notify all other threads to wake up
    for (int i = 0; i < ue_count; i++) {
        if (ues[i]->id == id) {
            struct UE* temp = ues[i];
            for (int j = i + 1; j < ue_count; j++) {
                ues[j - 1] = ues[j];
            }
            ue_count--;
            free(temp);
        }
    }
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&mutex);
}

// Function for adding a new SR to the system
void add_sr(struct SR* sr) {
    // Lock the mutex and wait until all other UEs have finished processing their SRs
    pthread_mutex_lock(&mutex);
    while (ue_count != 0 || sr_count != 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    // Add the new SR to the list and notify all other threads to wake up
    srs[sr_count] = malloc(sizeof(struct SR));
    srs[sr_count]->id = sr->id;
    srs[sr_count]->srn = sr->srn;
    srs[sr_count]->count++;
    sr_count++;
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&mutex);
}

// Function for removing an existing SR from the system
void remove_sr(int id) {
    // Lock the mutex and wait until all other UEs have finished processing their SRs
    pthread_mutex_lock(&mutex);
    while (ue_count != 0 || sr_count != 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    // Remove the SR from the list and notify all other threads to wake up
    for (int i = 0; i < sr_count; i++) {
        if (srs[i]->id == id) {
            struct SR* temp = srs[i];
            for (int j = i + 1; j < sr_count; j++) {
                srs[j - 1] = srs[j];
            }
            sr_count--;
            free(temp);
        }
    }
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&mutex);
}

// Function for printing the list of UEs
void print_ues() {
    // Lock the mutex and wait until all other threads have finished processing their SRs
    pthread_mutex_lock(&mutex);
    while (ue_count != 0 || sr_count != 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    // Print the list of UEs
    printf("List of UEs: \n");
    for (int i = 0; i < ue_count; i++) {
        struct UE* temp = ues[i];
        printf("%d ", temp->id);
    }
    printf("\n");
    pthread_mutex_unlock(&mutex);
}

// Function for printing the list of SRs
void print_srs() {
    // Lock the mutex and wait until all other threads have finished processing their SRs
    pthread_mutex_lock(&mutex);
    while (ue_count != 0 || sr_count != 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    // Print the list of SRs
    printf("List of SRs: \n");
    for (int i = 0; i < sr_count; i++) {
        struct SR* temp = srs[i];
        printf("%d %llu ", temp->id, temp->srn);
    }
    printf("\n");
    pthread_mutex_unlock(&mutex);
}
