using namespace std;

// Grid telemetry data structure
struct GRID_TElemetry_PDU_T {
    int timestamp;
    double voltage;
    double current;
    double power;
};

// MQTT client instance
mqtt::client mqttClient;

// JSON serializer instance
json::serializer jsonSerializer;

// Thread-safe queue for storing grid data to be published
std::queue<GRID_TElemetry_PDU_T> gridDataQueue;

// Mutex and condition variable for synchronizing access to the queue
std::mutex queueMutex;
std::condition_variable queueCondition;

void publishGridDataToMqttBroker() {
    // Connect to MQTT broker
    mqttClient.connect("tcp://localhost:1883");

    // Subscribe to MQTT topic for grid data
    mqttClient.subscribe("grid/data", [](const std::string& topic, const std::string& message) {
        GRID_TElemetry_PDU_T pdu;
        jsonSerializer.fromJSON(message, &pdu);
        // Handle incoming grid data
    });

    // Publish grid data to MQTT broker
    while (true) {
        std::unique_lock<std::mutex> lock(queueMutex);
        while (gridDataQueue.empty()) {
            queueCondition.wait(lock);
        }
        GRID_TElemetry_PDU_T pdu = gridDataQueue.front();
        gridDataQueue.pop();
        lock.unlock();

        std::string message;
        jsonSerializer.toJSON(&pdu, &message);
        mqttClient.publish("grid/data", message);
    }
}

int main() {
    // Initialize MQTT client and JSON serializer
    mqttClient.init();
    jsonSerializer.init();

    // Start publisher thread for grid data to MQTT broker
    std::thread publishThread(publishGridDataToMqttBroker);

    // Sample grid telemetry data structure
    GRID_TElemetry_PDU_T pdu;
    pdu.timestamp = 1643275900;
    pdu.voltage = 230;
    pdu.current = 10;
    pdu.power = 2300;

    // Enqueue grid data for publication to MQTT broker
    std::unique_lock<std::mutex> lock(queueMutex);
    gridDataQueue.push(pdu);
    queueCondition.notify_one();
    lock.unlock();

    // Wait for publisher thread to exit
    publishThread.join();

    return 0;
}
